69: /**
70:  * Class to display a UML note in a diagram
71:  * Since we don't need stereotypes for the note and an
72:  * empty stereotype textfield causes problems with the
73:  * note layout, I subclass FigNode instead of FigNodeModelElement.
74:  */
75: public class FigComment
76:     extends FigNodeModelElement
77:     implements VetoableChangeListener,
78: 	       DelayedVChangeListener,
79: 	       MouseListener,
80: 	       KeyListener,
81: 	       PropertyChangeListener
82: {
83:     protected static Logger cat = Logger.getLogger(FigComment.class);
84: 
85:     ////////////////////////////////////////////////////////////////
86:     // constants
87: 
88:     // public final int MARGIN = 2;
89:     public int x = 0;
90:     public int y = 0;
91:     public int width = 80;
92:     public int height = 60;
93:     public int gapY = 10;
94: 
95:     protected boolean _readyToEdit = true;
96: 
97:     public static Font LABEL_FONT;
98:     public static Font ITALIC_LABEL_FONT;
99:     public final int MARGIN = 2;
100: 
101:     static {
102:         LABEL_FONT = LookAndFeelMgr.getInstance().getSmallFont();
103:         ITALIC_LABEL_FONT = new Font(LABEL_FONT.getFamily(),
104: 				     Font.ITALIC,
105: 				     LABEL_FONT.getSize());
106:     }
107: 
108:     ////////////////////////////////////////////////////////////////
109:     // instance variables
110: 
111:     // The model element the note is attached to.
112:     private Object _noteOwner = null;
113: 
114:     // The figure that holds the text of the note.
115:     FigText _text;
116: 
117:     FigPoly _body;
118:     FigPoly _urCorner;
119: 
120:     ////////////////////////////////////////////////////////////////
121:     // constructors
122: 
123:     public FigComment() {
124:         _body = new FigPoly(Color.black, Color.white);
125:         _body.addPoint(x, y);
126:         _body.addPoint(x + width - 1 - gapY, y);
127:         _body.addPoint(x + width - 1, y + gapY);
128:         _body.addPoint(x + width - 1, y + height - 1);
129:         _body.addPoint(x, y + height - 1);
130:         _body.addPoint(x, y);
131:         _body.setFilled(true);
132:         _body.setLineWidth(1);
133: 
134:         _urCorner = new FigPoly(Color.black, Color.white);
135:         _urCorner.addPoint(x + width - 1 - gapY, y);
136:         _urCorner.addPoint(x + width - 1, y + gapY);
137:         _urCorner.addPoint(x + width - 1 - gapY, y + gapY);
138:         _urCorner.addPoint(x + width - 1 - gapY, y);
139:         _urCorner.setFilled(true);
140:         _urCorner.setLineWidth(1);
141: 
142:         setBigPort(new FigRect(x, y, width, height, null, null));
143:         getBigPort().setFilled(false);
144:         getBigPort().setLineWidth(0);
145: 
146:         _text = new FigText(2, 2, width - 2 - gapY, height - 4, true);
147:         _text.setFont(LABEL_FONT);
148:         _text.setTextColor(Color.black);
149:         _text.setMultiLine(true);
150:         _text.setAllowsTab(false);
151:         // _text.setText(placeString());
152:         _text.setJustification(FigText.JUSTIFY_LEFT);
153:         _text.setFilled(false);
154:         _text.setLineWidth(0);
155:         //_text.setLineColor(Color.white);
156: 
157:         // add Figs to the FigNode in back-to-front order
158:         addFig(getBigPort());
159:         addFig(_body);
160:         addFig(_urCorner);
161:         addFig(_text);
162: 
163:         setBlinkPorts(false); //make port invisble unless mouse enters
164:         Rectangle r = getBounds();
165:         setBounds(r.x, r.y, r.width, r.height);
166:         updateEdges();
167: 
168:         _readyToEdit = false;
169:     }
170: 
171:     /**
172:      * Construct a new note
173:      *
174:      * @param gm The graphmodel
175:      * @param node The underlying MComment node
176:      */
177:     public FigComment(GraphModel gm, Object node) {
178:         this();
179:         setOwner(node);
180:     }
181: 
182:     /**
183:      * Create a note for a given model element.
184:      * @deprecated as of 0.17.1 nobody should use this constructor since it not only constructs
185:      * the fig but also the model behind it. That should not be done by a fig which is only a view to the model
186:      * @param element The annotated model element.
187:      */
188:     public FigComment(Object element) {
189:         this(); // Construct the figure.
190: 
191:         if(!ModelFacade.isAModelElement(element)){
192:             throw new IllegalArgumentException();
193:         }
194: 
195: 	// Create a new Comment node.
196:         Object comment =
197: 	    UmlFactory.getFactory().getCore().createComment();
198:         setOwner(comment); // Set it as the owner of the figure.
199: 	// Tell the annotated element, that it has a comment now.
200:         ModelFacade.addComment(element, comment);
201: 
202:         // Notes in statechart diagrams need a special treatment, cause
203:         // the nodes in them don't necessary have a namespace, where
204:         // we could add the note. So I added this hack... :-(
205:         // Andreas Rueckert <a_rueckert@gmx.net>
206:         if (ModelFacade.isAStateVertex(element)) {
207: 
208: 	    // If the current target is a statechart diagram, we have to
209: 	    // check, if we are editing the diagram.
210:             ProjectBrowser pb = ProjectBrowser.getInstance(); 
211:             if (TargetManager.getInstance().getTarget() instanceof UMLStateDiagram) { 
212:                 StateDiagramGraphModel gm =
213: 		    (StateDiagramGraphModel)
214: 		    (((UMLStateDiagram) TargetManager.getInstance().getTarget()).getGraphModel());
215: 		// We are editing, so we set the Namespace directly.
216:                 ModelFacade.setNamespace(comment, gm.getNamespace());
217:             }
218:         } else {
219: 	    // Add the comment to the same namespace as the annotated element.
220:             ModelFacade.setNamespace(comment, ModelFacade.getNamespace(element));
221:         }
222: 
223:         storeNote(placeString()); // Set the default text for this figure type.
224:     }
225: 
226:     /**
227:      * Get the default text for this figure.
228:      *
229:      * @return The default text for this figure.
230:      */
231:     public String placeString() {
232:         String placeString = retrieveNote();
233:         if (placeString == null)
234:             placeString = "new note";
235:         return placeString;
236:     }
237: 
238:     /**
239:      * Clone this figure.
240:      *
241:      * @return The cloned figure.
242:      */
243:     public Object clone() {
244:         FigComment figClone = (FigComment) super.clone();
245:         Iterator it = figClone.getFigs(null).iterator();
246:         figClone.setBigPort((FigRect) it.next());
247:         figClone._body = (FigPoly) it.next();
248:         figClone._urCorner = (FigPoly) it.next();
249:         figClone._text = (FigText) it.next();
250:         return figClone;
251:     }
252: 
253:     ////////////////////////////////////////////////////////////////
254:     // event handlers
255: 
256:     /**
257:      * See FigNodeModelElement.java for more info on these methods.
258:      */
259: 
260:     /** If the user double clicks on any part of this FigNode, pass it
261:      *  down to one of the internal Figs.  This allows the user to
262:      *  initiate direct text editing. */
263:     public void mouseClicked(MouseEvent me) {
264:         if (!_readyToEdit) {
265:             if (org.argouml.model.ModelFacade.isAModelElement(getOwner())) {
266:                 Object own = /*(MModelElement)*/ getOwner();
267:                 _readyToEdit = true;
268:             } else {
269:                 cat.debug("not ready to edit note");
270:                 return;
271:             }
272:         }
273:         if (me.isConsumed())
274:             return;
275:         if (me.getClickCount() >= 2
276: 	    && !(me.isPopupTrigger()
277: 		 || me.getModifiers() == InputEvent.BUTTON3_MASK))
278: 	{
279:             if (getOwner() == null)
280:                 return;
281:             Fig f = hitFig(new Rectangle(me.getX() - 2, me.getY() - 2, 4, 4));
282:             if (f instanceof MouseListener)
283:                  ((MouseListener) f).mouseClicked(me);
284:         }
285:         me.consume();
286:     }
287: 
288:     public void vetoableChange(PropertyChangeEvent pce) {
289:         Object src = pce.getSource();
290:         if (src == getOwner()) {
291:             DelayedChangeNotify delayedNotify =
292: 		new DelayedChangeNotify(this, pce);
293:             SwingUtilities.invokeLater(delayedNotify);
294:         } else
295:             cat.debug("FigNodeModelElement got vetoableChange"
296: 		      + " from non-owner:" + src);
297:     }
298: 
299:     public void delayedVetoableChange(PropertyChangeEvent pce) {
300:         Object src = pce.getSource();
301:         // update any text, colors, fonts, etc.
302:         renderingChanged();
303:         // update the relative sizes and positions of internel Figs
304:         endTrans();
305:     }
306: 
307:     public void propertyChange(PropertyChangeEvent pve) {
308:         Object src = pve.getSource();
309:         String pName = pve.getPropertyName();
310:         if (pName.equals("editing")
311: 	    && Boolean.FALSE.equals(pve.getNewValue()))
312: 	{
313:             try {
314:                 //parse the text that was edited
315:                 textEdited((FigText) src);
316:                 // resize the FigNode to accomodate the new text
317:                 Rectangle bbox = getBounds();
318:                 Dimension minSize = getMinimumSize();
319:                 bbox.width = Math.max(bbox.width, minSize.width);
320:                 bbox.height = Math.max(bbox.height, minSize.height);
321:                 setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
322:                 endTrans();
323:             } catch (PropertyVetoException ex) {
324:                 cat.error("could not parse and use the text entered "
325: 			  + "in figcomment", ex);
326:             }
327:         } else
328:             super.propertyChange(pve);
329:     }
330: 
331:     public void keyPressed(KeyEvent ke) {
332:         if (!_readyToEdit) {
333:             if (org.argouml.model.ModelFacade.isAModelElement(getOwner())) {
334:                 storeNote("");
335:                 _readyToEdit = true;
336:             } else {
337:                 cat.debug("not ready to edit note");
338:                 return;
339:             }
340:         }
341:         if (ke.isConsumed())
342:             return;
343:         if (getOwner() == null)
344:             return;
345:         _text.keyPressed(ke);
346:     }
347: 
348:     /** not used, do nothing. */
349:     public void keyReleased(KeyEvent ke) {
350:     }
351: 
352:     public void keyTyped(KeyEvent ke) {
353:     }
354: 
355:     ////////////////////////////////////////////////////////////////
356:     // Fig accessors
357: 
358:     public void setLineColor(Color col) {
359:         // The _text element has no border, so the line color doesn't matter.
360:         _body.setLineColor(col);
361:         _urCorner.setLineColor(col);
362:     }
363: 
364:     public Color getLineColor() {
365:         return _body.getLineColor();
366:     }
367: 
368:     public void setFillColor(Color col) {
369:         _body.setFillColor(col);
370:         _urCorner.setFillColor(col);
371:     }
372: 
373:     public Color getFillColor() {
374:         return _body.getFillColor();
375:     }
376: 
377:     public void setFilled(boolean f) {
378:         _text.setFilled(false); // The text is always opaque.
379:         _body.setFilled(f);
380:         _urCorner.setFilled(f);
381:     }
382: 
383:     public boolean getFilled() {
384:         return _body.getFilled();
385:     }
386: 
387:     public void setLineWidth(int w) {
388:         _text.setLineWidth(0); // Make a seamless integration of the text
389:         // in the note figure.
390:         _body.setLineWidth(w);
391:         _urCorner.setLineWidth(w);
392:     }
393: 
394:     public int getLineWidth() {
395:         return _body.getLineWidth();
396:     }
397: 
398:     ////////////////////////////////////////////////////////////////
399:     // user interaction methods
400: 
401:     protected void textEdited(FigText ft) throws PropertyVetoException {
402:         if (ft == _text)
403:             storeNote(ft.getText());
404:     }
405: 
406:     public void setEnclosingFig(Fig encloser) {
407:         super.setEnclosingFig(encloser);
408:     }
409: 
410:     ////////////////////////////////////////////////////////////////
411:     // accessor methods
412: 
413:     /**
414:      * Store a note in the associated model element.
415:      *
416:      * @param note The note to store.
417:      */
418:     public final void storeNote(String note) {
419:         if (getOwner() != null)
420:              ModelFacade.setName(getOwner(), note);
421:     }
422: 
423:     /**
424:      * Retrieve the note from the associated model element.
425:      *
426:      * @return The note from the associated model element.
427:      */
428:     public final String retrieveNote() {
429:         return (getOwner() != null)
430: 	    ? org.argouml.model.ModelFacade.getName(getOwner())
431: 	    : null;
432:     }
433: 
434:     public boolean getUseTrapRect() {
435:         return true;
436:     }
437: 
438:     /**
439:      * Get the minimum size for the note figure.
440:      *
441:      * @return The minimum size for the note figure.
442:      */
443:     public Dimension getMinimumSize() {
444: 
445:         // Get the size of the text field.
446:         Dimension textMinimumSize = _text.getMinimumSize();
447: 
448:         // And add the gaps around the textfield to get the minimum
449:         // size of the note.
450:         return new Dimension(textMinimumSize.width + 4 + gapY,
451: 			     textMinimumSize.height + 4);
452:     }
453: 
454:     public void setBounds(int px, int y, int w, int h) {
455:         if (_text == null)
456:             return;
457: 
458:         Rectangle oldBounds = getBounds();
459: 
460:         // Resize the text figure
461:         _text.setBounds(px + 2, y + 2, w - 4 - gapY, h - 4);
462: 
463:         // Resize the big port around the figure
464:         getBigPort().setBounds(px, y, w, h);
465: 
466:         // Since this is a complex polygon, there's no easy way to resize it.
467:         Polygon newPoly = new Polygon();
468:         newPoly.addPoint(px, y);
469:         newPoly.addPoint(px + w - 1 - gapY, y);
470:         newPoly.addPoint(px + w - 1, y + gapY);
471:         newPoly.addPoint(px + w - 1, y + h - 1);
472:         newPoly.addPoint(px, y + h - 1);
473:         newPoly.addPoint(px, y);
474:         _body.setPolygon(newPoly);
475: 
476:         // Just move the corner to it's new position.
477:         _urCorner.setBounds(px + w - 1 - gapY, y, gapY, gapY);
478: 
479:         calcBounds(); //_x = x; _y = y; _w = w; _h = h;
480:         firePropChange("bounds", oldBounds, getBounds());
481:     }
482: 
483:     protected void updateBounds() {
484:         Rectangle bbox = getBounds();
485:         Dimension minSize = getMinimumSize();
486:         bbox.width = Math.max(bbox.width, minSize.width);
487:         bbox.height = Math.max(bbox.height, minSize.height);
488:         setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
489:     }
490: 
491:     ///////////////////////////////////////////////////////////////////
492:     // Internal methods
493: 
494:     /**
495:      * This is called aftern any part of the UML MModelElement has
496:      * changed. This method automatically updates the note FigText.
497:      */
498:     protected final void modelChanged(MElementEvent mee) {
499:         super.modelChanged(mee);
500: 
501:         String noteStr = retrieveNote();
502:         if (noteStr != null)
503:             _text.setText(noteStr);
504: 
505:     }
506: 
507:     /**
508:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateNameText()
509:      */
510:     protected void updateNameText() {
511:         if (getOwner() != null) {
512:             String text = org.argouml.model.ModelFacade.getName(getOwner());
513:             if (text != null) {
514:                 _text.setText(text);
515:                 calcBounds();
516:                 setBounds(getBounds());
517:             }
518:         }
519:     }
520: 
521: } /* end class FigComment */

