38: /**
39:  * Class that represents the clarifier (red wavy line)
40:  * for a attribute compartment.
41:  *
42:  */
43: public class ClAttributeCompartment implements Clarifier {
44: 
45:     private static final Logger LOG =
46: 	Logger.getLogger(ClAttributeCompartment.class);
47: 
48:     private static ClAttributeCompartment theInstance =
49: 	new ClAttributeCompartment();
50: 
51:     private static final int WAVE_LENGTH = 4;
52:     private static final int WAVE_HEIGHT = 2;
53: 
54:     ////////////////////////////////////////////////////////////////
55:     // instance variables
56:     private Fig fig;
57: 
58:     /**
59:      * @see org.argouml.ui.Clarifier#setFig(org.tigris.gef.presentation.Fig)
60:      */
61:     public void setFig(Fig f) { fig = f; }
62: 
63:     /**
64:      * @see org.argouml.ui.Clarifier#setToDoItem(org.argouml.cognitive.ToDoItem)
65:      */
66:     public void setToDoItem(ToDoItem i) { }
67: 
68:     /**
69:      * @see javax.swing.Icon#paintIcon(java.awt.Component, java.awt.Graphics,
70:      * int, int)
71:      */
72:     public void paintIcon(Component c, Graphics g, int x, int y) {
73: 	if (fig instanceof AttributesCompartmentContainer) {
74: 	    AttributesCompartmentContainer fc =
75: 	        (AttributesCompartmentContainer) fig;
76: 
77: 	    // added by Eric Lefevre 13 Mar 1999: we must check if the
78: 	    // FigText for attributes is drawn before drawing things
79: 	    // over it
80: 	    if (!fc.isAttributesVisible()) {
81: 		fig = null;
82: 		return;
83: 	    }
84: 
85: 	    FigGroup fr = fc.getAttributesFig();
86: 	    int left  = fr.getX() + 6;
87: 	    int height = fr.getY() + fr.getHeight() - 5;
88: 	    int right = fr.getX() + fr.getWidth() - 6;
89: 	    g.setColor(Color.red);
90: 	    int i = left;
91: 	    while (true) {
92: 		g.drawLine(i, height, i + WAVE_LENGTH, height + WAVE_HEIGHT);
93: 		i += WAVE_LENGTH;
94: 		if (i >= right) break;
95: 		g.drawLine(i, height + WAVE_HEIGHT, i + WAVE_LENGTH, height);
96: 		i += WAVE_LENGTH;
97: 		if (i >= right) break;
98: 		g.drawLine(i, height, i + WAVE_LENGTH,
99: 			   height + WAVE_HEIGHT / 2);
100: 		i += WAVE_LENGTH;
101: 		if (i >= right) break;
102: 		g.drawLine(i, height + WAVE_HEIGHT / 2, i + WAVE_LENGTH,
103: 			   height);
104: 		i += WAVE_LENGTH;
105: 		if (i >= right) break;
106: 	    }
107: 	    fig = null;
108: 	}
109:     }
