32: import org.argouml.uml.reveng.DiagramInterface;
33: import org.argouml.uml.ui.UMLAction;
34: 
35: import org.tigris.gef.base.Globals;
36: 
37: /**
38:  * ActionAddAllClassesFromModel enables pasting of an existing node into a 
39:  * Diagram.
40:  *
41:  * @author Timothy M. Lebo (Oct 2003)
42:  * Smart Information Flow Technologies.
43:  */
44: public class ActionAddAllClassesFromModel extends UMLAction {
45: 
46:     // Instance Variables
47:     private String name;
48:     private Object targetDiagram;
49: 
50:     /**
51:      * Constructor
52:      *
53:      * @param myTabName the name of the tab
54:      */
55:     public ActionAddAllClassesFromModel(String myTabName) {
56:         super(myTabName, NO_ICON);
57:         name = myTabName;
58:     }
59: 
60:     /**
61:      * Constructor
62:      *
63:      * @param name the name of the tab
64:      * @param o the Diagram
65:      */
66:     public ActionAddAllClassesFromModel(String name, Object o) {
67:         super(name, NO_ICON);
68:         this.name = name;
69:         targetDiagram = o;
70:     }
71: 
72:     /**
73:      * shouldBeEnabled
74:      *
75:      * Returns true if this popup menu item should be enabled, false
76:      * if it should be grayed out.
77:      *
78:      * @author Timothy M. Lebo (Oct 2003)
79:      * Smart Information Flow Technologies.
80:      *
81:      * @see org.argouml.uml.ui.UMLAction#shouldBeEnabled()
82:      */
83:     public boolean shouldBeEnabled() {	
84: 	return targetDiagram instanceof UMLClassDiagram;
85:     }
86: 
87:     /**
88:      * actionPerformed
89:      *
90:      * Finds all of the classes within the same namespace as the
91:      * UMLClassDiagram that was given to me in my constructor and adds
92:      * them to the UMLClassDiagram.
93:      *
94:      * @param ae - the ActionEvent
95:      *
96:      * @author Timothy M. Lebo (Oct 2003)
97:      * Smart Information Flow Technologies.
98:      */
99:     public void actionPerformed(ActionEvent ae) {
100: 
101: 	if ( targetDiagram instanceof UMLClassDiagram ) {
102: 
103: 	    // Use DiagramInterface to add classes to diagram
104: 	    DiagramInterface diagram =
105: 		new DiagramInterface( Globals.curEditor() );
106: 	    diagram.setCurrentDiagram( (UMLClassDiagram) targetDiagram);
107: 
108: 	    Object namespace = ((UMLClassDiagram) targetDiagram).getNamespace();
109: 	    Iterator elements =
110: 		ModelFacade.getOwnedElements( namespace ).iterator();
111: 	    while ( elements.hasNext() ) {
112: 		Object element = elements.next();
113: 		if ( ModelFacade.isAClass(element) ) {
114: 		    diagram.addClass( element , false );
115: 		}
116: 	    }
117: 	}
118:     }
119: 
120: } // ActionAddAllClassesFromModel
