45: /** Class to display graphics for a UML State in a diagram. */
46: 
47: public class FigNote extends FigNode
48: implements VetoableChangeListener, DelayedVetoableChangeListener {
49: 
50:   ////////////////////////////////////////////////////////////////
51:   // constants
52: 
53:   public final int MARGIN = 2;
54: 
55:   ////////////////////////////////////////////////////////////////
56:   // instance variables
57: 
58:   /** The main label on this icon. */
59:   FigText _name;
60: 
61:   /** UML does not really use ports, so just define one big one so
62:    *  that users can drag edges to or from any point in the icon. */
63: 
64:   FigRect _bigPort;
65: 
66:   // add other Figs here aes needed
67: 
68: 
69:   ////////////////////////////////////////////////////////////////
70:   // constructors
71: 
72:   public FigNote(GraphModel gm, Object node) {
73:     super(node);
74:     // if it is a UML meta-model object, register interest in any change events
75:     if (node instanceof ElementImpl)
76:       ((ElementImpl)node).addVetoableChangeListener(this);
77: 
78:     Color handleColor = Globals.getPrefs().getHandleColor();
79:     _bigPort = new FigRect(10, 10, 90, 20, handleColor, Color.lightGray);
80:     _name = new FigText(10,10,90,20, Color.blue, "Times", 10);
81:     _name.setExpandOnly(true);
82:     _name.setText("FigNode");
83:     // initialize any other Figs here
84: 
85:     // add Figs to the FigNode in back-to-front order
86:     addFig(_bigPort);
87:     addFig(_name);
88: 
89: 
90:     Object onlyPort = node;
91:     bindPort(onlyPort, _bigPort);
92:     setBlinkPorts(true); //make port invisble unless mouse enters
93:     Rectangle r = getBounds();
94:   }
95: 
96: 
97:   /** If the UML meta-model object changes state. Update the Fig.  But
98:    *  we need to do it as a "DelayedVetoableChangeListener", so that
99:    *  model changes complete before we update the screen. */
100:   public void vetoableChange(PropertyChangeEvent pce) {
101:     // throws PropertyVetoException 
102:     //System.out.println("FigNote got a change notification!");
103:     Object src = pce.getSource();
104:     if (src == getOwner()) {
105:       DelayedChangeNotify delayedNotify = new DelayedChangeNotify(this, pce);
106:       SwingUtilities.invokeLater(delayedNotify);
107:     }
108:   }
109: 
110:   /** The UML meta-model object changed. Now update the Fig to show
111:    *  its current  state. */
112:   public void delayedVetoableChange(PropertyChangeEvent pce) {
113:     // throws PropertyVetoException 
114:     //System.out.println("FigNote got a delayed change notification!");
115:     Object src = pce.getSource();
116:     if (src == getOwner()) {
117:       updateText();
118:       // you may have to update more than just the text
119:     }
120:   }
121: 
122: 
123:   /** Update the text labels */
124:   protected void updateText() {
125:     Element elmt = (Element) getOwner();
126:     String nameStr = GeneratorDisplay.Generate(elmt.getName());
127: 
128:     startTrans();
129:     _name.setText(nameStr);
130:     Rectangle bbox = getBounds();
131:     setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
132:     endTrans();
133:   }
134: 
135:   public void dispose() {
136:     if (!(getOwner() instanceof Element)) return;
137:     Element elmt = (Element) getOwner();
138:     Project p = ProjectBrowser.TheInstance.getProject();
139:     p.moveToTrash(elmt);
140:     super.dispose();
141:   }
142: 
143: 
144: 
145: } /* end class FigNote */
