12: /**
13:  * Abstract class to be used as a convenience class for implementing 'go rules'.
14:  * Go rules are rules to which the navperspectives comply if they are registred
15:  * with the navperspectives. This usually happens in the static block of
16:  * NavPerspective.
17:  * If some modelelement is not showing up in a navperspective, in most cases this
18:  * means that there is no go rule defined or an incorrect one. Via the abstract method
19:  * getChildren the children of some tree element in a perspective are returned.
20:  * Only the returned children are shown for some tree element.
21:  *
22:  *
23:  * @author jaap.branderhorst@xs4all.nl
24:  */
25: public abstract class AbstractGoRule implements TreeModel {
26:     
27:     private static Category cat = Category.getInstance(org.argouml.ui.AbstractGoRule.class);
28:     
29:     // ----------- TreeModel implementation -----------
30:     
31:     /**
32:      * returns null.
33:      *
34:      * @see javax.swing.tree.TreeModel#getRoot()
35:      */
36:     public Object getRoot() {
37:         return null;
38:     }
39:     
40:     /**
41:      * @see javax.swing.tree.TreeModel#getChild(Object, int)
42:      */
43:     public Object getChild(Object parent, int index) {
44:         Vector children = toVector(getChildren(parent));
45:         if (children != null) {
46:             return children.elementAt(index);
47:         } else {
48:             cat.fatal("getChild should never get here");
49:             return null;
50:         }
51:     }
52:     
53:     /**
54:      * @see javax.swing.tree.TreeModel#getChildCount(Object)
55:      */
56:     public int getChildCount(Object parent) {
57:         Collection c = getChildren(parent);
58:         
59:         if (c == null)
60:             return 0;
61:         
62:         return c.size();
63:     }
64:     
65:     /**
66:      * @see javax.swing.tree.TreeModel#isLeaf(Object)
67:      */
68:     public abstract boolean isLeaf(Object node);
69:     
70:     /**
71:      * @see javax.swing.tree.TreeModel#valueForPathChanged(TreePath, Object)
72:      */
73:     public void valueForPathChanged(TreePath path, Object newValue) {
74:     }
75:     
76:     /**
77:      * @see javax.swing.tree.TreeModel#getIndexOfChild(Object, Object)
78:      */
79:     public int getIndexOfChild(Object parent, Object child) {
80:         // the next line does not take into account multiple levels of the Tree
81:         // to change that we must change ALL implementations of getChildren(Object)
82:         // to return ALL elements of the tree instead of only the first level.
83:         // since this is going to be quite complicated and a violation of the
84:         // design with GoRules (GoRules do only take into account one node) we have
85:         // to invent a way around it.
86:         Vector children = toVector(getChildren(parent));
87:         return children.indexOf(child);
88:     }
89:     
90:     /**
91:      * @see javax.swing.tree.TreeModel#addTreeModelListener(TreeModelListener)
92:      */
93:     public void addTreeModelListener(TreeModelListener treeModelListener) {
94:     }
95:     
96:     /**
97:      * @see javax.swing.tree.TreeModel#removeTreeModelListener(TreeModelListener)
98:      */
99:     public void removeTreeModelListener(TreeModelListener treeModelListener) {
100:     }
101:     
102:     // -------------- other helper methods --------------------
103:     
104:     public abstract Collection getChildren(Object parent);
105:     
106:     /** return the name of the rule as it is displayed in
107:      *  the nav perspective edit pane. Returns for example
108:      *  "State->Substates".
109:      *  @see #toString()
110:      */
111:     public abstract String getRuleName();
112:     
113:     /** wrapper around getRuleName()
114:      */
115:     public String toString() { return getRuleName(); }
116:     
117:     
118:     private Vector toVector(Collection col) {
119:         Vector ret = new Vector();
120:         if (col != null && !col.isEmpty()) {
121:             ret.addAll(col);
122:         }
123:         return ret;
124:     }
125: }
