162:     protected void setBoundsImpl(int x, int y, int w, int h) {
163:         if (getNameFig() == null) {
164:             return;
165:         }
166:         Rectangle oldBounds = getBounds();
167: 
168:         getNameFig().setBounds(x + PADDING, y, w - PADDING * 2, h - PADDING);
