235:     /**
236:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#modelChanged(java.beans.PropertyChangeEvent)
237:      */
238:     protected void modelChanged(PropertyChangeEvent mee) {
239:         super.modelChanged(mee);
240:         if (mee instanceof AddAssociationEvent
241:                 || mee instanceof AttributeChangeEvent) {
242:             if (mee.getSource() == getOwner()
243:                 && mee.getPropertyName().equals("entry")) {
244:                 if (mee.getNewValue() != null) {
245:                     addElementListener(mee.getNewValue(), "script");
246:                 }
247:                 updateNameText();
248:                 damage();
249:             } else {
250:                 if (getOwner() != null
251:                         && Model.getFacade().getEntry(getOwner()) == mee
252:                                 .getSource()) {
253:                     updateNameText();
254:                     damage();
255:                 }
256:             }
257:         } else if (mee instanceof RemoveAssociationEvent) {
258:             if (mee.getOldValue() != null
259:                     && mee.getPropertyName().equals("entry")) {
260:                 removeElementListener(mee.getOldValue());
261:                 updateNameText();
262:                 damage();
263:             }
264:         }
265:     }
