65: public class SelectionActionState extends SelectionWButtons {
66:     protected static Category cat = 
67:         Category.getInstance(SelectionActionState.class);
68:   ////////////////////////////////////////////////////////////////
69:   // constants
70:   public static Icon trans = 
71:       ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("Transition");
72:   public static Icon transDown = 
73:       ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("TransitionDown");
74:   ////////////////////////////////////////////////////////////////
75:   // instance varables
76:   protected boolean _showIncomingLeft = true;
77:     protected boolean _showIncomingAbove = true;
78:   protected boolean _showOutgoingRight = true;
79:     protected boolean _showOutgoingBelow = true;
80: 
81:   ////////////////////////////////////////////////////////////////
82:   // constructors
83: 
84:   /** Construct a new SelectionActionState for the given Fig */
85:   public SelectionActionState(Fig f) { super(f); }
86: 
87:   ////////////////////////////////////////////////////////////////
88:   // accessors
89: 
90:   public void setOutgoingButtonEnabled(boolean b) {
91:         setOutgoingRightButtonEnabled(b);
92:         setIncomingAboveButtonEnabled(b);
93:   }
94: 
95:   public void setIncomingButtonEnabled(boolean b) {
96:         setIncomingLeftButtonEnabled(b);
97:         setOutgoingBelowButtonEnabled(b);
98:   }
99: 
100:   public void setIncomingLeftButtonEnabled(boolean b) {
101:     _showIncomingLeft = b;
102:   }
103: 
104:   public void setOutgoingRightButtonEnabled(boolean b) {
105:     _showOutgoingRight = b;
106:   }
107: 
108:    public void setIncomingAboveButtonEnabled(boolean b) {
109:     _showIncomingAbove = b;
110:   }
111: 
