254:   public Object addCompClassAbove(MutableGraphModel mgm, MComponentInstance cls,
255: 			    MComponentInstance newCls) {
256:     return mgm.connect(cls, newCls, MDependency.class);
257:   }
258: 
259:   public Object createEdgeRight(MutableGraphModel mgm, MComponentInstance cls,
260:                                 MComponentInstance newCls) {
261:     return mgm.connect(newCls, cls, MDependency.class);
262:   }
263:   public Object addCompClassRight(MutableGraphModel mgm, MComponentInstance cls,
264: 			    MComponentInstance newCls) {
265:     return mgm.connect(cls, newCls, MDependency.class);
266:   }
267: 
268:   public Object addCompClassLeft(MutableGraphModel mgm, MComponentInstance cls,
269: 			    MComponentInstance newCls) {
270:     return mgm.connect(newCls, cls, MDependency.class);
271:   }
