239:     public void buttonClicked(int buttonCode) {
240:         super.buttonClicked(buttonCode);
241:         MClass newNode = UmlFactory.getFactory().getCore().createClass();
242:         FigClass fc = (FigClass) _content;
243:         MClass cls = (MClass) fc.getOwner();
244: 
245:         Editor ce = Globals.curEditor();
246:         GraphModel gm = ce.getGraphModel();
247:         if (!(gm instanceof MutableGraphModel)) return;
248:         MutableGraphModel mgm = (MutableGraphModel) gm;
249: 
250:         if (!mgm.canAddNode(newNode)) return;
251:         GraphNodeRenderer renderer = ce.getGraphNodeRenderer();
252:         LayerPerspective lay = (LayerPerspective)
253:             ce.getLayerManager().getActiveLayer();
254:         Fig newFC = renderer.getFigNodeFor(gm, lay, newNode);
255: 
256:         Rectangle outputRect = new Rectangle(Math.max(0, fc.getX() - 200),
257:                                              Math.max(0, fc.getY() - 200),
258:                                              fc.getWidth() + 400,                              
259:                                              fc.getHeight() + 400);
260:                                              
261:         
262:         // handle the case that it is not a self association
263:         if (buttonCode >=10 && buttonCode <= 13) {
264:             int x = 0;
265:             int y = 0; 
266:             if (buttonCode == 10) {
267:                 // superclass
268:                 x = fc.getX();
269:                 y = Math.max(0, fc.getY() - 200);
270:             }
271:             else if (buttonCode == 11) {
272:                 x = fc.getX();
273:                 y = fc.getY() + fc.getHeight() + 100;
274:             }
275:             else if (buttonCode == 12) {
276:                 x = fc.getX() + fc.getWidth() + 100;
277:                 y = fc.getY();
278:             }
279:             else if (buttonCode == 13) {
280:                 x = Math.max(0, fc.getX() - 200);
281:                 y = fc.getY();
282:                 
283:             }        
284:             // place the fig if it is not a selfassociation       
285:             if (!placeFig(newFC, lay, x, y, outputRect)) return;
286:         }
287:         
288:         // add the new node only if required, e.g. not when we add a 
289:         // self association
290:         if (buttonCode != 14) {
291:             ce.add(newFC);
292:             mgm.addNode(newNode);
293:         }
294:         FigPoly edgeShape = new FigPoly();
295:         if (buttonCode!=14) {
296:             Point fcCenter = fc.center();
297:             edgeShape.addPoint(fcCenter.x, fcCenter.y);
298:             Point newFCCenter = newFC.center();
299:             edgeShape.addPoint(newFCCenter.x, newFCCenter.y);
300:         }
301:         else {
302:             Point fcCenter = fc.center();
303:             Point centerRight = 
304:                 new Point((int)(fcCenter.x + fc.getSize().getWidth()/2), 
305:                           fcCenter.y);
306: 
307:             int yoffset = (int)((fc.getSize().getHeight()/2));
308:             edgeShape.addPoint(fcCenter.x, fcCenter.y);
309:             edgeShape.addPoint(centerRight.x, centerRight.y);
310:             edgeShape.addPoint(centerRight.x + 30,
311:                                centerRight.y);
312:             edgeShape.addPoint(centerRight.x + 30,
313:                                centerRight.y + yoffset);
314:             edgeShape.addPoint(centerRight.x,
315:                                centerRight.y + yoffset);
316:         }
317:         Object newEdge = null;
318:         if (buttonCode == 10) newEdge = addSuperClass(mgm, cls, newNode);
319:         else if (buttonCode == 11) newEdge = addSubClass(mgm, cls, newNode);
320:         else if (buttonCode == 12) newEdge = createEdgeToSelf(mgm, cls, newNode);
321:         else if (buttonCode == 13) newEdge = createAssociationEdge(mgm, cls, newNode);
322:         else if (buttonCode == 14) newEdge = createEdgeToSelf(mgm, cls, cls);
323: 
324:         FigEdge fe = (FigEdge) lay.presentationFor(newEdge);
325:         edgeShape.setLineColor(Color.black);
326:         edgeShape.setFilled(false);
327:         edgeShape._isComplete = true;
328:         fe.setFig(edgeShape);
329:         ce.getSelectionManager().select(fc);
330:     }
