65: public class SelectionState extends SelectionWButtons {
66:     protected static Category cat = 
67:         Category.getInstance(SelectionState.class);
68:   ////////////////////////////////////////////////////////////////
69:   // constants
70:   public static Icon trans = ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("Transition");
71: 
72:   ////////////////////////////////////////////////////////////////
73:   // instance varables
74:   protected boolean _showIncoming = true;
75:   protected boolean _showOutgoing = true;
76: 
77:   ////////////////////////////////////////////////////////////////
78:   // constructors
79: 
80:   /** Construct a new SelectionState for the given Fig */
81:   public SelectionState(Fig f) { super(f); }
