84:   // accessors
85: 
86:   public void setIncomingButtonEnabled(boolean b) {
87:     _showIncoming = b;
88:   }
89: 
90:   public void setOutgoingButtonEnabled(boolean b) {
91:     _showOutgoing = b;
92:   }
