94:   public void hitHandle(Rectangle r, Handle h) {
95:     super.hitHandle(r, h);
96:     if (h.index != -1) return;
97:     if (!_paintButtons) return;
98:     Editor ce = Globals.curEditor();
99:     SelectionManager sm = ce.getSelectionManager();
100:     if (sm.size() != 1) return;
101:     ModeManager mm = ce.getModeManager();
102:     if (mm.includes(ModeModify.class) && _pressedButton == -1) return;
103:     int cx = _content.getX();
104:     int cy = _content.getY();
105:     int cw = _content.getWidth();
106:     int ch = _content.getHeight();
107:     int iw = trans.getIconWidth();
108:     int ih = trans.getIconHeight();
109:     if (_showOutgoing && hitLeft(cx + cw, cy + ch/2, iw, ih, r)) {
110:       h.index = 12;
111:       h.instructions = "Add an outgoing transition";
112:     }
113:     else if (_showIncoming && hitRight(cx, cy + ch/2, iw, ih, r)) {
114:       h.index = 13;
115:       h.instructions = "Add an incoming transition";
116:     }
117:     else {
118:       h.index = -1;
119:       h.instructions = "Move object(s)";
120:     }
121:   }
