124:   /** Paint the handles at the four corners and midway along each edge
125:    * of the bounding box.  */
126:   public void paintButtons(Graphics g) {
127:     int cx = _content.getX();
128:     int cy = _content.getY();
129:     int cw = _content.getWidth();
130:     int ch = _content.getHeight();
131:     if (_showOutgoing) paintButtonLeft(trans, g, cx + cw, cy + ch/2, 12);
132:     if (_showIncoming) paintButtonRight(trans, g, cx, cy + ch/2, 13);
133:   }
