136:   public void dragHandle(int mX, int mY, int anX, int anY, Handle hand) {
137:     if (hand.index < 10) {
138:       _paintButtons = false;
139:       super.dragHandle(mX, mY, anX, anY, hand);
140:       return;
141:     }
142:     int cx = _content.getX(), cy = _content.getY();
143:     int cw = _content.getWidth(), ch = _content.getHeight();
144:     int newX = cx, newY = cy, newW = cw, newH = ch;
145:     Dimension minSize = _content.getMinimumSize();
146:     int minWidth = minSize.width, minHeight = minSize.height;
147:     Class edgeClass = null;
148:     Class nodeClass = MStateImpl.class;
149: 
150:     Editor ce = Globals.curEditor();
151:     GraphModel gm = ce.getGraphModel();
152:     if (!(gm instanceof MutableGraphModel)) return;
153:    
154:     MutableGraphModel mgm = (MutableGraphModel) gm;
155: 
156:     int bx = mX, by = mY;
157:     boolean reverse = false;
158:     switch (hand.index) {
159:     case 12: //add outgoing
160:       edgeClass = MTransition.class;
161:       by = cy + ch/2;
162:       bx = cx + cw;
163:       break;
164:     case 13: // add incoming
165:       edgeClass = MTransition.class;
166:       reverse = true;
167:       by = cy + ch/2;
168:       bx = cx;
169:       break;
170:     default:
171:       cat.warn("invalid handle number");
172:       break;
173:     }
174:     if (edgeClass != null && nodeClass != null) {
175:       ModeCreateEdgeAndNode m = new
176: 	ModeCreateEdgeAndNode(ce, edgeClass, nodeClass, false);
177:       m.setup((FigNode)_content, _content.getOwner(), bx, by, reverse);
178:       ce.mode(m);
179:     }
180:   }
