183:   public void buttonClicked(int buttonCode) {
184:     super.buttonClicked(buttonCode);
185: 
186:     FigStateVertex fc = (FigStateVertex) _content;
187:     MStateVertex cls = (MStateVertex) fc.getOwner();
188: 
189:     Editor ce = Globals.curEditor();
190:     GraphModel gm = ce.getGraphModel();
191:     if (!(gm instanceof StateDiagramGraphModel)) return;
192:     StateDiagramGraphModel mgm = (StateDiagramGraphModel) gm;
193: 
194:     MState newNode = UmlFactory.getFactory().getStateMachines().createState();
195:     if (!mgm.canAddNode(newNode)) return;
196: 
197:     //mgm.getNamespace().addOwnedElement(newNode);
198: 
199:     GraphNodeRenderer renderer = ce.getGraphNodeRenderer();
200:     LayerPerspective lay = (LayerPerspective)
201:       ce.getLayerManager().getActiveLayer();
202: 
203:     Fig newFC = renderer.getFigNodeFor(gm, lay, newNode);
204: 
205:     Rectangle outputRect = new Rectangle(Math.max(0, fc.getX() - 200),
206: 					 Math.max(0, fc.getY() - 200),
207: 					 fc.getWidth() + 400,
208: 					 fc.getHeight() + 400);
209:     // handle the case that it is not a self association
210:         if (buttonCode >=10 && buttonCode <= 13) {
211:             int x = 0;
212:             int y = 0; 
213:             if (buttonCode == 10) {
214:                 // superclass
215:                 x = fc.getX();
216:                 y = Math.max(0, fc.getY() - 200);
217:             }
218:             else if (buttonCode == 11) {
219:                 x = fc.getX();
220:                 y = fc.getY() + fc.getHeight() + 100;
221:             }
222:             else if (buttonCode == 12) {
223:                 x = fc.getX() + fc.getWidth() + 100;
224:                 y = fc.getY();
225:             }
226:             else if (buttonCode == 13) {
227:                 x = Math.max(0, fc.getX() - 200);
228:                 y = fc.getY();
229:                 
230:             }        
231:             // place the fig if it is not a selfassociation       
232:             if (!placeFig(newFC, lay, x, y, outputRect)) return;
233:         }
234:     ce.add(newFC);
235:     mgm.addNode(newNode);
236: 
237:     FigPoly edgeShape = new FigPoly();
238:     Point fcCenter = fc.center();
239:     edgeShape.addPoint(fcCenter.x, fcCenter.y);
240:     Point newFCCenter = newFC.center();
241:     edgeShape.addPoint(newFCCenter.x, newFCCenter.y);
242:     Object newEdge = null;
243:     if (buttonCode == 12) newEdge = createEdgeRight(mgm, cls, newNode);
244:     else if (buttonCode == 13) newEdge = addIncomingTrans(mgm, cls, newNode);
245: 
246:     FigEdge fe = (FigEdge) lay.presentationFor(newEdge);
247:     edgeShape.setLineColor(Color.black);
248:     edgeShape.setFilled(false);
249:     edgeShape._isComplete = true;
250:     fe.setFig(edgeShape);
251:     ce.getSelectionManager().select(fc);
252:   }
253: 
254:   public Object createEdgeRight(MutableGraphModel mgm, MStateVertex cls,
255:                                 MStateVertex newCls) {
256:     return mgm.connect(cls, newCls, MTransition.class);
257:   }
258: 
259:   public Object addIncomingTrans(MutableGraphModel mgm, MStateVertex cls,
260: 			    MStateVertex newCls) {
261:     return mgm.connect(newCls, cls, MTransition.class);
262:   }
263: 
