332:     private EventListenerList registrateTargetListeners(Container container) {
333:         Component[] components = container.getComponents();
334:         EventListenerList list = new EventListenerList();
335:         for (int i = 0; i < components.length; i++) {
336:             if (components[i] instanceof TargetListener) {
337:                 list.add(TargetListener.class, (TargetListener) components[i]);
338:             }
339:             if (components[i] instanceof TargettableModelView) {
