199:     /**
200:      * Add a component with the specified label positioned after another
201:      * component.
202:      *
203:      * @param label
204:      *            the label for the component
205:      * @param component
206:      *            the component
207:      * @param afterComponent
208:      *            the component before
209:      * @return the newly added label
210:      */
211:     public JLabel addFieldAfter(String label, Component component,
212:             Component afterComponent) {
213:         int nComponent = this.getComponentCount();
214:         for (int i = 0; i < nComponent; ++i) {
215:             if (getComponent(i) == afterComponent) {
216:                 JLabel jlabel = new JLabel(label);
217:                 jlabel.setFont(stdFont);
218:                 component.setFont(stdFont);
219:                 jlabel.setLabelFor(component);
220:                 add(jlabel, ++i);
221:                 add(component, ++i);
222:                 return jlabel;
223:             }
224:         }
225:         throw new IllegalArgumentException("Component not found");
226:     }
