228:     /**
229:      * Add a component with the specified label positioned before another
230:      * component.
231:      * <p>
232:      *
233:      * @param label
234:      *            the label for the component
235:      * @param component
236:      *            the to be added component
237:      * @param beforeComponent
238:      *            the component before its label we add
239:      * @return the newly added component
240:      */
241:     public JLabel addFieldBefore(String label, Component component,
242:             Component beforeComponent) {
243:         int nComponent = this.getComponentCount();
244:         for (int i = 0; i < nComponent; ++i) {
245:             if (getComponent(i) == beforeComponent) {
246:                 JLabel jlabel = new JLabel(label);
247:                 jlabel.setFont(stdFont);
248:                 component.setFont(stdFont);
249:                 jlabel.setLabelFor(component);
250:                 add(jlabel, i - 1);
251:                 add(component, i++);
252:                 return jlabel;
253:             }
254:         }
255:         throw new IllegalArgumentException("Component not found");
256:     }
