323:     /**
324:      * Builds a eventlistenerlist of all targetlisteners that are part of this
325:      * container and its children.
326:      *
327:      * @param container
328:      *            the container to search for targetlisteners
329:      * @return an EventListenerList with all TargetListeners on this container
330:      *         and its children.
331:      */
332:     private EventListenerList registrateTargetListeners(Container container) {
333:         Component[] components = container.getComponents();
334:         EventListenerList list = new EventListenerList();
335:         for (int i = 0; i < components.length; i++) {
336:             if (components[i] instanceof TargetListener) {
337:                 list.add(TargetListener.class, (TargetListener) components[i]);
338:             }
339:             if (components[i] instanceof TargettableModelView) {
340:                 list.add(TargetListener.class,
341:                         ((TargettableModelView) components[i])
342:                                 .getTargettableModel());
343:             }
344:             if (components[i] instanceof Container) {
345:                 EventListenerList list2 = registrateTargetListeners(
346:                                                 (Container) components[i]);
347:                 Object[] objects = list2.getListenerList();
348:                 for (int j = 1; j < objects.length; j += 2) {
349:                     list.add(TargetListener.class, (TargetListener) objects[j]);
350:                 }
351:             }
352:         }
353:         return list;
354:     }
