490:     private void fireTargetSet(TargetEvent targetEvent) {
491:         if (listenerList == null)
492:             listenerList = registrateTargetListeners(this);
493:         // Guaranteed to return a non-null array
494:         Object[] listeners = listenerList.getListenerList();
495:         for (int i = listeners.length - 2; i >= 0; i -= 2) {
496:             if (listeners[i] == TargetListener.class) {
497:                 // Lazily create the event:
498:                 ((TargetListener) listeners[i + 1]).targetSet(targetEvent);
499:             }
500:         }
501:     }
502: 
503:     private void fireTargetAdded(TargetEvent targetEvent) {
504:         if (listenerList == null)
505:             listenerList = registrateTargetListeners(this);
506:         // Guaranteed to return a non-null array
507:         Object[] listeners = listenerList.getListenerList();
508: 
509:         for (int i = listeners.length - 2; i >= 0; i -= 2) {
510:             if (listeners[i] == TargetListener.class) {
511:                 // Lazily create the event:
512:                 ((TargetListener) listeners[i + 1]).targetAdded(targetEvent);
513:             }
514:         }
515:     }
516: 
517:     private void fireTargetRemoved(TargetEvent targetEvent) {
518:         if (listenerList == null)
519:             listenerList = registrateTargetListeners(this);
520:         // Guaranteed to return a non-null array
521:         Object[] listeners = listenerList.getListenerList();
522:         for (int i = listeners.length - 2; i >= 0; i -= 2) {
523:             if (listeners[i] == TargetListener.class) {
524:                 // Lazily create the event:
525:                 ((TargetListener) listeners[i + 1]).targetRemoved(targetEvent);
526:             }
527:         }
528:     }
