138:     /**
139:      * Computes the route of this {@link FigMessage} and computes the
140:      * connectionpoints of the figlink to the ports.  This depends on
141:      * the action attached to the owner of the {@link FigMessage}.  Also
142:      * adds FigActivations etc or moves the {@link FigClassifierRole}s
143:      * if necessary.<p>
144:      *
145:      * @see org.tigris.gef.presentation.FigEdge#computeRoute()
146:      */
147:     public void computeRouteImpl() {
148:         Fig sourceFig = getSourcePortFig();
149:         Fig destFig = getDestPortFig();
150:         if (sourceFig instanceof FigMessagePort
151:                 && destFig instanceof FigMessagePort) {
152:             FigMessagePort srcMP = (FigMessagePort) sourceFig;
153:             FigMessagePort destMP = (FigMessagePort) destFig;
154:             Point startPoint = sourceFig.connectionPoint(destMP.getCenter());
155:             Point endPoint = destFig.connectionPoint(srcMP.getCenter());
156:             // If it is a self-message
157:             if (isSelfMessage()) {
158:                 if (startPoint.x < sourceFig.getCenter().x) {
159:                     startPoint.x += sourceFig.getWidth();
160:                 }
161:                 endPoint.x = startPoint.x;
162:                 setEndPoints(startPoint, endPoint);
163:                 // If this is the first time it is laid out, will only
164:                 // have 2 points, add the middle point
165:                 if (getNumPoints() <= 2) {
166:                     insertPoint(0, startPoint.x
167:                             + SequenceDiagramLayer.OBJECT_DISTANCE / 3,
168:                                 (startPoint.y + endPoint.y) / 2);
169:                 } else {
170:                     // Otherwise, move the middle point
171:                     int middleX =
172:                         startPoint.x
173:                         + SequenceDiagramLayer.OBJECT_DISTANCE / 3;
174:                     int middleY = (startPoint.y + endPoint.y) / 2;
175:                     Point p = getPoint(1);
176:                     if (p.x != middleX || p.y != middleY) {
177:                         setPoint(new Handle(1), middleX, middleY);
178:                     }
179:                 }
180:             } else {
181:                 setEndPoints(startPoint, endPoint);
182:             }
183:             calcBounds();
184:             layoutEdge();
185:         }
186:     }
