28:  * A member of the project.
29:  *
30:  */
31: public abstract class AbstractProjectMember implements ProjectMember {
32: 
33:     ////////////////////////////////////////////////////////////////
34:     // instance varables
35: 
36:     private String uniqueName;
37:     private Project project = null;
38: 
39:     ////////////////////////////////////////////////////////////////
40:     // constructors
