43:      * The constructor.
44:      * 
45:      * @param theName the name of the member
46:      * @param theProject the owning project
47:      */
48:     public AbstractProjectMember(String theName, Project theProject) {
49:         project = theProject;
50:         setName(theName);
51:     }
52: 
53:     /**
54:      * Returns a unique member's name for storage in a zipfile.
55:      * The project's base name is prepended followed by an
56:      * underscore '_'.
57:      *
58:      * @return the name for zip file storage
59:      */
60:     public String getZipName() {
61:         if (uniqueName == null)
62:             return null;
63:         
64:         String s = project.getBaseName();
65:         
66:         if (uniqueName.length() > 0)
67:             s += "_" + uniqueName;
68:         
69:         if (!s.endsWith(getFileExtension()))
70:             s += getFileExtension();
71: 
72:         System.out.println("Returning members name as " + s);
73:         return s;
74:     }
75:   
76:     /**
77:      * @param s the name of the member
78:      */
79:     protected void setName(String s) {
80:         uniqueName = s;
81:         
82:         if (uniqueName == null) {
83:             return;
84:         }
85:         
86:         if (uniqueName.startsWith (project.getBaseName())) {
87:             uniqueName = uniqueName.substring (project.getBaseName().length());
88:             int i = 0;
89:             for (; i < uniqueName.length(); i++) {
90:             	if (uniqueName.charAt(i) != '_') {
91:             	    break;
92:                 }
93:             }
94:             if (i > 0) {
95:                 uniqueName = uniqueName.substring(i);
96:             }
97:         }
98:         
99:         if (uniqueName.endsWith(getFileExtension())) {
100:             uniqueName =
101:                 uniqueName.substring(0,
102:                         uniqueName.length() - getFileExtension().length());
103:         }
104:     }
105: 
