59: 
60: /**
61:  * Class to display a UML comment in a diagram.
62:  *
63:  * @author Andreas Rueckert
64:  */
65: public class FigComment
66:     extends FigNodeModelElement
67:     implements VetoableChangeListener,
68: 	       DelayedVChangeListener,
69: 	       MouseListener,
70: 	       KeyListener,
71: 	       PropertyChangeListener {
72:     private static final Logger LOG = Logger.getLogger(FigComment.class);
73: 
74:     ////////////////////////////////////////////////////////////////
75:     // constants
76: 
77:     private int x = 0;
78:     private int y = 0;
79:     private int width = 80;
80:     private int height = 60;
81:     private int gapY = 10;
82: 
83:     private boolean readyToEdit = true;
84: 
85:     private static final int MARGIN = 2;
86: 
87:     ////////////////////////////////////////////////////////////////
88:     // instance variables
89: 
90:     // The figure that holds the text of the note.
91:     private FigText text;
92: 
93:     private FigPoly body;
94:     private FigPoly urCorner; // the upper right corner
95: 
96:     ////////////////////////////////////////////////////////////////
97:     // constructors
98: 
99:     /**
100:      * The main constructor used for file loading.
101:      */
102:     public FigComment() {
103:         body = new FigPoly(Color.black, Color.white);
104:         body.addPoint(x, y);
105:         body.addPoint(x + width - 1 - gapY, y);
106:         body.addPoint(x + width - 1, y + gapY);
107:         body.addPoint(x + width - 1, y + height - 1);
108:         body.addPoint(x, y + height - 1);
109:         body.addPoint(x, y);
110:         body.setFilled(true);
111:         body.setLineWidth(1);
112: 
113:         urCorner = new FigPoly(Color.black, Color.white);
114:         urCorner.addPoint(x + width - 1 - gapY, y);
115:         urCorner.addPoint(x + width - 1, y + gapY);
116:         urCorner.addPoint(x + width - 1 - gapY, y + gapY);
117:         urCorner.addPoint(x + width - 1 - gapY, y);
118:         urCorner.setFilled(true);
119:         urCorner.setLineWidth(1);
120: 
121:         setBigPort(new FigRect(x, y, width, height, null, null));
122:         getBigPort().setFilled(false);
123:         getBigPort().setLineWidth(0);
124: 
125:         text = new FigText(2, 2, width - 2 - gapY, height - 4, true);
126:         text.setFont(getLabelFont());
127:         text.setTextColor(Color.black);
128:         text.setMultiLine(true);
129:         text.setAllowsTab(false);
130:         // _text.setText(placeString());
131:         text.setJustification(FigText.JUSTIFY_LEFT);
132:         text.setFilled(false);
133:         text.setLineWidth(0);
134:         //_text.setLineColor(Color.white);
135: 
136:         // add Figs to the FigNode in back-to-front order
137:         addFig(getBigPort());
138:         addFig(body);
139:         addFig(urCorner);
140:         addFig(text);
141: 
142:         setBlinkPorts(false); //make port invisble unless mouse enters
143:         Rectangle r = getBounds();
144:         setBounds(r.x, r.y, r.width, r.height);
145:         updateEdges();
146: 
147:         readyToEdit = false;
148:     }
149: 
150:     /**
151:      * Construct a new comment.
152:      *
153:      * @param gm the graphmodel
154:      * @param node the underlying UML Comment
155:      */
156:     public FigComment(GraphModel gm, Object node) {
157:         this();
158:         setOwner(node);
159:     }
160: 
161:     /**
162:      * Create a note for a given model element.
163:      * @deprecated as of 0.17.1 nobody should use this constructor since
164:      * it not only constructs the fig but also the model behind it.
165:      * That should not be done by a fig which is only a view to the model
166:      * @param element The annotated model element.
167:      */
168:     public FigComment(Object element) {
169:         this(); // Construct the figure.
170: 
171:         if (!ModelFacade.isAModelElement(element)) {
172:             throw new IllegalArgumentException();
173:         }
174: 
175: 	// Create a new Comment node.
176:         Object comment =
177: 	    Model.getCoreFactory().createComment();
178:         setOwner(comment); // Set it as the owner of the figure.
179: 	// Tell the annotated element, that it has a comment now.
180:         ModelFacade.addComment(element, comment);
181: 
182:         // Notes in statechart diagrams need a special treatment, cause
183:         // the nodes in them don't necessary have a namespace, where
184:         // we could add the note. So I added this hack... :-(
185:         // Andreas Rueckert <a_rueckert@gmx.net>
186:         if (ModelFacade.isAStateVertex(element)) {
187: 
188: 	    // If the current target is a statechart diagram, we have to
189: 	    // check, if we are editing the diagram.
190:             ProjectBrowser pb = ProjectBrowser.getInstance();
191:             if (TargetManager.getInstance().getTarget()
192:                     instanceof UMLStateDiagram) {
193:                 StateDiagramGraphModel gm =
194: 		    (StateDiagramGraphModel)
195: 		    (((UMLStateDiagram) TargetManager.getInstance()
196: 		            .getTarget()).getGraphModel());
197: 		// We are editing, so we set the Namespace directly.
198:                 ModelFacade.setNamespace(comment, gm.getNamespace());
199:             }
200:         } else {
201: 	    // Add the comment to the same namespace as the annotated element.
202:             ModelFacade.setNamespace(comment,
203:                     ModelFacade.getNamespace(element));
204:         }
205: 
206:         storeNote(placeString()); // Set the default text for this figure type.
207:     }
208: 
209:     /**
210:      * Get the default text for this figure.
211:      *
212:      * @return The default text for this figure.
213:      */
214:     public String placeString() {
215:         String placeString = retrieveNote();
216:         if (placeString == null) {
217:             placeString = "new note";
218:         }
219:         return placeString;
220:     }
221: 
222:     /**
223:      * Clone this figure.
224:      *
225:      * @return The cloned figure.
226:      */
227:     public Object clone() {
228:         FigComment figClone = (FigComment) super.clone();
229:         Iterator it = figClone.getFigs(null).iterator();
230:         figClone.setBigPort((FigRect) it.next());
231:         figClone.body = (FigPoly) it.next();
232:         figClone.urCorner = (FigPoly) it.next();
233:         figClone.text = (FigText) it.next();
234:         return figClone;
235:     }
236: 
237:     ////////////////////////////////////////////////////////////////
238:     // event handlers
239: 
240:     /**
241:      * See FigNodeModelElement.java for more info on these methods.
242:      */
243: 
244:     /**
245:      * If the user double clicks on any part of this FigNode, pass it
246:      * down to one of the internal Figs.  This allows the user to
247:      * initiate direct text editing.
248:      *
249:      * @see java.awt.event.MouseListener#mouseClicked(java.awt.event.MouseEvent)
250:      */
251:     public void mouseClicked(MouseEvent me) {
252:         if (!readyToEdit) {
253:             if (org.argouml.model.ModelFacade.isAModelElement(getOwner())) {
254:                 Object own = /*(MModelElement)*/ getOwner();
255:                 readyToEdit = true;
256:             } else {
257:                 LOG.debug("not ready to edit note");
258:                 return;
259:             }
260:         }
261:         if (me.isConsumed()) {
262:             return;
263:         }
264:         if (me.getClickCount() >= 2
265: 	    && !(me.isPopupTrigger()
266: 		 || me.getModifiers() == InputEvent.BUTTON3_MASK)) {
267:             if (getOwner() == null) {
268:                 return;
269:             }
270:             Fig f = hitFig(new Rectangle(me.getX() - 2, me.getY() - 2, 4, 4));
271:             if (f instanceof MouseListener) {
272:                 ((MouseListener) f).mouseClicked(me);
273:             }
274:         }
275:         me.consume();
276:     }
