252:         if (!readyToEdit) {
253:             if (org.argouml.model.ModelFacade.isAModelElement(getOwner())) {
254:                 Object own = /*(MModelElement)*/ getOwner();
255:                 readyToEdit = true;
256:             } else {
257:                 LOG.debug("not ready to edit note");
258:                 return;
259:             }
