63:         super(text);
64:         setFont(LookAndFeelMgr.getInstance().getSmallFont());
65:         _propertySetName = name;
66:         addActionListener(a);
67: 
68: 	// TODO: When no longer requiring support for JDK1.2 this constant
69: 	// can be changed to Action.ACTION_COMMAND_KEY.
70: 	final String ACTION_COMMAND_KEY = "ActionCommandKey";
71:         setActionCommand((String) a.getValue(ACTION_COMMAND_KEY));
72:     }
73: 
