93:      */
94:     public void roleRemoved(MElementEvent e) {
95:     }
96: 
97:     /**
98:      * @see ru.novosoft.uml.MElementListener#listRoleItemSet(
99:      *          ru.novosoft.uml.MElementEvent)
100:      */
101:     public void listRoleItemSet(MElementEvent e) {
102:     }
103: 
104:     /**
105:      * @see ru.novosoft.uml.MElementListener#removed(
106:      *          ru.novosoft.uml.MElementEvent)
107:      */
108:     public void removed(MElementEvent e) {
109:     }
110: 
111:     /**
112:      * @see ru.novosoft.uml.MElementListener#recovered(
113:      *          ru.novosoft.uml.MElementEvent)
114:      */
115:     public void recovered(MElementEvent e) {
116:     }
117: 
118:     /**
119:      * Returns the target. The target is directly asked from the
120:      * _target attribute and not from the _container attribute to make
121:      * the move to a new targeting system as easy as possible.
122:      *
123:      * @return Object
124:      */
125:     public Object getTarget() {
126:         return _target;
127:     }
128: 
129:     /**
130:      * Sets the target. This method will not be used untill the target does
131:      * not come via the container.
132:      * @param target The target to set
133:      */
134:     public void setTarget(Object target) {
135:         target = target instanceof Fig ? ((Fig) target).getOwner() : target;
136:         if (ModelFacade.isABase(_target)) {
137:             UmlModelEventPump.getPump()
138: 		.removeModelEventListener(this, _target, _propertySetName);
139:         }
140:        
141:         if (ModelFacade.isABase(target)) {
142:             _target = target;
143: 	    // UmlModelEventPump.getPump()
144: 	    // .removeModelEventListener(this, (MBase)_target,
145: 	    // _propertySetName);
146: 	    UmlModelEventPump.getPump()
147: 		.addModelEventListener(this, _target, _propertySetName);
148:             buildModel();
149:         }
150:             
151:     }
152:     
153:     /**
154:      * Builds the model. That is: it sets the checkbox to true or
155:      * false. The name of this method is choosen to be compliant with
156:      * for example UMLModelElementListModel2.
157:      */
158:     public abstract void buildModel();
159:        
160: 
161:     /**
162:      * TODO: Is this used? I cannot find the reference to
163:      * org.argouml.uml.ui.TargetChangedListener#targetChanged(Object)
164:      */
165:     public void targetChanged(Object newTarget) {
166:         if (_target != newTarget)
167:             setTarget(newTarget);
168:     }
