172:      * org.argouml.uml.ui.TargetChangedListener#targetReasserted(Object)
173:      */
174:     public void targetReasserted(Object newTarget) {
175:         if (newTarget != _target)
176:             setTarget(newTarget);
177:     }
178: 
179:     /**
180:      * @see TargetListener#targetAdded(TargetEvent)
181:      */
182:     public void targetAdded(TargetEvent e) {
183:         setTarget(e.getNewTarget());
184:     }
185: 
