41: public class FigAssociation extends FigEdgeLine
42: implements VetoableChangeListener, DelayedVetoableChangeListener {
43: 
44:   protected FigText _name;
45:   protected FigText _source_end;
46:   protected FigText _destMult;
47: 
48:   public FigAssociation(Object edge) {
49:     super();
50:     setOwner(edge);
51: 
52:     if (edge instanceof ElementImpl)
53:       ((ElementImpl)edge).addVetoableChangeListener(this);
54: 
55:     Font labelFont = MetalLookAndFeel.getSubTextFont();
56:     
57:     
58:     _name = new FigText(10, 30, 90, 20);
59:     _name.setFont(labelFont);
60:     _name.setTextColor(Color.black);
61:     _name.setTextFilled(false);
62:     _name.setFilled(false);
63:     _name.setLineWidth(0);
64: 
65:     addPathItem(_name, new PathConvPercent(this, (float).50, 0));
66: 
67:     _source_end = new FigText(10, 30, 90, 20);
68:     _source_end.setFont(labelFont);
69:     _source_end.setTextColor(Color.black);
70:     _source_end.setTextFilled(false);
71:     _source_end.setFilled(false);
72:     _source_end.setLineWidth(0);
73:     addPathItem(_source_end, new PathConvPercent(this, (float).20, 0));
74: 
75:     _destMult = new FigText(10, 30, 90, 20);
76:     _destMult.setFont(labelFont);
77:     _destMult.setTextColor(Color.black);
78:     _destMult.setTextFilled(false);
79:     _destMult.setFilled(false);
80:     _destMult.setLineWidth(0);
81:     addPathItem(_destMult, new PathConvPercent(this, (float).80, 0));
82: 
83:     setBetweenNearestPoints(true);
84:     updateText();
85:   }
86: 
87: 
88:   public void dispose() {
89:     if (!(getOwner() instanceof Association)) return;
90:     Association asc = (Association) getOwner();
91:     Project p = ProjectBrowser.TheInstance.getProject();
92:     p.moveToTrash(asc);
93:     super.dispose();
94:   }
95:   
96: 
97:   public void vetoableChange(PropertyChangeEvent pce) {
98:     // throws PropertyVetoException 
99:     System.out.println("FigAssociation got a change notification!");
100:     Object src = pce.getSource();
101:     if (src == getOwner()) {
102:       DelayedChangeNotify delayedNotify = new DelayedChangeNotify(this, pce);
103:       SwingUtilities.invokeLater(delayedNotify);
104:     }
105:   }
106: 
107:   public void delayedVetoableChange(PropertyChangeEvent pce) {
108:     // throws PropertyVetoException 
109:     System.out.println("FigAssociation got a delayed change notification!");
110:     Object src = pce.getSource();
111:     updateText();
112:   }
113: 
114:   protected void updateText() {
115:     Association as = (Association) getOwner();
116:     String asNameStr = GeneratorDisplay.Generate(as.getName());
117: 
118:     startTrans();
119:     _name.setText(asNameStr);
120: 
121:     AssociationEnd _end_1 = ((AssociationEnd)(as.getConnection().elementAt(0)));
122:     AssociationEnd _end_2 = ((AssociationEnd)(as.getConnection().elementAt(1)));
123: 
124:     _source_end.setText(GeneratorDisplay.Generate(_end_1.getMultiplicity()));
125:     _destMult.setText(GeneratorDisplay.Generate(_end_2.getMultiplicity()));
126: 
127:     AggregationKind agg_kind_1 = _end_1.getAggregation();
128:     AggregationKind agg_kind_2 = _end_2.getAggregation();
129: 
130:     updateArrowHead("source", agg_kind_1);
131:     updateArrowHead("dest", agg_kind_2);
132: 
133:     Rectangle bbox = getBounds();
134:     setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
135:     endTrans();
136:   }
137: 
138:   protected void updateArrowHead(String which, AggregationKind agg_kind)
139:   {
140:     ArrowHead newArrowhead = new ArrowHeadNone();
141: 
142:     if (agg_kind.equals(AggregationKind.UNSPEC)) {
143:       newArrowhead = new ArrowHeadNone(); }
144:     if (agg_kind.equals(AggregationKind.NONE)) {
145:       newArrowhead = new ArrowHeadNone(); }
146:     if (agg_kind.equals(AggregationKind.AGG)) {
147:       ArrowHeadDiamond temp = new ArrowHeadDiamond();
148:       temp.setFillColor(Color.white);
149:       newArrowhead = temp; }
150:     if (agg_kind.equals(AggregationKind.COMPOSITE)) {
151:       ArrowHeadDiamond temp = new ArrowHeadDiamond();
152:       temp.setFillColor(Color.black);
