586:     /**
587:      * @see org.argouml.model.CoreFactory#buildAssociationEnd(java.lang.Object,
588:      *      java.lang.String, java.lang.Object, java.lang.Object,
589:      *      java.lang.Object, boolean, java.lang.Object, java.lang.Object,
590:      *      java.lang.Object, java.lang.Object, java.lang.Object)
591:      */
592:     public Object buildAssociationEnd(Object assoc, String name, Object type,
593:             Object multi, Object stereo, boolean navigable, Object order,
594:             Object aggregation, Object scope, Object changeable,
595:             Object visibility) {
596:         // wellformednessrules and preconditions
597:         if (assoc == null || !(assoc instanceof UmlAssociation) || type == null
598:                 || !(type instanceof Classifier)) {
599:             throw new IllegalArgumentException("either type or association "
600:                     + "are null");
601:         }
602:         if (multi != null && !(multi instanceof Multiplicity)) {
603:             throw new IllegalArgumentException("Multiplicity");
604:         }
605:         if (stereo != null && !(stereo instanceof Stereotype)) {
606:             throw new IllegalArgumentException("Stereotype");
607:         }
608:         if (order != null && !(order instanceof OrderingKind)) {
609:             throw new IllegalArgumentException("OrderingKind");
610:         }
611:         if (aggregation != null && !(aggregation instanceof AggregationKind)) {
612:             throw new IllegalArgumentException("AggregationKind");
613:         }
614:         if (scope != null && !(scope instanceof ScopeKind)) {
615:             throw new IllegalArgumentException("ScopeKind");
616:         }
617:         if (changeable != null && !(changeable instanceof ChangeableKind)) {
618:             throw new IllegalArgumentException("ChangeableKind");
619:         }
620:         if (visibility != null && !(visibility instanceof VisibilityKind)) {
621:             throw new IllegalArgumentException("VisibilityKind");
622:         }
623: 
624:         if (type instanceof DataType || type instanceof Interface) {
625:             if (!navigable) {
626:                 throw new IllegalArgumentException(
627:                         "Wellformedness rule 2.5.3.3 [1] is broken. "
628:                                 + "The Classifier of an AssociationEnd cannot"
629:                                 + "be an Interface or a DataType if the "
630:                                 + "association is navigable away from "
631:                                 + "that end.");
632:             }
633:             List ends = new ArrayList();
634:             ends.addAll(((UmlAssociation) assoc).getConnection());
635:             Iterator it = ends.iterator();
636:             while (it.hasNext()) {
637:                 AssociationEnd end = (AssociationEnd) it.next();
638:                 if (end.isNavigable()) {
639:                     throw new IllegalArgumentException("type is either "
640:                             + "datatype or " + "interface and is "
641:                             + "navigable to");
642:                 }
643:             }
644:         }
645:         if (aggregation != null
646:                 && aggregation.equals(AggregationKindEnum.AK_COMPOSITE)
647:                 && multi != null && getMaxUpper((Multiplicity) multi) > 1) {
648:             throw new IllegalArgumentException("aggregation is composite "
649:                     + "and multiplicity > 1");
650:         }
651: 
652:         AssociationEnd end = (AssociationEnd) createAssociationEnd();
653:         end.setAssociation((UmlAssociation) assoc);
654:         end.setParticipant((Classifier) type);
655:         end.setName(name);
656:         if (multi != null) {
657:             end.setMultiplicity((Multiplicity) multi);
658:         } else {
659:             end.setMultiplicity(getMultiplicity11());
660:         }
661:         if (stereo != null) {
662:             end.getStereotype().clear();
663:             end.getStereotype().add(stereo);
664:         }
665:         end.setNavigable(navigable);
666:         if (order != null) {
667:             end.setOrdering((OrderingKind) order);
668:         } else {
669:             end.setOrdering(OrderingKindEnum.OK_UNORDERED);
670:         }
671:         if (aggregation != null) {
672:             end.setAggregation((AggregationKind) aggregation);
673:         } else {
674:             end.setAggregation(AggregationKindEnum.AK_NONE);
675:         }
676:         if (scope != null) {
677:             end.setTargetScope((ScopeKind) scope);
678:         } else {
679:             end.setTargetScope(ScopeKindEnum.SK_INSTANCE);
680:         }
681:         if (changeable != null) {
682:             end.setChangeability((ChangeableKind) changeable);
683:         } else {
684:             end.setChangeability(ChangeableKindEnum.CK_CHANGEABLE);
685:         }
686:         if (visibility != null) {
687:             end.setVisibility((VisibilityKind) visibility);
688:         } else {
689:             end.setVisibility(VisibilityKindEnum.VK_PUBLIC);
690:         }
691:         return end;
692:     }
