838:      *      java.lang.Object, java.lang.Object, java.util.Collection)
839:      */
840:     public Object buildAttribute(Object handle, Object model, Object intType,
841:             Collection propertyChangeListeners) {
842:         if (!(handle instanceof Classifier)
843:                 && !(handle instanceof AssociationEnd)) {
844:             throw new IllegalArgumentException();
845:         }
846:         Attribute attr = (Attribute) buildAttribute(model, intType);
847:         if (handle instanceof Classifier) {
848:             Classifier cls = (Classifier) handle;
