1631:     /**
1632:      * Does a 'cascading delete' to all modelelements that are associated with
1633:      * this element that would be in an illegal state after deletion of the
1634:      * element. Does not do an cascading delete for elements that are deleted by
1635:      * MDR automatically. This method should not be called directly.
1636:      * <p>
1637:      * 
1638:      * In the case of a modelelement these are the following elements:
1639:      * <ul>
1640:      * <li>Dependencies that have the modelelement as supplier or as a client
1641:      * and are binary. (that is, they only have one supplier and one client)
1642:      * <li>Behaviors, TemplateArguments, and ElementImports which require
1643:      * this ModelElement
1644:      * </ul>
1645:      * 
1646:      * @param elem
1647:      * @see UmlFactoryMDRImpl#delete(Object)
1648:      */
1649:     void deleteModelElement(Object elem) {
1650:         if (!(elem instanceof ModelElement)) {
1651:             throw new IllegalArgumentException("elem: " + elem);
1652:         }
1653: 
1654:         // Delete dependencies where this is the only client
1655:         Collection deps = org.argouml.model.Model.getFacade()
1656:                 .getClientDependencies(elem);
1657:         Iterator it = deps.iterator();
1658:         while (it.hasNext()) {
1659:             Dependency dep = (Dependency) it.next();
1660:             if (dep.getClient().size() < 2
1661:                     && dep.getClient().contains(elem)) {
1662:                 nsmodel.getUmlFactory().delete(dep);
1663:             }
1664:         }
1665: 
1666:         // Delete dependencies where this is the only supplier
1667:         deps = org.argouml.model.Model.getFacade()
1668:                 .getSupplierDependencies(elem);
1669:         it = deps.iterator();
1670:         while (it.hasNext()) {
1671:             Dependency dep = (Dependency) it.next();
1672:             if (dep.getSupplier().size() < 2
1673:                     && dep.getSupplier().contains(elem)) {
1674:                 nsmodel.getUmlFactory().delete(dep);
1675:             }
1676:         }
1677: 
1678:         nsmodel.getUmlHelper().deleteCollection(
1679:                 nsmodel.getFacade().getBehaviors(elem));
1680:         nsmodel.getUmlHelper().deleteCollection(
1681:                 corePackage
1682:                         .getAModelElementTemplateArgument()
1683:                         .getTemplateArgument((ModelElement) elem));
1684:         nsmodel.getUmlHelper().deleteCollection(
1685:                 nsmodel.getUmlPackage().getModelManagement()
1686:                         .getAImportedElementElementImport()
1687:                         .getElementImport((ModelElement) elem));
1688:         
1689: 
1690:     }
