1900:         List listFrom = ((Enumeration) from).getLiteral();
1901:         List listTo = ((Enumeration) to).getLiteral();
1902:         Object literalFrom;
1903:         Object literalTo;
1904:         for (int i = 0; i < listFrom.size(); i++) {
1905:             literalFrom = listFrom.get(i);
1906:             if (listTo.size() > i) {
1907:                 literalTo = listTo.get(i);
1908:             } else {
1909:                 literalTo = createEnumerationLiteral();
1910:                 listTo.add(literalTo);
1911:             }
1912:             doCopyModelElement(literalFrom, literalTo);
1913:             ((EnumerationLiteral) literalTo).setEnumeration((Enumeration) to);
1914:         }
