834:     /**
835:      * Called from the parser to add a method body to an operation.
836:      * (An operation will have exactly one Java body.)
837:      *
838:      * @param op An operation.
839:      * @param body A method body.
840:      */
841:     public void addBodyToOperation(Object op, String body) {
842:         if (op == null || !Model.getFacade().isAOperation(op)) {
843: //            LOG.warn("adding body failed: no operation!");
844:             return;
845:         }
846:         if (body == null || body.length() == 0) {
847:             return;
848:         }
849: 
850:         Object method = getMethod(Model.getFacade().getName(op));
851:         parseState.feature(method);
852:         Model.getCoreHelper().setBody(method,
853: 			    Model.getDataTypesFactory()
854: 			    	.createProcedureExpression("Java",
855: 			    	        		   body));
856: 	// Add the method to it's specification.
857:         Model.getCoreHelper().addMethod(op, method);
858: 
859:         // Add this method as a feature to the classifier that owns
860:         // the operation.
861:         Model.getCoreHelper().addFeature(Model.getFacade().getOwner(op),
862:                 method);
