1449:     /**
1450:      * Add the contents of a single standard javadoc tag to the model element.
1451:      * Usually this will be added as a tagged value.
1452:      *
1453:      * This is called from {@link #addDocumentationTag} only.
1454:      *
1455:      * @param me the model element to add to
1456:      * @param sTagName the name of the javadoc tag
1457:      * @param sTagData the contents of the javadoc tag
1458:      */
1459:     private void addJavadocTagContents(Object me,
1460: 				       String sTagName,
1461: 				       String sTagData) {
1462:         int colonPos = (sTagData != null) ? sTagData.indexOf(':') : -1;
1463:         if (colonPos != -1 && (("invariant".equals(sTagName))
1464: 	    || ("pre-condition".equals(sTagName))
1465: 	    || ("post-condition".equals(sTagName)))) {
1466: 
1467: 	    // add as OCL constraint
1468: 	    String sContext = OCLUtil.getContextString(me);
1469: 	    String name = sTagData.substring(0, colonPos);
1470: 	    String body = null;
1471: 	    if (sTagName.equals ("invariant")) {
1472: 		// add as invariant constraint Note that no checking
1473: 		// of constraint syntax is performed... BAD!
1474: 		body = sContext + " inv " + sTagData;
1475: 	    } else if (sTagName.equals ("pre-condition")) {
1476: 		body = sContext + " pre " + sTagData;
1477: 	    } else {
1478: 		body = sContext + " post " + sTagData;
1479: 	    }
1480: 	    Object bexpr =
1481: 		Model.getDataTypesFactory()
1482: 		    .createBooleanExpression("OCL", body);
1483: 	    Object mc =
1484: 		Model.getCoreFactory().buildConstraint(name, bexpr);
1485: 	    Model.getCoreHelper().addConstraint(me, mc);
1486: 	    if (Model.getFacade().getNamespace(me) != null) {
1487: 		// Apparently namespace management is not supported
1488: 		// for all model elements. As this does not seem to
1489: 		// cause problems, I'll just leave it at that for the
1490: 		// moment...
1491: 		Model.getCoreHelper().addOwnedElement(
1492: 		        Model.getFacade().getNamespace(me),
1493: 		        mc);
1494: 	    }
1495:         } else {
1496:             if ("stereotype".equals(sTagName)) {
1497:                 // multiple stereotype support: 
1498:                 // make one stereotype tag from many stereotype tags
1499:                 Object tv = getTaggedValue(me, sTagName);
1500:                 if (tv != null) {
1501:                     String sStereotype = Model.getFacade().getValueOfTag(tv);
1502:                     if (sStereotype != null && sStereotype.length() > 0) {
1503:                         sTagData = sStereotype + ',' + sTagData;
1504:                     }
1505:                 }
1506:                 // now eliminate multiple entries in that comma separated list
1507:                 HashSet stSet = new HashSet();
1508:                 StringTokenizer st = new StringTokenizer(sTagData, ", ");
1509:                 while (st.hasMoreTokens()) {
1510:                     stSet.add(st.nextToken().trim());
1511:                 }
1512:                 StringBuffer sb = new StringBuffer();
1513:                 Iterator iter = stSet.iterator();
1514:                 while (iter.hasNext()) {
1515:                     if (sb.length() > 0) {
1516:                         sb.append(',');
1517:                     }
1518:                     sb.append(iter.next());
1519:                 }
1520:                 sTagData = sb.toString();
1521: 
1522:             }
1523:             Model.getExtensionMechanismsHelper().addTaggedValue(
1524:                     me,
1525:                     Model.getExtensionMechanismsFactory().buildTaggedValue(
1526:                             sTagName, sTagData));
1527: 
1528: 	}
1529:     }
