730: 	    Model.getCoreHelper().setConcurrency(mOperation,
731: 	            Model.getConcurrencyKind().getGuarded());
732: 	} else if (Model.getFacade().getConcurrency(mOperation)
733: 		   == Model.getConcurrencyKind().getGuarded()) {
734: 	    Model.getCoreHelper().setConcurrency(mOperation,
735: 	            Model.getConcurrencyKind().getSequential());
736: 	}
737: 
738:         Collection c = new ArrayList(Model.getFacade()
739:                 .getParameters(mOperation));
740: 	for (Iterator i = c.iterator(); i.hasNext();) {
741: 	    Model.getCoreHelper().removeParameter(mOperation, i.next());
742: 	}
743: 
744: 	Object mParameter;
745: 	String typeName;
746: 	Object mClassifier;
747: 
748: 	if (returnType == null
749:             || ("void".equals(returnType)
750:                 && name.equals(Model.getFacade().getName(parseState
751:                         .getClassifier())))) {
752: 	    // Constructor
753: 	    Model.getCoreHelper().addStereotype(mOperation,
754:                 getStereotype(mOperation, "create", "BehavioralFeature"));
755: 	} else {
756: 	    try {
757: 		mClassifier =
758: 		    getContext(returnType).get(getClassifierName(returnType));
759: 
760: 		Object mdl = ProjectManager.getManager()
761: 		    .getCurrentProject().getModel();
762: 		Object voidType = ProjectManager.getManager()
763: 		    .getCurrentProject().findType("void");
764: 		Collection project = ProjectManager.getManager()
765: 		    .getCurrentProject().findFigsForMember(mOperation);
766: 		mParameter = Model.getCoreFactory().buildParameter(
767: 		        mOperation, mdl, voidType, project);
768:                 Model.getCoreHelper().setName(mParameter, "return");
769:                 Model.getCoreHelper().setKind(
770:                         mParameter,
771:                         Model.getDirectionKind().getReturnParameter());
772: 
773:                 Model.getCoreHelper().setType(mParameter, mClassifier);
774: 	    } catch (ClassifierNotFoundException e) {
775: 		// Currently if a classifier cannot be found in the
776:                 // model/classpath then information will be lost from
777:                 // source files, because the classifier cannot be
778:                 // created on the fly.
779:                 LOG.warn("Modeller.java: a classifier that was in the source "
780: 			 + "file could not be generated in the model "
781: 			 + "(for generating operation return type) - "
782: 			 + "information lost",
783: 			 e);
784: 	    }
785: 	}
786: 
787: 	for (Iterator i = parameters.iterator(); i.hasNext();) {
788: 	    Vector parameter = (Vector) i.next();
789: 	    typeName = (String) parameter.elementAt(1);
790: 	    try {
791:                 mClassifier =
792: 		    getContext(typeName).get(getClassifierName(typeName));
793:                 Object mdl = ProjectManager.getManager()
794:                     .getCurrentProject().getModel();
