285:     /**
286:      * Adds a listener to modelevents that are fired by some given modelelement and that
287:      * have the name eventNames.
288:      *
289:      * <p>
290:      * If you want the listener to be registred for remove events (that is: the
291:      * instance the listener is listening too is removed), then you have to
292:      * register for the eventname "remove"
293:      * </p>
294:      * @param listener
295:      * @param modelelement
296:      * @param eventNames
297:      */
298:     public void addModelEventListener(Object listener, Object modelelement, String[] eventNames) {
299:         if (listener == null || modelelement == null || eventNames == null || eventNames.length == 0)
300:             throw new IllegalArgumentException("Null or empty arguments while adding a modelelement listener");
301:         if (!(listener instanceof MElementListener) || !(modelelement instanceof MBase))
302:             throw new IllegalArgumentException("Wrong argument types while adding a modelelement listener");
303:         for (int i = 0; i < eventNames.length; i++) {
304:             executeAddModelEventListener((MElementListener)listener, (MBase)modelelement, eventNames[i]);
305:         }
306:     }
