313:      */
314:     public void addModelEventListener(Object listener, Object modelelement, String eventName) {
315:         if (listener == null || modelelement == null || eventName == null)
316:             throw new IllegalArgumentException("Tried to add null listener to null class");
317:         if (!(listener instanceof MElementListener) || !(modelelement instanceof MBase))
318:             throw new IllegalArgumentException("Wrong argument types while adding a modelelement listener");
319:         if (eventName.equals(""))
320:             throw new IllegalArgumentException("Tried to add an empty eventname");
321:         executeAddModelEventListener((MElementListener)listener, (MBase)modelelement, eventName);
322:     }
