324:     /**
325:      * Adds a listener to all events fired by some modelelement.
326:      *
327:      * <p><em>Note:</em> Due to the fact that ALL events are pumped for some
328:      * modelelement, this is a rather powerfull method but also
329:      * one that can hog performance. Use this with care!</p>
330:      * @param listener
331:      * @param modelElement
332:      */
333:     public void addModelEventListener(Object listener, Object modelelement) {
334:         if (listener == null || modelelement == null)
335:             throw new IllegalArgumentException("Tried to add null listener to null class");
336:         if (!(listener instanceof MElementListener) || !(modelelement instanceof MBase))
