63:  *
64:  * @author Andreas Rueckert
65:  */
66: public class FigComment
67:     extends FigNodeModelElement
68:     implements VetoableChangeListener,
69: 	       DelayedVChangeListener,
70: 	       MouseListener,
71: 	       KeyListener,
72: 	       PropertyChangeListener {
73:     /**
74:      * Logger.
75:      */
76:     private static final Logger LOG = Logger.getLogger(FigComment.class);
77: 
