79:     // constants
80: 
81:     private int x = 0;
82:     private int y = 0;
83:     private int width = 80;
84:     private int height = 60;
85:     private int dogear = 10; // a dog-ear = a bent corner in a book
86: 
87:     private boolean readyToEdit = true;
88: 
