596:     /**
597:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateStereotypeText()
598:      */
599:     protected void updateStereotypeText() {
600:         if (SingleStereotypeEnabler.isEnabled()) {
601:             updateStereotypeTextSingleStereotype();
602:             return;
603:         }
604:         Object me = /*(MModelElement)*/ getOwner();
605: 
606:         if (me == null) {
607:             return;
608:         }
609: 
610:         Rectangle rect = getBounds();
611: 
612:         Dimension stereoMin = getStereotypeFig().getMinimumSize();
613:         
614:         if (Model.getFacade().getStereotypes(me).isEmpty()) {
615: 
616:             if (getStereotypeFig().isVisible()) {
617:                 getStereotypeFig().setVisible(false);
618:                 rect.y += stereoMin.height;
619:                 rect.height -= stereoMin.height;
620:                 setBounds(rect.x, rect.y, rect.width, rect.height);
621:                 calcBounds();
622:             }
623:         } else {
624:             getStereotypeFig().setOwner(getOwner());
625: 
626:             if (!getStereotypeFig().isVisible()) {
627:                 getStereotypeFig().setVisible(true);
628: 
629:                 // Only adjust the stereotype height if we are not newly
630:                 // created. This gets round the problem of loading classes with
631:                 // stereotypes defined, which have the height already including
632:                 // the stereotype.
633: 
634:                 if (!newlyCreated) {
635:                     rect.y -= stereoMin.height;
636:                     rect.height += stereoMin.height;
637:                     rect.width = 
638:                         Math.max(getMinimumSize().width, rect.width);
639:                     setBounds(rect.x, rect.y, rect.width, rect.height);
640:                     calcBounds();
641:                 }
642:             }
643:         }
644:         // Whatever happened we are no longer newly created, so clear the
645:         // flag. Then set the bounds for the rectangle we have defined.
646:         newlyCreated = false;
647:     }
648:     protected void updateStereotypeTextSingleStereotype() {
649:         Object me = /*(MModelElement)*/ getOwner();
650: 
651:         if (me == null) {
652:             return;
653:         }
654: 
655:         Rectangle rect = getBounds();
656:         Object stereo = CollectionUtil.getFirstItemOrNull(
657:                 Model.getFacade().getStereotypes(me));
658: 
659:         if ((stereo == null)
660:                 || (Model.getFacade().getName(stereo) == null)
661:                 || (Model.getFacade().getName(stereo).length() == 0))   {
662: 
663:             if (getStereotypeFig().isVisible()) {
664:                 getStereotypeFig().setVisible(false);
665:                 rect.y += STEREOHEIGHT;
666:                 rect.height -= STEREOHEIGHT;
667:                 setBounds(rect.x, rect.y, rect.width, rect.height);
668:                 calcBounds();
669:             }
670:         } else {
671:             getStereotypeFig().setOwner(getOwner());
672: 
673:             if (!getStereotypeFig().isVisible()) {
674:                 getStereotypeFig().setVisible(true);
675: 
676:                 // Only adjust the stereotype height if we are not newly
677:                 // created. This gets round the problem of loading classes with
678:                 // stereotypes defined, which have the height already including
679:                 // the stereotype.
680: 
681:                 if (!newlyCreated) {
682:                     rect.y -= STEREOHEIGHT;
683:                     rect.height += STEREOHEIGHT;
684:                     rect.width = 
685:                         Math.max(getMinimumSize().width, rect.width);
686:                     setBounds(rect.x, rect.y, rect.width, rect.height);
687:                     calcBounds();
688:                 }
689:             }
690:         }
691:         // Whatever happened we are no longer newly created, so clear the
692:         // flag. Then set the bounds for the rectangle we have defined.
693:         newlyCreated = false;
694:     }
