272:     /**
273:      * initialize the menu for diagram construction in the explorer popup menu.
274:      *
275:      */
276:     private void initMenuCreateDiagrams() {
277:         createDiagrams.add(new ActionUseCaseDiagram());
278: 
279:         createDiagrams.add(new ActionClassDiagram());
280: 
281:         createDiagrams.add(new ActionSequenceDiagram());
282: 
283:         createDiagrams.add(new ActionCollaborationDiagram());
284: 
285:         createDiagrams.add(new ActionStateDiagram());
286: 
