212:     /**  After loading the diagram it?s necessary to connect
213:      *  every FigMessage to its FigAssociationRole. 
214:      *  This is done by adding the FigMessage 
215:      *  to the PathItems of its FigAssociationRole */
216:     public void postLoad() {
217: 
218:         super.postLoad();
219: 
220:         Collection messages;
221:         Iterator msgIterator;
222:         if (getNamespace() == null) {
223:             cat.error("Collaboration Diagram does not belong to a namespace");
224:             return;
225:         }
226:         Collection ownedElements = ModelFacade.getOwnedElements(getNamespace());
227:         Iterator oeIterator = ownedElements.iterator();
228:         Layer lay = getLayer();
229:         while (oeIterator.hasNext()) {
230:             Object me = /*(MModelElement)*/
231: 		oeIterator.next();
232:             if (org.argouml.model.ModelFacade.isAAssociationRole(me)) {
233:                 messages = ModelFacade.getMessages(me);
234:                 msgIterator = messages.iterator();
235:                 while (msgIterator.hasNext()) {
236:                     Object message = /*(MMessage)*/
237: 			msgIterator.next();
238:                     FigMessage figMessage =
239:                         (FigMessage) lay.presentationFor(message);
240:                     if (figMessage != null) {
241:                         figMessage.addPathItemToFigAssociationRole(lay);
242:                     }
243:                 }
244:             }
245:         }
246:     }
