96:      */
97:     public boolean isValidNamespace(Object handle) {
98:         if (!ModelFacade.isANamespace(handle)) {
99:             LOG.error("No namespace as argument");
100:             LOG.error(handle);
101:             throw new IllegalArgumentException(
102:                 "The argument " + handle + "is not a namespace.");
103:         }
104:         Object/*MNamespace*/ ns = handle;
105:         return CollaborationsHelper.getHelper().isAddingCollaborationAllowed(ns);
106:     }
107: 
108:     /**
109:      * Just calls isValidNamespace(...) on the nav pane target.
110:      * @see org.argouml.uml.ui.UMLAction#shouldBeEnabled()
111:      */
112:     public boolean shouldBeEnabled() {
113: 
114:         Object target = TargetManager.getInstance().getModelTarget();
