201:     public AbstractArgoJPanel spawn() {
202: 	TabResults newPanel = (TabResults) super.spawn();
203: 	if (newPanel != null) {
204: 	    newPanel.setResults(results, diagrams);
205: 	}
206: 	return newPanel;
207:     }
