252:         if (ModelFacade.isABase(theNewTarget) || ModelFacade.isADiagram(theNewTarget)) {
253:             if (ModelFacade.isABase(_target)) {
254:                 UmlModelEventPump.getPump()
255: 		    .removeModelEventListener(this,
256: 					      /*(MBase)*/_target,
257: 					      _eventName);
258:             }
259: 
260:             if (ModelFacade.isABase(theNewTarget)) {
261:                 _target = theNewTarget;
262:                 // UmlModelEventPump.getPump()
263:                 // .removeModelEventListener(this, (MBase)_target,
264:                 // _eventName);
265:                 UmlModelEventPump.getPump()
