82: /**
83:  * A datastructure that represents the designer's current project.  A
84:  *  Project consists of diagrams and UML models.
85:  */
86: public class Project implements java.io.Serializable, TargetListener {
87: 
88:     /** logger */
89:     private static final Logger LOG = Logger.getLogger(Project.class);
90:     
91:     ////////////////////////////////////////////////////////////////
92:     // constants
93: 
94:     private static final String ARGO_TEE = "/org/argouml/xml/dtd/argo.tee";
95: 
96:     /**
97:      * Default name for a project.
98:      */
99:     private static final String UNTITLED_FILE = "Untitled";
100: 
101:     ////////////////////////////////////////////////////////////////
102:     // static variables
103:     
104:     /**
