129:      * saved this project.
130:      */
131:     private int persistenceVersion;
132: 
133:     /**
134:      * Instances of the uml model.
135:      */
136:     private Vector _models;
137: 
138:     /**
139:      * Instances of the uml diagrams.
140:      */
141:     private Vector diagrams;
