676:             return;
677:         }
678:         java.util.Enumeration enumeration = getMembers().elements();
679:         try {
680:             while (enumeration.hasMoreElements()) {
681:                 ProjectMember pm = (ProjectMember) enumeration.nextElement();
682:                 if (type.equalsIgnoreCase(pm.getType())) {
683:                     pm.load();
684:                 }
685:             }
686:         } catch (IOException ignore) {
687:             LOG.error("IOException in makeEmptyProject", ignore);
688:         } catch (org.xml.sax.SAXException ignore) {
689:             LOG.error("SAXException in makeEmptyProject", ignore);
690:         }
691:     }
