898:     /** 
899:      * Finds a classifier with a certain name.<p>
900:      * 
901:      * Will only return first classifier with the matching name.
902:      *
903:      * @param s is short name.
904:      * @param ns Namespace where we do the search.
905:      * @return the found classifier (or <tt>null</tt> if not found).
906:      */
907:     public Object findTypeInModel(String s, Object ns) {
908:         
909:         if (!ModelFacade.isANamespace(ns)) {
910:             throw new IllegalArgumentException();
911:     	}
912:         
913:         Collection allClassifiers =
914:             ModelManagementHelper.getHelper()
915: 	        .getAllModelElementsOfKind(ns, (Class) ModelFacade.CLASSIFIER);
916:         
917:         Object[] classifiers = allClassifiers.toArray();
918:         Object classifier = null;
919:         
920:         for (int i = 0; i < classifiers.length; i++) {
921:             
922:             classifier = classifiers[i];
923:             if (ModelFacade.getName(classifier) != null
924:             		&& ModelFacade.getName(classifier).equals(s)) {
925:                 return classifier;
926:             }
927:         }
928:         
929:         return null;
930:     }
