987:     protected void removeDiagram(ArgoDiagram d) {
988:         diagrams.removeElement(d);
989:         // if the diagram is a statechart,
990:         // remove its associated statemachine model elements
991:         if (d instanceof UMLStateDiagram) {
992:             UMLStateDiagram statediagram = (UMLStateDiagram) d;
