53:      */
54:     protected void setUp() throws Exception {
55:         super.setUp();
56:         Object mmodel =
57:             Model.getModelManagementFactory().createModel();
58:         Model.getCoreHelper().setName(mmodel, "untitledModel");
59:         Model.getModelManagementFactory().setRootModel(mmodel);
60:         elem = Model.getUseCasesFactory().createInclude();
61:         model = new UMLIncludeAdditionComboBoxModel();
62:         model.targetSet(new TargetEvent(this, "set", new Object[0],
63:                 new Object[] {elem}));
64:         additions = new Object[10];
65:         Object m = Model.getModelManagementFactory().createModel();
66:         ProjectManager.getManager().getCurrentProject().setRoot(m);
67:         Model.getCoreHelper().setNamespace(elem, m);
68:         for (int i = 0; i < 10; i++) {
69:             additions[i] = Model.getUseCasesFactory().createUseCase();
70:             Model.getCoreHelper().addOwnedElement(m, additions[i]);
71:         }
72:     }
73: 
