347:     /**
348:      * @param m the member to be added
349:      */
350:     public void addMember(Object m) {
351: 
352:         if (m == null) {
353:             throw new IllegalArgumentException(
354:                     "A model member must be suppleid");
355:         } else if (m instanceof ArgoDiagram) {
356:             LOG.info("Adding diagram member");
357:             addDiagramMember((ArgoDiagram) m);
358:         } else if (m instanceof ProjectMemberTodoList) {
359:             LOG.info("Adding todo member");
360:             addTodoMember((ProjectMemberTodoList) m);
361:         } else if (Model.getFacade().isAModel(m)) {
362:             LOG.info("Adding model member");
363:             addModelMember(m);
364:         } else {
365:             throw new IllegalArgumentException(
366:                     "The member must be a UML model todo member or diagram."
367:                     + "It is " + m.getClass().getName());
368:         }
369:         LOG.info("There are now " + members.size() + " members");
370:     }
371: 
372:     /**
373:      * @param m the model
374:      */
375:     private void addModelMember(Object m) {
376: 
377:         boolean memberFound = false;
378:         Object currentMember =
379:             members.getMember(ProjectMemberModel.class);
380:         if (currentMember != null) {
381:             Object currentModel =
382:                 ((ProjectMemberModel) currentMember).getModel();
383:             if (currentModel == m) {
384:                 memberFound = true;
385:             }
386:         }
387: 
388:         if (!memberFound) {
389:             if (!models.contains(m)) {
390:                 addModel(m);
391:             }
392:             // got past the veto, add the member
393:             ProjectMember pm = new ProjectMemberModel(m, this);
394:             LOG.info("Adding model member to start of member list");
395:             members.add(pm);
396:         } else {
397:             LOG.info("Attempted to load 2 models");
398:             throw new IllegalArgumentException(
399:                     "Attempted to load 2 models");
400:         }
401:     }
