775:     /**
776:      * Removes a diagram from the list with diagrams.
777:      *
778:      * Removes (hopefully) the event listeners for this diagram.  Does
779:      * not remove the diagram from the project members. This should
780:      * not be called directly. Use moveToTrash if you want to remove a
781:      * diagram.
782:      *
783:      * @param d the ArgoDiagram
784:      */
785:     protected void removeDiagram(ArgoDiagram d) {
786:         d.removeVetoableChangeListener(new Vcl());
787:         diagrams.removeElement(d);
788:         if (d instanceof UMLDiagram) {
789:             /* If this is a UML diagram, then remove the dependent
790:              * modelelements, such as the statemachine
791:              * for a statechartdiagram.
792:              */
793:             Object o = ((UMLDiagram) d).getDependentElement();
794:             if (o != null) {
