425:         if (activeDiagram == d) {
426:             ArgoDiagram defaultDiagram;
427:             if (diagrams.size() == 1) {
428:                 // We're deleting the last diagram so lets create a new one
429:                 // TODO: Once we go MDI we won't need this.
430:                 Object treeRoot = 
431:                     Model.getModelManagementFactory().getRootModel();
432:                 defaultDiagram =
433:                     DiagramFactory.getInstance()
434:                         .createDiagram(UMLClassDiagram.class, treeRoot, null);
435:                 addMember(defaultDiagram);
436:             } else {
437:                 // Make the topmost diagram (that is not the one being deleted)
438:                 // current.
439:                 defaultDiagram = (ArgoDiagram) diagrams.get(0);
440:                 if (defaultDiagram == d) {
441:                     defaultDiagram = (ArgoDiagram) diagrams.get(1);
442:                 }
443:             }
444:             activeDiagram = defaultDiagram;
445:             TargetManager.getInstance().setTarget(defaultDiagram);
446:         }
447: 
448:         removeDiagram(d);
449:         members.remove(d);
450:         d.remove();
451:         ProjectManager.getManager().setSaveEnabled(true);
452:     }
