674:      * Will only return first classifier with the matching name.
675:      *
676:      * @param s is short name.
677:      * @param ns Namespace where we do the search.
678:      * @return the found classifier (or <code>null</code> if not found).
679:      */
680:     public Object findTypeInModel(String s, Object ns) {
681: 
682:         if (!Model.getFacade().isANamespace(ns)) {
683:             throw new IllegalArgumentException(
684:                     "Looking for the classifier " + s
685:                     + " in a non-namespace object of " + ns
686:                     + ". A namespace was expected.");
687:     	}
688: 
689:         Collection allClassifiers =
690:             Model.getModelManagementHelper()
691: 	        .getAllModelElementsOfKind(ns,
692: 	                Model.getMetaTypes().getClassifier());
693: 
694:         Object[] classifiers = allClassifiers.toArray();
695:         Object classifier = null;
696: 
697:         for (int i = 0; i < classifiers.length; i++) {
698: 
699:             classifier = classifiers[i];
700:             if (Model.getFacade().getName(classifier) != null
701:             		&& Model.getFacade().getName(classifier).equals(s)) {
702:                 return classifier;
703:             }
704:         }
705: 
706:         return null;
707:     }
