1248:     public void remove() {
1249: 
1250:         if (diagrams != null) {
1251:             for (Iterator it = diagrams.iterator(); it.hasNext();) {
1252:                 Diagram diagram = (Diagram) it.next();
1253:                 diagram.remove();
1254:             }
1255:         }
1256:         
1257:         if (members != null) {
1258:             members.clear();
1259:         }
1260: 
1261:         if (models != null) {
1262:             for (Iterator it = models.iterator(); it.hasNext();) {
1263:                 Object model = it.next();
1264:                 LOG.debug("Deleting project model " 
1265:                         + Model.getFacade().getName(model));
1266:                 Model.getUmlFactory().delete(model);
1267:             }
1268:             models.clear();
1269:         }
1270:         
1271:         if (defaultModel != null) {
1272:             LOG.debug("Deleting profile model " 
1273:                     + Model.getFacade().getName(defaultModel));
1274:             Model.getUmlFactory().delete(defaultModel);
1275:             defaultModel = null;
1276:         }
1277: 
1278:         if (diagrams != null) {
1279:             diagrams.clear();
1280:         }
1281: 
1282:         if (uuidRefs != null) {
1283:             uuidRefs.clear();
1284:         }
1285: 
1286:         if (defaultModelTypeCache != null) {
1287:             defaultModelTypeCache.clear();
1288:         }
1289: 
1290:         members = null;
1291:         models = null;
