519: class ActionAttr extends UMLAction {
520:   // needs-more-work: should be part of java binding or common elements
521:   public static DataType INT_TYPE = new DataType("int");
522: 
523:   public ActionAttr() { super("Attribute"); }
524: 
525:   public void actionPerformed(ActionEvent e) {
526:     ProjectBrowser pb = ProjectBrowser.TheInstance;
527:     Object target = pb.getTarget();
528:     if (!(target instanceof Classifier)) return;
529:     Classifier cls = (Classifier) target;
530:     try {
531:       Attribute attr = new Attribute("newAttr", INT_TYPE, "0");
532:       attr.setVisibility(VisibilityKind.PUBLIC);
533:       cls.addStructuralFeature(attr);
534:     }
535:     catch (PropertyVetoException pve) {
536:       System.out.println("PropertyVetoException in ActionOper");
537:     }
538:   }
539: 
540:   public boolean shouldBeEnabled() {
541:     ProjectBrowser pb = ProjectBrowser.TheInstance;
542:     Object target = pb.getTarget();
543:     return super.shouldBeEnabled() && target instanceof Classifier;
544:   }
545: } /* end class ActionAttr */
