315:   public void parseStateBody(MState st, String s) {
316:     Collection trans = new ArrayList();
317:     java.util.StringTokenizer lines = new java.util.StringTokenizer(s, "\n\r");
318:     while (lines.hasMoreTokens()) {
319:       String line = lines.nextToken().trim();
320:       if (line.startsWith("entry")) parseStateEntyAction(st, line);
321:       else if (line.startsWith("exit")) parseStateExitAction(st, line);
322:       else {
323: 		MTransition t = parseTransition(line);
324: 		if (t == null) continue;
325: 		//System.out.println("just parsed:" + GeneratorDisplay.Generate(t));
326: 		trans.add(t);
327:       }
328:     }
329:     st.setInternalTransitions(trans);
330:   }
