138:     String visStr = s.substring(0, firstSpace);
139:     MVisibilityKind vk = MVisibilityKind.PUBLIC;
140:     if (visStr.equals("public") || s.startsWith("+"))
141:       vk = MVisibilityKind.PUBLIC;
142:     else if (visStr.equals("private") || s.startsWith("-"))
143:       vk = MVisibilityKind.PRIVATE;
144:     else if (visStr.equals("protected") || s.startsWith("#"))
145:       vk = MVisibilityKind.PROTECTED;
146: 	//    else if (visStr.equals("package") || s.startsWith("~"))
147: 	// vk = MVisibilityKind.PACKAGE;
148:     else {
149:       System.out.println("unknown visibility \"" + visStr +
150: 			 "\", using default");
151:       return s;
152:     }
153:      f.setVisibility(vk);
154: 
155:     if (s.startsWith("+") || s.startsWith("-") ||
156: 	s.startsWith("#") || s.startsWith("~"))
157:       s = s.substring(1);
158:     else
159:       s = s.substring(firstSpace+1);
160:     return s;
