168: 
169:       if (visStr.equals("static"))
170: 	f.setOwnerScope(MScopeKind.CLASSIFIER);
171:       else if (visStr.equals("synchronized") && (f instanceof MOperation))
172: 	((MOperation)f).setConcurrency(MCallConcurrencyKind.GUARDED);
173:       else if (visStr.equals("transient"))
