357:       name = s.substring(0, s.indexOf(":")).trim();
358:       s = s.substring(s.indexOf(":") + 1).trim();
359:     }
360: 
361:     if (s.indexOf("[", 0) > -1 && s.indexOf("]", 0) > -1) {
362:       guard = s.substring(s.indexOf("[", 0)+1, s.indexOf("]")).trim();
363:       s = s.substring(0, s.indexOf("[")) + s.substring(s.indexOf("]")+1);
364:       s = s.trim();
365:     }
366: 
367:     if (s.indexOf("/", 0) > -1) {
368:       actions = s.substring(s.indexOf("/")+1).trim();
369:       s = s.substring(0, s.indexOf("/")).trim();
370:     }
371: 
372:     trigger = s;
373: 
