163:   public String parseOutKeywords(MFeature f, String s) {
164:     s = s.trim();
165:     int firstSpace = s.indexOf(" ");
166:     if (firstSpace == -1) return s;
167:     String visStr = s.substring(0, firstSpace);
168: 
169:       if (visStr.equals("static"))
170: 	f.setOwnerScope(MScopeKind.CLASSIFIER);
171:       else if (visStr.equals("synchronized") && (f instanceof MOperation))
172: 	((MOperation)f).setConcurrency(MCallConcurrencyKind.GUARDED);
173:       else if (visStr.equals("transient"))
174: 	System.out.println("'transient' keyword is currently ignored");
175:       else if (visStr.equals("final"))
176: 	System.out.println("'final' keyword is currently ignored");
177:       else if (visStr.equals("abstract"))
178: 	System.out.println("'abstract' keyword is currently ignored");
179:       else {
180: 	return s;
181:       }
182: 
183:     return parseOutKeywords(f, s.substring(firstSpace+1));
184:   }
