470:   /** Parse a line of the form: "name: base-class" */
471:   public void parseObject(MObject obj, String s) {
472:     // strip any trailing semi-colons
473:     s = s.trim();
474:     if (s.length() == 0) return;
475:     if (s.charAt(s.length()-1) == ';')
476:       s = s.substring(0, s.length() - 2);
477: 
478:     String name = "";
479:     String bases = "";
480:     String base = "";
481:     if (s.indexOf(":", 0) > -1) {
482:       name = s.substring(0, s.indexOf(":")).trim();
483:       bases = s.substring(s.indexOf(":") + 1).trim();
484:       if (bases.indexOf(":", 0) > 1) {
485:         base = bases.substring(0, bases.indexOf(":")).trim();
486:       }
487:       else base = bases;
488:     }
489:     else {
490:       name = s;
491:     }
492: 
493:     Collection col = obj.getClassifiers();
494:     if ((col != null) && (col.size()>0)) { 
495:       Iterator itcol = col.iterator(); 
496:       while (itcol.hasNext()) { 
497:         MClassifier cls = (MClassifier) itcol.next(); 
498:         obj.removeClassifier(cls); 
499:       } 
500:     } 
501: 
502:     Vector diagrams = ProjectBrowser.TheInstance.getProject().getDiagrams();
503:     Vector v = new Vector();
504:     MClass classifier = new MClassImpl();
505:     GraphModel model = null;
506:     int size = diagrams.size();
507:     for (int i=0; i<size; i++) {
508:       Object o = diagrams.elementAt(i);
509:       if (!(o instanceof Diagram)) continue;
510:       if (o instanceof MModel) continue;
511:       Diagram d = (Diagram) o;
512:       model = d.getGraphModel(); 
513:       if (!(model instanceof ClassDiagramGraphModel || model instanceof DeploymentDiagramGraphModel)) continue;
514:        
515:       Vector nodes = model.getNodes();
516:       int si = nodes.size();
517:       for (int j=0; j<si; j++) {
518:         MModelElement node = (MModelElement) nodes.elementAt(j);
519:         if (node != null && (node instanceof MClassImpl)) {
520:           MClass mclass = (MClass) node;
521:           if (mclass.getNamespace() != obj.getNamespace()) continue;
522:           String class_name = mclass.getName();
523:           if (class_name != null && (class_name.equals(base))) {
524:             v.addElement(mclass);
525:             obj.setClassifiers(v);
526:             obj.setName(new String(name)); 
527:             return; 
528:           }      
529:         }
530:       }
531:     }
532:     classifier.setName(base);
533:     
534:     v.addElement(classifier);
535:     obj.setClassifiers(v);
536:     obj.setName(new String(name));
537: 
538:   }
