53:     java.util.StringTokenizer st = new java.util.StringTokenizer(s, "\n\r");
54:     List newOps = new ArrayList();
55:     while (st.hasMoreTokens()) {
56:       String token = st.nextToken();
57:       MOperation op = parseOperation(token);
58:       newOps.add(op);
59:     }
60:     // System.out.println("parsed " + newOps.size() + " operations");
61: 	Vector features = new Vector(cls.getFeatures());
62: 	Vector oldOps = new Vector(MMUtil.SINGLETON.getOperations(cls));
