65: 	// don't forget to remove old Operations!
66: 	for (int i = 0; i < oldOps.size(); i++)
67: 		((MOperation)oldOps.elementAt(i)).remove();
68: 	features.addAll(newOps);
69: 	cls.setFeatures(features);
70:   }
