141:       vk = MVisibilityKind.PUBLIC;
142:     else if (visStr.equals("private") || s.startsWith("-"))
143:       vk = MVisibilityKind.PRIVATE;
144:     else if (visStr.equals("protected") || s.startsWith("#"))
