466:     /**
467:      * Every classifier role has a state and a caller list.
468:      * The state is PRECREATED before a node is created
469:      * and DESTROYED after classifier role is
470:      * destroyed.
471:      * The state is INITIAL before anything happens
472:      * After a classifier is created, the state is CREATED and
473:      * the state for prior nodes is set to PRECREATED
474:      * If the classifier does something:<p>
475:      *
476:      * If the state is INITIAL, the state for that and prior
477:      * nodes becomes DONE_SOMETHING_NO_CALL<p>
478:      *
479:      * else if the state is IMPLICIT_RETURNED, the state for that
480:      * and prior nodes becomes CALLED<p>
481:      *
482:      * Otherwise, the state doesn't change<p>
483:      *
484:      * If the classifier is called:<p>
485:      *
486:      * If the caller list is empty, the state becomes CALLED<p>
487:      *
488:      * The caller is added to the caller list<p>
489:      *
490:      * If the classifier returns, the caller being returned to and any callers
491:      * added to the list since that call are removed from the caller list.
492:      * If the caller list is empty the state becomes RETURNED.<p>
493:      *
494:      * If nothing happens on the node:<p>
495:      *
496:      * If the previous state was CALLED, the state becomes IMPLICIT_RETURNED<p>
497:      *
498:      * Otherwise, the state is the same as the previous node's state<p>
499:      *
500:      * Start or stop a rectangle when the state changes.
501:      *
502:      */
503:     private void updateNodeStates() {
504:         int lastState = MessageNode.INITIAL;
505:         ArrayList callers = null;
506:         int nodeCount = linkPositions.size();
507:         Rectangle fmpBounds = new Rectangle();
508: 
509:         for (int i = 0; i < nodeCount; ++i) {
510:             MessageNode node = (MessageNode) linkPositions.get(i);
511:             FigMessagePort fmp = node.getFigMessagePort();
512:             // If the node has a FigMessagePort
513:             if (fmp != null) {
514:                 fmpBounds = fmp.getBounds(fmpBounds);
515:                 int fmpY = getYCoordinate(i);
516:                 if (fmpBounds.y != fmpY) {
517:                     fmpBounds.y = fmpY;
518:                     fmp.setBounds(fmpBounds);
519:                 }
520:                 Object message = fmp.getOwner();
521:                 boolean selfMessage =
522: 		    (Model.getFacade().isAMessage(message)
523: 		     && (Model.getFacade().getSender(message)
524: 			 == Model.getFacade().getReceiver(message)));
525:                 boolean selfReceiving = false;
526:                 if (selfMessage) {
527:                     for (int j = i - 1; j >= 0; --j) {
528:                         MessageNode prev = (MessageNode) linkPositions.get(j);
529:                         FigMessagePort prevmp = prev.getFigMessagePort();
530:                         if (prevmp != null && prevmp.getOwner() == message) {
531:                             selfReceiving = true;
532: 			}
533:                     }
534:                 }
535:                 if (isCallMessage(message)) {
536:                     if (Model.getFacade().getSender(message) == getOwner()
537:                          && !selfReceiving) {
538:                         lastState = setFromActionNode(lastState, i);
539:                         node.setState(lastState);
540:                         node.setCallers(callers);
541:                     } else {
542: 			if (lastState == MessageNode.INITIAL
543: 			    || lastState == MessageNode.CREATED
544: 			    || lastState == MessageNode.IMPLICIT_CREATED
545: 			    || lastState == MessageNode.IMPLICIT_RETURNED
546: 			    || lastState == MessageNode.RETURNED) {
547: 
548:                             lastState = MessageNode.CALLED;
549: 
550: 			}
551: 
552:                         if (callers == null) {
553:                             callers = new ArrayList();
554: 			} else {
555:                             callers = new ArrayList(callers);
556: 			}
557:                         callers.add(Model.getFacade().getSender(message));
558:                         node.setState(lastState);
559:                         node.setCallers(callers);
560:                     }
561:                 } else if (isReturnMessage(message)) {
562:                     if (lastState == MessageNode.IMPLICIT_RETURNED) {
563:                         setPreviousState(i, MessageNode.CALLED);
564:                         lastState = MessageNode.CALLED;
565:                     }
566:                     if (Model.getFacade().getSender(message) == getOwner()
567: 			&& !selfReceiving) {
568:                         if (callers == null) {
569:                             callers = new ArrayList();
570:                         }
571:                         Object caller = Model.getFacade().getReceiver(message);
572:                         int callerIndex = callers.lastIndexOf(caller);
573:                         if (callerIndex != -1) {
574:                             for (int backNodeIndex = i - 1;
575:                                   backNodeIndex > 0
576: 				     && ((MessageNode) linkPositions
577: 					 .get(backNodeIndex))
578: 				     .matchingCallerList(caller, callerIndex);
579:                                   --backNodeIndex) {
580: 				;
581: 			    }
582:                             if (callerIndex == 0) {
583:                                 callers = null;
584:                                 if (lastState == MessageNode.CALLED) {
585:                                     lastState = MessageNode.RETURNED;
586: 				}
587:                             } else {
588:                                 callers =
589: 				    new ArrayList(callers.subList(0,
590: 								  callerIndex));
591:                             }
592:                         }
593:                     }
594:                     node.setState(lastState);
595:                     node.setCallers(callers);
596:                 } else if (isCreateMessage(message)) {
597:                     if (Model.getFacade().getSender(message) == getOwner()) {
598:                         lastState = setFromActionNode(lastState, i);
599:                         node.setState(lastState);
600:                         node.setCallers(callers);
601:                     } else {
602:                         lastState = MessageNode.CREATED;
603:                         setPreviousState(i, MessageNode.PRECREATED);
604:                         node.setState(lastState);
605:                         node.setCallers(callers);
606:                     }
607:                 } else if (isDestroyMessage(message)) {
608:                     if (Model.getFacade().getSender(message) == getOwner()
609:                          && !selfReceiving) {
610:                         lastState = setFromActionNode(lastState, i);
611:                         node.setState(lastState);
612:                         node.setCallers(callers);
613:                     } else {
614:                         lastState = MessageNode.DESTROYED;
615:                         callers = null;
616:                         node.setState(lastState);
617:                         node.setCallers(callers);
618:                     }
619:                 }
620:             } else {
621:                 if (lastState == MessageNode.CALLED) {
622:                     lastState = MessageNode.IMPLICIT_RETURNED;
623: 		}
624:                 if (lastState == MessageNode.CREATED) {
625:                     lastState = MessageNode.IMPLICIT_CREATED;
626: 		}
627:                 node.setState(lastState);
628:                 node.setCallers(callers);
629:             }
630:         }
631:     }
