452:     private int setFromActionNode(int lastState, int offset) {
453:         if (lastState == MessageNode.INITIAL) {
454: 	    lastState = MessageNode.DONE_SOMETHING_NO_CALL;
455:             setPreviousState(offset, lastState);
456:         } else if (lastState == MessageNode.IMPLICIT_RETURNED) {
457: 	    lastState = MessageNode.CALLED;
458:             setPreviousState(offset, lastState);
459:         } else if (lastState == MessageNode.IMPLICIT_CREATED) {
460: 	    lastState = MessageNode.CREATED;
461:             setPreviousState(offset, lastState);
462:         }
463:         return lastState;
464:     }
