1059:     /**
1060:      * Returns the port for a given coordinate pair. Normally
1061:      * deepHitPort returns the owner of the fig in the FigGroup that
1062:      * is present at the given coordinate pair (returning figs that
1063:      * are added later first). In this case it returns a
1064:      * MessagePort.<p>
1065:      *
1066:      * @see org.tigris.gef.presentation.FigNode#deepHitPort(int, int)
1067:      */
1068:     public Object deepHitPort(int x, int y) {
1069:         Rectangle rect = new Rectangle(getX(), y - 16, getWidth(), 32);
1070:         MessageNode foundNode = null;
1071:         if (lifeLine.intersects(rect)) {
1072:             for (int i = 0; i < linkPositions.size(); i++) {
1073:                 MessageNode node = (MessageNode) linkPositions.get(i);
1074:                 int position = getYCoordinate(i);
1075:                 if (i < linkPositions.size() - 1) {
1076:                     int nextPosition =
1077:                         getYCoordinate(i + 1);
1078:                     if (nextPosition >= y && position <= y) {
1079:                         if ((y - position) <= (nextPosition - y)) {
1080:                             foundNode = node;
1081:                         } else {
1082:                             foundNode = (MessageNode) linkPositions.get(i + 1);
1083:                         }
1084:                         break;
1085:                     }
1086:                 } else {
1087:                     foundNode =
1088:                         (MessageNode) linkPositions
1089: 			.get(linkPositions.size() - 1);
1090:                     MessageNode nextNode;
1091: 		    nextNode = new MessageNode(this);
1092:                     linkPositions.add(nextNode);
1093:                     int nextPosition = getYCoordinate(i + 1);
1094:                     if ((y - position) >= (nextPosition - y)) {
1095:                         foundNode = nextNode;
1096: 		    }
1097:                     break;
1098:                 }
1099:             }
1100: 
1101:         } else if (headFig.intersects(rect)) {
1102:             foundNode = getClassifierRoleNode();
1103:         } else {
1104:             return null;
1105:         }
1106:         setMatchingFig((MessageNode) foundNode);
1107:         return foundNode;
1108:     }
