317:     public void setBoundsImpl(int x, int y, int w, int h) {
318:         Rectangle oldBounds = getBounds();
319:         if (getNameFig().getWidth() > w) {
320:             w = getNameFig().getWidth() + 2 * MARGIN;
321:         }
322:         if (getStereotypeFig().getWidth() > w) {
323:             w = getStereotypeFig().getWidth() + 2 * MARGIN;
324:         }
325:         getNameFig().setCenter(
326:             new Point(x + w / 2,
327: 		      getNameFig().getY() - oldBounds.y + y
328: 		      + getNameFig().getHeight() / 2));
329:         getStereotypeFig().setCenter(
330:             new Point(
331:                 x + w / 2,
332:                 (getStereotypeFig().getY() - oldBounds.y
333: 		 + y + getStereotypeFig().getHeight() / 2)));
334:         reSize(headFig, x, y, w, h);
335:         lifeLine.setBounds(
336:                 headFig.getX() + headFig.getWidth() / 2,
337:                 headFig.getY() + headFig.getHeight(),
338:             0,
339:             h - headFig.getHeight());
340:         for (Iterator figIt = getFigs().iterator(); figIt.hasNext();) {
341:             Fig fig = (Fig) figIt.next();
342:             if (activationFigs.contains(fig) || fig instanceof FigMessagePort) {
343:                 fig.setBounds(
344:                         headFig.getX()
345: 		    + headFig.getWidth() / 2
346: 		    - fig.getWidth() / 2,
347:                     y - oldBounds.y + fig.getY(),
348:                     fig.getWidth(),
349:                     fig.getHeight());
350:             }
351:         }
352:         growToSize(lifeLine.getHeight() / SequenceDiagramLayout.LINK_DISTANCE
353:                 + 2);
354:         calcBounds(); //_x = x; _height = y; _w = w; _h = h;
355:         firePropChange("bounds", oldBounds, getBounds());
356:     }
