442:     private void setPreviousState(int start, int newState) {
443:         for (int i = start - 1; i >= 0; --i) {
444:             MessageNode node = (MessageNode) linkPositions.get(i);
445:             if (node.getFigMessagePort() != null) {
446:                 break;
447:             }
448:             node.setState(newState);
449:         }
450:     }
