128:                 while (iter.hasNext()) {
129:                     ownedElement = iter.next();
130:                     targetName = ModelFacade.getName(ownedElement);
131:                     if (targetName != null && phantomName.equals(targetName)) {
132:                         if (ModelFacade.isAPackage(ownedElement)) {
