227:     /**
228:      * @see java.awt.event.ActionListener#actionPerformed(ActionEvent)
229:      */
230:     public void actionPerformed(ActionEvent e) {
231: 	Object source = e.getSource(); 
232: 	if (source.equals(_addButton)) {
233: 	    addSelection();
234: 	    update();
235: 	}
236: 	if (source.equals(_removeButton)) {
237: 	    removeSelection();
238: 	    update();
239: 	}
240: 	if (source.equals(_okButton)) {
241: 	    ok();
242: 	}
243: 	if (source.equals(_cancelButton)) {
244: 	    cancel();
245: 	}
246:     }
247: 	
248:     /**
249:      * Updates the add and remove button (sets
250:      * enabled/disabled). Called whenever the model is changed.
251:      */
252:     public void update() {
253: 	if (_choices.size() == 0) {
254: 	    _addButton.setEnabled(false);
255: 	} else {
256: 	    _addButton.setEnabled(true);
257: 	}
258: 	if (_selected.size() == 0) {
259: 	    _removeButton.setEnabled(false);
260: 	} else {
261: 	    _removeButton.setEnabled(true);
262: 	}
263:     }
264: 	
265:     /**
266:      * Utility method to construct a DefaultListModel from a Vector
267:      * @param vec
268:      * @return DefaultListModel
269:      */
270:     protected DefaultListModel constructListModel(Vector vec) {
271: 	DefaultListModel model = new DefaultListModel();
272: 	for (int i = 0; i < vec.size(); i++) {
273: 	    model.addElement(vec.get(i));
274: 	}
275: 	return model;		
276:     }
277: 	
278:     /**
279:      * Shows the dialog. First a dialog must be constructed using one
280:      * of the constructors of this class.  After that this method
281:      * should be called to actually show the dialog. This method
282:      * returns either JOptionPane.OK_OPTION if the user wants to
283:      * select his choices or JOptionPane.CANCEL_OPTION if he does not
284:      * want to.
285:      *
286:      * @param parent The parent frame of this dialog.
287:      * @return int The returnvalue, can be either
288:      * JOptionPane.OK_OPTION or JOptionPane.CANCEL_OPTION
289:      */
290:     public int showDialog(Component parent) {
291: 	Frame frame = parent instanceof Frame ? (Frame) parent
292: 	    : (Frame) SwingUtilities.getAncestorOfClass(Frame.class, parent);
293: 
294: 	// String title = getUI().getDialogTitle(this);
295: 
296:         _dialog = new JDialog(frame, _title, true);
297:         Container contentPane = _dialog.getContentPane();
298:         contentPane.setLayout(new BorderLayout());
299:         contentPane.add(this, BorderLayout.CENTER);
300:  
301: 	_dialog.setDefaultCloseOperation(JDialog.DO_NOTHING_ON_CLOSE);
302: 	_dialog.addWindowListener(new WindowAdapter() {
303:     	    public void windowClosing(WindowEvent we) {
304: 		cancel();
305: 	    }
306: 	});
307: 
308:         _dialog.pack();
309:         _dialog.setLocationRelativeTo(parent);
310:  
311:         _dialog.show();
312: 	return _returnValue;
313:     }
314: 	
315:     /**
316:      * Returns the choices a user can make.
317:      * @return Vector
318:      */
319:     public Vector getChoices() {
320: 	int[] indices = _choicesList.getSelectedIndices();
321: 	Vector returnVector = new Vector();
322: 	for (int i = 0; i < indices.length; i++) {
323: 	    returnVector.add(_choices.get(indices[i]));
324: 	}
325: 	return returnVector;
326:     }
327: 	
328:     /**
329:      * Returns the selected elements in the selected list
330:      * @return Vector
331:      */
332:     public Vector getSelectedChoices() {
333: 	Vector returnVector = new Vector();
334: 	if (_selectedList != null && _selected != null) {
335: 	    int[] indices = _selectedList.getSelectedIndices();			
336: 	    for (int i = 0; i < indices.length; i++) {
337: 		returnVector.add(_selected.get(indices[i]));
338: 	    }
339: 	}
340: 	return returnVector;
341:     }
342: 	
343:     /**
344:      * Returns the by the user selected elements. This method should
345:      * be called if the selected choices are to be known.
346:      *
347:      * @return Vector
348:      */
349:     public Vector getSelected() {
350: 	return _selected;
351:     }
352: 	
353:     /**
354:      * Adds the selected elements in the choices list to the selected
355:      * list. Updates the GUI too.
356:      */
357:     public void addSelection() {
358: 	Vector choices = getChoices();
359: 	_choices.removeAll(choices);
360: 	for (int i = 0; i < choices.size(); i++) {
361: 	    ((DefaultListModel) _choicesList.getModel()).removeElement(choices.get(i));
362: 	}
363: 	_selected.addAll(choices);
364: 	for (int i = 0; i < choices.size(); i++) {
365: 	    ((DefaultListModel) _selectedList.getModel()).addElement(choices.get(i));
366: 	}
367:     }
368: 	
369:     /**
370:      * Removes the selected elements in the selected list and adds
371:      * them to the choices list. Updates the GUI too.
372:      */
373:     public void removeSelection() {
374: 	Vector choices = getSelectedChoices();
375: 	_selected.removeAll(choices);
376: 	for (int i = 0; i < choices.size(); i++) {
377: 	    ((DefaultListModel) _selectedList.getModel()).removeElement(choices.get(i));
378: 	}
379: 	_choices.addAll(choices);
380: 	for (int i = 0; i < choices.size(); i++) {
381: 	    ((DefaultListModel) _choicesList.getModel()).addElement(choices.get(i));
382: 	}
383:     }
384: 	
385:     /**
386:      * Called when the okbutton is pressed. Closes this dialog and
387:      * sets the returnvalue to JOptionPane.OK_OPTION.
388:      */
389:     public void ok() {
390: 	if (_dialog != null) {
391: 	    _dialog.setVisible(false);
392: 	    _returnValue = JOptionPane.OK_OPTION;
393: 	}
394:     }
395: 	
396:     /**
397:      * Called when the cancel button is pressed. Closes this dialog
398:      * and sets the returnvalue to JOptionPane.CANCEL_OPTION.  Resets
399:      * the selected list to the originally preselection if there is
400:      * one. Otherwise the selected list is emptied.
401:      */
402:     public void cancel() {
403: 	_selected.removeAllElements();
404: 	if (_preSelected != null) {
405: 	    _selected.addAll(_preSelected);
406: 	}
407: 	if (_dialog != null) {
408: 	    _dialog.setVisible(false);
409: 	    _returnValue = JOptionPane.CANCEL_OPTION;
410: 	}
411:     }
412: }
