136:       _botMargin >= 0 && _leftMargin >= 0 && _rightMargin >= 0 &&
137:       (_justification == JUSTIFY_LEFT || _justification == JUSTIFY_CENTER ||
138:        _justification == JUSTIFY_RIGHT) && _textColor != null &&
139:       _textFillColor != null;
