141:   ////////////////////////////////////////////////////////////////
142:   // accessors
143: 
144:   /** Reply a string that indicates how the text is justified: Left,
145:    *  Center, or Right. */
146:   public String alignmentByName() {
147:     // needs-more-work: index into static array?
148:     // return _AlignmentNames[_alignment];
149:     if (_justification == JUSTIFY_LEFT) return "Left";
150:     else if (_justification == JUSTIFY_CENTER) return "Center";
151:     else if (_justification == JUSTIFY_RIGHT) return "Right";
152:     System.out.println("internal error, unknown text alignment");
153:     return "Unknown";
154:   }
155: 
156:   /** Set the text justification given one of these strings: Left,
157:    *  Center, or Right. */
158:   public void alignmentByName(String alignString) {
159:     if (alignString.equals("Left")) _justification = JUSTIFY_LEFT;
160:     else if (alignString.equals("Center")) _justification = JUSTIFY_CENTER;
161:     else if (alignString.equals("Right")) _justification = JUSTIFY_RIGHT;
162:     _fm = null;
