340:   /** Compute the overall width and height of the FigText object based
341:    *  on the font, font size, and current text. Needs-More-Work: Right
342:    *  now text objects can get larger when you type more, but they
343:    *  do not get smaller when you backspace.  */
344:   protected void calcBounds() {
345:     if (_font == null) return;
346:     if (_fm == null) _fm = Toolkit.getDefaultToolkit().getFontMetrics(_font);
347:     int overallW = 0;
348:     int numLines = 1;
349:     StringTokenizer lines = new StringTokenizer(_curText, "\n\r", true);
350:     while (lines.hasMoreTokens()) {
351:       String curLine = lines.nextToken();
352:       int chunkW = _fm.stringWidth(curLine);
353:       if (curLine.equals("\n") || curLine.equals("\r")) numLines++;
354:       else overallW = Math.max(chunkW, overallW);
355:     }
356:     _lineHeight = _fm.getHeight();
357:     int maxDescent = _fm.getMaxDescent();
358:     int overallH = (_lineHeight + _lineSpacing) * numLines +
359:       _topMargin + _botMargin + maxDescent;
360:     overallW = Math.max(MIN_TEXT_WIDTH, overallW + _leftMargin + _rightMargin);
361:     switch (_justification) {
362:     case JUSTIFY_LEFT: break;
363:     case JUSTIFY_CENTER: if (_w < overallW) _x -= (overallW - _w) / 2; break;
364:     case JUSTIFY_RIGHT: if (_w < overallW) _x -= (overallW - _w); break;
365:     }
366:     _w = _expandOnly ? Math.max(_w, overallW) : overallW;
367:     _h = _expandOnly ? Math.max(_h, overallH) : overallH;
368:   }
