60:   protected FontMetrics _fm;
61:   protected int _lineHeight;
62: 
63:   /** Color of the actual text characters. */
64:   protected Color _textColor = Color.black;
65: 
66:   /** Color to be drawn behind the actual text characters. Note that
67:    *  this will be a smaller area than the bounding box which is
68:    *  filled with FillColor. */
69:   protected Color _textFillColor = Color.white;
70: 
71:   /** True if the area behind individual characters is to be filled
72:    *  with TextColor. */
73:   protected boolean _textFilled = false;
74:   protected boolean _underline = false;
75:   // needs-more-work: use insets instead
76:   protected int _lineSpacing = -4;
77:   protected int _topMargin = 1;
78:   protected int _botMargin = 1;
79:   protected int _leftMargin = 1;
80:   protected int _rightMargin = 1;
81: 
82:   /** True if the FigText can only grow in size, never shrink. */
83:   protected boolean _expandOnly = false;
84: 
85:   /** Text alignment can be JUSTIFY_LEFT, JUSTIFY_RIGHT, or JUSTIFY_CENTER. */
86:   protected int _alignment;
87: 
88:   /** The current string to display. */
89:   protected String _curText;
90: 
91:   ////////////////////////////////////////////////////////////////
92:   // static initializer
93:   static {
94:     PropCategoryManager.categorizeProperty("Text", "font");
95:     PropCategoryManager.categorizeProperty("Text", "underline");
96:     PropCategoryManager.categorizeProperty("Text", "expandOnly");
97:     PropCategoryManager.categorizeProperty("Text", "lineSpacing");
98:     PropCategoryManager.categorizeProperty("Text", "topMargin");
99:     PropCategoryManager.categorizeProperty("Text", "botMargin");
100:     PropCategoryManager.categorizeProperty("Text", "leftMargin");
101:     PropCategoryManager.categorizeProperty("Text", "rightMargin");
102:     PropCategoryManager.categorizeProperty("Text", "text");
103:     PropCategoryManager.categorizeProperty("Style", "alignment");
104:     PropCategoryManager.categorizeProperty("Style", "textFilled");
