115: 		 Color textColor, String familyName, int fontSize) {
116:     super(x, y, w, h);
117:     _x = x; _y = y; _w = w; _h = h;
118:     _textColor = textColor;
119:     _font = new Font(familyName, Font.PLAIN, fontSize);
120:     _alignment = JUSTIFY_CENTER;
