178: 
179:   public String getAlignment() { return alignmentByName(); }
180:   public void setAlignment(String align) { alignmentByName(align); }
181:   public int getLineSpacing() { return _lineSpacing; }
182:   public void setLineSpacing(int s) { _lineSpacing = s; calcBounds(); }
183: 
184:   public int getTopMargin() { return _topMargin; }
185:   public void setTopMargin(int m) { _topMargin = m; calcBounds(); }
186:   public int getBotMargin() { return _botMargin; }
187:   public void setBotMargin(int m) { _botMargin = m; calcBounds(); }
188:   public int getLeftMargin() { return _leftMargin; }
189:   public void setLeftMargin(int m) { _leftMargin = m; calcBounds(); }
190:   public int getRightMargin() { return _rightMargin; }
191:   public void setRightMargin(int m) { _rightMargin = m; calcBounds(); }
192: 
193:   public boolean getExpandOnly() { return _expandOnly; }
194:   public void setExpandOnly(boolean b) { _expandOnly = b; }
195: 
196:   public Font getFont() { return _font; }
197:   public void setFont(Font f) { _font = f; _fm = null; calcBounds(); }
198: 
199:   public boolean getItalic() { return _font.isItalic(); }
200:   public void setItalic(boolean b) {
201:     int style = (getBold() ? Font.BOLD : 0) + (b ? Font.ITALIC : 0);
202:     setFont(new Font(_font.getFamily(), _font.getSize(), style));
203:   }
204: 
205:   public boolean getBold() { return _font.isBold(); }
206:   public void setBold(boolean b) {
207:     int style = (b ? Font.BOLD : 0) + (getItalic() ? Font.ITALIC : 0);
208:     setFont(new Font(_font.getFamily(), _font.getSize(), style));
209:   }
210: 
211:   /** Remove the last char from the current string line and return the
212:    *  new string.  Called whenever the user hits the backspace key.
213:    *  Needs-More-Work: Very slow.  This will eventually be replaced by
214:    *  full text editing... if there are any volunteers to do that...*/
215:   public String deleteLastCharFromString(String inputString) {
216:     int len = Math.max(inputString.length() - 1, 0);
217:     char[] string_char = inputString.toCharArray();
218:     String new_string = new String(string_char,0, len);
219:     return new_string;
220:   }
221: 
222:   /** Delete the last char from the current string. Called whenever
223:    *  the user hits the backspace key */
224:   public void deleteLastChar() {
225:     _curText = deleteLastCharFromString(_curText);
226:     calcBounds();
227:   }
228: 
229:   /** Append a character to the current String .*/
230:   public void append(char c) { setText(_curText + c); }
231: 
232:   /** Append the given String to the current String. */
233:   public void append(String s) { setText(_curText + s); }
234: 
235:   /** set the current String to be the given String. */
236:   public void setText(String s) { _curText = s; calcBounds(); }
237: 
238:   /** Get the String held by this FigText. Multi-line text is
239:    *  represented by newline characters embedded in the String. */
240:   public String getText() { return _curText; }
241: 
242:   ////////////////////////////////////////////////////////////////
243:   // painting methods
244: 
245:   /** Paint the FigText. */
246:   public void paint(Graphics g) {
247:     int chunkX = _x + _leftMargin;
248:     int chunkY = _y + _topMargin;
249:     StringTokenizer lines;
250: 
251:     if (_filled) {
252:       g.setColor(_fillColor);
253:       g.fillRect(_x, _y, _w, _h);
254:     }
255:     if (_lineWidth > 0) {
256:       g.setColor(_lineColor);
257:       g.drawRect(_x - 1, _y - 1, _w + 1, _h + 1);
258:     }
259: 
260:     if (_font != null) g.setFont(_font);
261:     _fm = g.getFontMetrics(_font);
262:     int chunkH = _lineHeight + _lineSpacing;
263:     chunkY = _y + _topMargin + chunkH;
264:     if (_textFilled) {
265:       g.setColor(_textFillColor);
266:       lines = new StringTokenizer(_curText, "\n\r", true);
267:       while (lines.hasMoreTokens()) {
268: 	String curLine = lines.nextToken();
269: 	//if (curLine.equals("\r")) continue;
270: 	int chunkW = _fm.stringWidth(curLine);
271: 	switch (_alignment) {
272: 	case JUSTIFY_LEFT: break;
273: 	case JUSTIFY_CENTER: chunkX = _x + (_w - chunkW) / 2; break;
274: 	case JUSTIFY_RIGHT: chunkX = _x + _w - chunkW - _rightMargin; break;
275: 	}
276: 	if (curLine.equals("\n") || curLine.equals("\r")) chunkY += chunkH;
277: 	else g.fillRect(chunkX, chunkY - chunkH, chunkW, chunkH);
278:       }
279:     }
280: 
281:     g.setColor(_textColor);
282:     chunkX = _x + _leftMargin;
283:     chunkY = _y + _topMargin + _lineHeight + _lineSpacing;
284:     lines = new StringTokenizer(_curText, "\n\r", true);
285:     while (lines.hasMoreTokens()) {
286:       String curLine = lines.nextToken();
287:       //if (curLine.equals("\r")) continue;
288:       int chunkW = _fm.stringWidth(curLine);
289:       switch (_alignment) {
290:       case JUSTIFY_LEFT: break;
291:       case JUSTIFY_CENTER: chunkX = _x + ( _w - chunkW ) / 2; break;
292:       case JUSTIFY_RIGHT: chunkX = _x + _w  - chunkW; break;
293:       }
294:       if (curLine.equals("\n")  || curLine.equals("\r")) chunkY += chunkH;
295:       else g.drawString(curLine, chunkX, chunkY);
296:     }
297:   }
298: 
299: 
300: 
301:   ////////////////////////////////////////////////////////////////
302:   // event handlers
303: 
304:   /** When the user presses a key when a FigText is selected, that key
305:    *  should be added to the current string, or if the key was
306:    *  backspace, the last character is removed.  Needs-More-Work: Should
307:    *  also catch arrow keys and mouse clicks for full text
308:    *  editing... someday... */
309:   public void keyTyped(KeyEvent ke) {
310:     if (ke.getModifiers() != 0) return;
311:     char c = ke.getKeyChar();
312:     if (!Character.isISOControl(c)) {
313:       startTrans();
314:       append(c);
315:       endTrans();
316:       ke.consume();
317:     }
318:   }
319: 
320:   public void keyPressed(KeyEvent ke) {
321:     if (ke.getKeyCode() == KeyEvent.VK_BACK_SPACE) {
322:       startTrans();
323:       deleteLastChar();
324:       endTrans();
325:       ke.consume();
326:     }
327:     if (ke.getKeyCode() == KeyEvent.VK_ENTER) {
328:       startTrans();
329:       append('\n');
330:       endTrans();
331:       ke.consume();
332:     }
333:   }
334:   public void keyReleased(KeyEvent ke) { }
335: 
336:   
337:   ////////////////////////////////////////////////////////////////
338:   // internal utility functions
339: 
340:   /** Compute the overall width and height of the FigText object based
341:    *  on the font, font size, and current text. Needs-More-Work: Right
342:    *  now text objects can get larger when you type more, but they
343:    *  do not get smaller when you backspace.  */
344:   protected void calcBounds() {
345:     if (_font == null) return;
346:     if (_fm == null) _fm = Toolkit.getDefaultToolkit().getFontMetrics(_font);
347:     int overallW = 0;
348:     int numLines = 1;
349:     StringTokenizer lines = new StringTokenizer(_curText, "\n\r", true);
350:     while (lines.hasMoreTokens()) {
351:       String curLine = lines.nextToken();
352:       int chunkW = _fm.stringWidth(curLine);
353:       if (curLine.equals("\n") || curLine.equals("\r")) numLines++;
354:       else overallW = Math.max(chunkW, overallW);
355:     }
356:     _lineHeight = _fm.getHeight();
357:     int maxDescent = _fm.getMaxDescent();
358:     int overallH = (_lineHeight + _lineSpacing) * numLines +
359:       _topMargin + _botMargin + maxDescent;
360:     overallW = Math.max(MIN_TEXT_WIDTH, overallW + _leftMargin + _rightMargin);
361:     switch (_alignment) {
362:     case JUSTIFY_LEFT: break;
363:     case JUSTIFY_CENTER: if (_w < overallW) _x -= (overallW - _w) / 2; break;
364:     case JUSTIFY_RIGHT: if (_w < overallW) _x -= (overallW - _w); break;
365:     }
366:     _w = _expandOnly ? Math.max(_w, overallW) : overallW;
367:     _h = _expandOnly ? Math.max(_h, overallH) : overallH;
368:   }
369: 
370: } /* end class FigText */
