25: package org.argouml.kernel;
26: 
27: /**
28:  * A member of the project.
29:  *
30:  */
31: public abstract class AbstractProjectMember implements ProjectMember {
32: 
33:     ////////////////////////////////////////////////////////////////
34:     // instance varables
35: 
36:     private String name;
37:     private Project project = null;
38: 
39:     ////////////////////////////////////////////////////////////////
40:     // constructors
41: 
42:     /**
43:      * The constructor.
44:      * 
45:      * @param theName the name of the member
46:      * @param theProject the owning project
47:      */
48:     public AbstractProjectMember(String theName, Project theProject) {
49:         project = theProject;
50:         setName(theName);
51:     }
52: 
53:     /**
54:      * In contrast to {@link #getZipName} returns the member's name without the
55:      * prepended name of the project. This is the name that
56:      * {@link Project#findMemberByName} goes by.
57:      *
58:      * @author Steffen Zschaler
59:      *
60:      * @return the member's name without the prepended name of the project
61:      */
62:     public String getPlainName() {
63:         String s = name;
64:         
65:         if (s != null) {
66:             if (!s.endsWith (getFileExtension())) {
67:         	s += getFileExtension();
68:             }
69:         }
70:         
71:         return s;
72:     }
73: 
74:     /**
75:      * In contrast to {@link #getPlainName} returns the member's name
76:      * including the project's base name. The project's base name is
77:      * prepended followed by an underscore '_'.
78:      *
79:      * @return the member's name including the project's base name
80:      */
81:     public String getZipName() {
82:         if (name == null)
83:             return null;
84:         
85:         String s = project.getBaseName();
86:         
87:         if (name.length() > 0)
88:             s += "_" + name;
89:         
90:         if (!s.endsWith(getFileExtension()))
91:             s += getFileExtension();
92:         
93:         return s;
94:     }
95:   
96:     /**
97:      * @param s the name of the member
98:      */
99:     protected void setName(String s) {
100:         name = s;
101:         
102:         if (name == null) {
103:             return;
104:         }
105:         
106:         if (name.startsWith (project.getBaseName())) {
107:             name = name.substring (project.getBaseName().length());
108:             int i = 0;
109:             for (; i < name.length(); i++) {
110:             	if (name.charAt(i) != '_') {
111:             	    break;
112:                 }
113:             }
114:             if (i > 0) {
