71:         Object owner = getOwner();
72:         if (owner != null && Model.getFacade().isALink(owner)) {
73:             Iterator it = Model.getFacade().getStimuli(owner).iterator();
74:             Object stimulus = it.next();
75:             if (stimulus != null) {
76:                 return Model.getFacade().getDispatchAction(stimulus);
77:             }
