56: /**
57:  * Fig to show an object on a sequence diagram. The fig consists of an
58:  * upper box that shows the name of the object (the owner) and a
59:  * lifeline. The lifeline consists of lifeline elements. An element
60:  * can be a dashed line (no link attached) or a rectangle (link
61:  * attached).
62:  * @author jaap.branderhorst@xs4all.nl
63:  * Aug 11, 2003
64:  */
65: public class FigClassifierRole extends FigNodeModelElement implements MouseListener {
66:     /**
67:     * The width of an activation box
68:     */
69:     public static final int WIDTH = 20;
70: 
71:     /**
72:      * The margin between the outer box and the name and stereotype text box.
73:      */
74:     public static final int MARGIN = 10;
75: 
76:     /**
77:      * The distance between two rows in the object rectangle.
78:      */
79:     public static final int ROWDISTANCE = 2;
80: 
81:     /**
82:      * The defaultheight of the object rectangle. That's 3 times the rowheight +
83:      * 3 times a distance of 2 between the rows + the stereoheight.
84:      */
85:     public static final int DEFAULT_HEIGHT =
86:         (3 * ROWHEIGHT + 3 * ROWDISTANCE + STEREOHEIGHT);
87: 
88:     /**
89:     * The defaultwidth of the object rectangle
90:     */
91:     public static final int DEFAULT_WIDTH = 3 * DEFAULT_HEIGHT / 2;
92: 
93:     /**
94:      * The outer black rectangle of the object box (object fig without
95:      * lifeline).
96:      */
97:     private FigRect outerBox;
98: 
99:     /**
100:      * The filled box for the object box (object fig without lifeline).
101:      */
102:     private FigRect backgroundBox;
103: 
104:     /**
105:      * The lifeline (dashed line under the object box to which activations are
106:      * attached)
107:      */
108:     private FigLine lifeLine;
109: 
110:     /**
111:      * The owner of the lifeline.
112:      */
113:     private LifeLinePort lifeLinePort;
114: 
115:     /**
116:      * The list where the nodes to which links can be attached are stored
117:      */
118:     private List linkPositions = new ArrayList();
119: 
120:     /**
121:      * The list where the figrects are stored that are the activation
122:      * boxes. The list is only here for performance issues. When
123:      * removing a figrect, it should also be removed from this list,
124:      * not only from the figs list.
125:      */
126:     private List figActivations = new ArrayList();
127: 
128:     /**
129:      * The list with the figLinkPorts. The list is only here for
130:      * performance issues. When deleting a figLinkPort, it should also
131:      * be removed from this list, not only from the figs list.
132:      */
133:     private List figFigLinkPorts = new ArrayList();
134: 
135:     /**
136:      * The comma seperated list of base names of the classifierRole(s)
137:      * that this object represents.
138:      */
139:     private String baseNames = "";
140: 
141:     /**
142:      * The comma seperated list of names of the classifierRole(s) that
143:      * this object represents.
144:      */
145:     private String classifierRoleNames = "";
146: 
147:     /**
148:      * The name of the object (the owner of this fig).
149:      */
150:     private String objectName = "";
151: 
152:     /**
153:      * Default constructor. Constructs the object rectangle, the lifeline,
154:      * the name box and the stereotype box.
155:      */
156:     public FigClassifierRole() {
157:         super();
158:         backgroundBox =
159:             new FigRect(
160:                 0,
161:                 0,
162:                 DEFAULT_WIDTH,
163:                 DEFAULT_HEIGHT,
164:                 Color.white,
165:                 Color.white);
166:         backgroundBox.setFilled(true);
167:         outerBox = new FigRect(0, 0, DEFAULT_WIDTH, DEFAULT_HEIGHT);
168:         outerBox.setFilled(false);
169:         setStereotypeFig(new FigText(DEFAULT_WIDTH / 2,
170: 				     ROWHEIGHT + ROWDISTANCE,
171: 				     0,
172: 				     0,
173: 				     Color.black,
174: 				     "Dialog",
175: 				     12,
176: 				     false));
177:         getStereotypeFigText().setAllowsTab(false);
178:         getStereotypeFigText().setEditable(false);
179:         getStereotypeFig().setFilled(false);
180:         getStereotypeFig().setLineWidth(0);
181:         setNameFig(new FigText(DEFAULT_WIDTH / 2,
182: 			       2 * ROWDISTANCE + STEREOHEIGHT + ROWHEIGHT,
183: 			       0,
184: 			       0,
185: 			       Color.black,
186: 			       "Dialog",
187: 			       12,
188: 			       false));
189:         getNameFig().setEditable(false);
190:         getNameFig().setAllowsTab(false);
191:         getNameFig().setFilled(false);
192:         getNameFig().setLineWidth(0);
193:         lifeLine =
194:             new FigLine(
195:                 DEFAULT_WIDTH / 2,
196:                 DEFAULT_HEIGHT,
197:                 DEFAULT_WIDTH / 2,
198:                 1000,
199:                 Color.black);
200:         lifeLine.setDashed(true);
201:         linkPositions.add(new ObjectNode(this));
202:         for (int i = 0;
203:             i <= lifeLine.getHeight() / SequenceDiagramLayout.LINK_DISTANCE;
204:             i++) {
205:             linkPositions.add(new EmptyNode());
206:         }
207:         addFig(lifeLine);
208:         addFig(backgroundBox);
209:         addFig(getStereotypeFig());
210:         addFig(getNameFig());
211:         addFig(outerBox);
212:     }
213: 
214:     /**
215:      * @param node the owner
216:      */
217:     public FigClassifierRole(Object node) {
218:         this();
219:         setOwner(node);
220:     }
221: 
222:     /**
223:      * When the mouse button is released, this fig will be moved into position
224:      *
225:      * @see MouseListener#mouseReleased(MouseEvent)
226:      */
227:     public void mouseReleased(MouseEvent me) {
228:         super.mouseReleased(me);
229:         Layer lay = Globals.curEditor().getLayerManager().getActiveLayer();
230:         if (lay instanceof SequenceDiagramLayout) {
231:             ((SequenceDiagramLayout) lay).putInPosition(this);
232:         }
233:     }
234: 
235:     /**
236:      * Constructs the contents of the name text box and upates the name text box
237:      * accordingly. The contents of the name text box itself are NOT updated.
238:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateNameText()
239:      */
240:     protected void updateNameText() {
241:         String nameText =
242:             (objectName + "/" + classifierRoleNames + ":" + baseNames)
243:                 .trim();
244:         getNameFig().setText(nameText);
245:         center(getNameFig());
246:         damage();
247:     }
248: 
249:     /**
250:      * @see FigNodeModelElement#updateStereotypeText()
251:      */
252:     protected void updateStereotypeText() {
253:         super.updateStereotypeText();
254:         center(getStereotypeFigText());
255:     }
256: 
257:     private void center(FigText figText) {
258:         int newX = this.getX() + this.getHalfWidth() - figText.getHalfWidth();
259:         if (figText.getX() != newX) {
260:             figText.setX(newX);
261:             updateBounds();
262:         }
263:     }
264: 
265:     /**
266:      * Sets the bounds and coordinates of this Fig. The outerbox (the
267:      * black box around the upper box) and the background box (the
268:      * white box at the background) are scaled to the given size. The
269:      * name text box and the stereo text box are moved to a correct
270:      * position.
271:      *
272:      * @see Fig#setBounds(int, int, int, int)
273:      */
274:     public void setBounds(int x, int y, int w, int h) {
275:         Rectangle oldBounds = getBounds();
276:         if (getNameFig().getWidth() > w) {
277:             w = getNameFig().getWidth() + 2 * MARGIN;
278:         }
279:         if (getStereotypeFig().getWidth() > w) {
280:             w = getStereotypeFig().getWidth() + 2 * MARGIN;
281:         }
282:         getNameFig().setCenter(
283:             new Point(x + w / 2,
284: 		      getNameFig().getY() - oldBounds.y + y
285: 		      + getNameFig().getHalfHeight()));
286:         getStereotypeFig().setCenter(
287:             new Point(
288:                 x + w / 2,
289:                 (getStereotypeFig().getY() - oldBounds.y
290: 		 + y + getStereotypeFig().getHalfHeight())));
291:         reSize(outerBox, x, y, w, h);
292:         reSize(backgroundBox, x, y, w, h);
293:         lifeLine.setBounds(
294:             outerBox.getX() + outerBox.getHalfWidth(),
295:             outerBox.getY() + outerBox.getHeight(),
296:             0,
297:             h - outerBox.getHeight());
298:         int factor = h / oldBounds.height;
299:         for (int i = 0; i < figActivations.size(); i++) {
