388:     private void addActivations() {
389:         boolean startActivation = false;
390:         ActivationNode startActivationNode = null;
391:         ActivationNode endActivationNode = null;
392:         int x = lifeLine.getX() - WIDTH / 2;
393:         for (int i = 0; i < linkPositions.size(); i++) {
394:             Node node = (Node) linkPositions.get(i);
395:             if (node instanceof ActivationNode
396:                 && ((ActivationNode) node).isStart()) {
397:                 startActivationNode = (ActivationNode) node;
398:                 endActivationNode = null;
399:             }
400:             if (node instanceof ActivationNode
401:                 && ((ActivationNode) node).isEnd()) {
402: 
403:                 if (startActivationNode == null) {
404:                     throw new IllegalStateException(
405: 			    "End activation node without "
406: 			    + "start activation node.");
407:                 }
408: 
409:                 endActivationNode = (ActivationNode) node;
410:                 int startPos =
411:                     getYCoordinateForActivationBox(startActivationNode, true);
412:                 int endPos = 0;
413:                 if (!endActivationNode.isStart()) {
414:                     endPos =
415:                         getYCoordinateForActivationBox(
416:                             endActivationNode,
417:                             false);
418:                 } else {
419:                     endPos = getYCoordinate(endActivationNode);
420:                     if (!endActivationNode.isCutOffBottom()) {
421:                         endPos += SequenceDiagramLayout.LINK_DISTANCE / 2;
422:                     }
423:                 }
424:                 FigRect activation =
425:                     new FigRect(
426:                         x,
427:                         startPos,
428:                         WIDTH,
429:                         endPos - startPos,
430:                         outerBox.getLineColor(),
431:                         backgroundBox.getFillColor());
432:                 figActivations.add(activation);
433:                 addFig(activation);
434:             }
435:         }
436:     }
