632:     /**
633:      * Returns the port for a given coordinate pair. Normally
634:      * deepHitPort returns the owner of the fig in the FigGroup that
635:      * is present at the given coordinate pair (returning figs that
636:      * are added later first). In this case it returns a
637:      * LinkPort.<p>
638:      *
639:      * This method has a side effect of creating a
640:      * FigLinkPort if ???<p>
641:      *
642:      * @see org.tigris.gef.presentation.FigNode#deepHitPort(int, int)
643:      */
644:     public Object deepHitPort(int x, int y) {
645:         Object port = null;
646:         Rectangle rect = new Rectangle(getX(), y - 16, getWidth(), 32);
647:         Node foundNode = null;
648:         if (lifeLine.intersects(rect)) {
649:             for (int i = linkPositions.indexOf(getObjectNode());
650:                 i < linkPositions.size();
651:                 i++) {
652:                 Node node = (Node) linkPositions.get(i);
653:                 int position = getYCoordinate(node);
654:                 if (i < linkPositions.size() - 1) {
655:                     int nextPosition =
656:                         getYCoordinate((Node) linkPositions.get(i + 1));
657:                     if (nextPosition >= y && position < y) {
658:                         if ((y - position) <= (nextPosition - y)) {
659:                             foundNode = node;
660:                         } else {
661:                             foundNode = (Node) linkPositions.get(i + 1);
662:                         }
663:                         break;
664:                     }
665:                 } else {
666:                     foundNode =
667:                         (Node) linkPositions.get(linkPositions.size() - 1);
668:                     break;
669:                 }
670:             }
671:             int yCoordinate = 0;
672:             SequenceDiagramLayout layout = (SequenceDiagramLayout) getLayer();
673:             if (!layout.getFigLinks(getYCoordinate(foundNode)).isEmpty()) {
674:                 FigLinkPort figLinkPort =
675:                     new FigLinkPort(
676:                         lifeLine.getX() - WIDTH / 2,
677:                         getYCoordinate(foundNode)
678:                             + SequenceDiagramLayout.LINK_DISTANCE,
679:                         lifeLine.getX() + WIDTH / 2);
680:                 addFig(figLinkPort);
681:                 figFigLinkPorts.add(figLinkPort);
682:                 LinkNode linkNode = new LinkNode(getOwner(), figLinkPort);
683:                 layout.addNode(getIndexOf(foundNode) + 1, linkNode);
684:                 foundNode = linkNode;
685:             } else {
686:                 if (!(foundNode instanceof LinkPort)
687:                     && !(foundNode instanceof ObjectNode)) {
688:                     FigLinkPort figLinkPort =
689:                         new FigLinkPort(
690:                             lifeLine.getX() - WIDTH / 2,
691:                             getYCoordinate(foundNode),
692:                             lifeLine.getX() + WIDTH / 2);
693:                     addFig(figLinkPort);
694:                     figFigLinkPorts.add(figLinkPort);
695:                     LinkNode linkNode = new LinkNode(getOwner(), figLinkPort);
696:                     linkPositions.set(
697:                         linkPositions.indexOf(foundNode),
698:                         linkNode);
699:                     foundNode = linkNode;
700:                 }
701: 
702:             }
703:             return foundNode;
704:         } else if (outerBox.intersects(rect)) {
705:             ObjectNode objectNode = (ObjectNode) getObjectNode();
706:             if (objectNode.getFigLinkPort() != null
707:                 && getFigLink(objectNode.getFigLinkPort()) != null) {
708:                 return null; // cannot connect here
709:             }
710:             if (objectNode.getFigLinkPort() == null) {
711:                 FigLinkPort figLinkPort =
712:                     new FigLinkPort(
713:                         lifeLine.getX() - WIDTH / 2,
714:                         getYCoordinate(foundNode),
715:                         lifeLine.getX() + WIDTH / 2);
716:                 objectNode.setFigLinkPort(figLinkPort);
717:             }
718:             objectNode.setObject(getOwner());
719:             return objectNode;
720:         } else {
721:             return null;
722:         }
723:     }
