206: 	    _w = 0;
207:             Iterator it = figs.iterator();
208:             int size = figs.size();
209: 	    for (int i = 0; i < size; i++) {
210:                 Fig fig = (Fig) it.next();
211: 
212:                 if (i == 0) {
213:                     first = fig;
214:                 }
215:                 if (i == size - 1) {
216:                     last = fig;
217:                 }
218: 
219: 		if (fig.getWidth() > _w) {
220: 		    _w = fig.getWidth();
221: 		}
222: 	    }
223:             _h = last.getY() + last.getHeight() - first.getY();
