70: /**
71:  * <p>Class to display graphics for a UML Class in a diagram.</p>
72:  */
73: public class FigClass extends FigNodeModelElement 
74:         implements AttributesCompartmentContainer, 
75:         OperationsCompartmentContainer {
76: 
77: 
78:     ////////////////////////////////////////////////////////////////
79:     // constants
80: 
81:     ////////////////////////////////////////////////////////////////
82:     // instance variables
83: 
84:     //These are the positions of child figs inside this fig
85:     //They mst be added in the constructor in this order.
86:     private static final int BLINDER_POSN = 3;
87:     private static final int OPERATIONS_POSN = 4;
88:     private static final int ATTRIBUTES_POSN = 5;
89:     
90:     /**
91:      * <p>Manages residency of a class within a component on a deployment
92:      *   diagram. Not clear why it is public, or even why it is an instance
93:      *   variable (rather than local to the method).</p>
94:      *
95:      * not currently used. should be lazily instantiated in future.
96:      */
97: //    public Object resident =
98: //	UmlFactory.getFactory().getCore().createElementResidence();
99: 
100:     /**
101:      * <p>Text highlighted by mouse actions on the diagram.</p>
102:      */
103:     private CompartmentFigText highlightedFigText = null;
104: 
105:     /**
106:      * <p>Flag to indicate that we have just been created. This is to fix the
107:      *   problem with loading classes that have stereotypes already
108:      *   defined.</p>
109:      */
110:     private boolean newlyCreated = false;
111: 
112:     ////////////////////////////////////////////////////////////////
113:     // constructors
114: 
115:     /**
116:      * Main constructor for a {@link FigClass}.<p>
117:      *
118:      * Parent {@link FigNodeModelElement} will have created the main
119:      * box {@link #getBigPort()} and its name {@link #getNameFig()}
120:      * and stereotype (@link #getStereotypeFig()}. This constructor
121:      * creates a box for the attributes and operations.<p>
122:      *
123:      * The properties of all these graphic elements are adjusted
124:      * appropriately. The main boxes are all filled and have
125:      * outlines.<p>
126:      *
127:      * For reasons I don't understand the stereotype is created in a
128:      * box with lines. So we have to created a blanking rectangle to
129:      * overlay the bottom line, and avoid four compartments
130:      * showing.<p>
131:      *
132:      * There is some complex logic to allow for the possibility that
133:      * stereotypes may not be displayed (unlike operations and
134:      * attributes this is not a standard thing for UML). Some care is
135:      * needed to ensure that additional space is not added, each time
136:      * a stereotyped class is loaded.<p>
137:      *
138:      * There is a particular problem when loading diagrams with
139:      * stereotyped classes. Because we create a FigClass indicating
140:      * the stereotype is not displayed, we then add extra space for
141:      * such classes when they are first rendered. This ought to be
142:      * fixed by correctly saving the class dimensions, but that needs
143:      * more work. The solution here is to use a simple flag to
144:      * indicate the FigClass has just been created.<p>
145:      *
146:      * <em>Warning</em>. Much of the graphics positioning is hard
147:      * coded. The overall figure is placed at location (10,10). The
148:      * name compartment (in the parent {@link FigNodeModelElement} is
149:      * 21 pixels high. The stereotype compartment is created 15 pixels
150:      * high in the parent, but we change it to 19 pixels, 1 more than
151:      * ({@link #STEREOHEIGHT} here. The attribute and operations boxes
152:      * are created at 19 pixels, 2 more than {@link #ROWHEIGHT}.<p>
153:      *
154:      * CAUTION: This constructor (with no arguments) is the only one
155:      * that does enableSizeChecking(false), all others must set it
156:      * true.  This is because this constructor is the only one called
157:      * when loading a project. In this case, the parsed size must be
158:      * maintained.<p>
159:      */
160:     public FigClass() {
161: 
162:         // Set name box. Note the upper line will be blanked out if there is
163:         // eventually a stereotype above.
164:         getNameFig().setLineWidth(1);
165:         getNameFig().setFilled(true);
166: 
167:         // Attributes inside. First one is the attribute box itself.
168:         FigCompartment attributeFigCompartment =
169:             new FigAttributesCompartment(10, 30, 60, ROWHEIGHT + 2);
170: 
171:         // this rectangle marks the operation section; all operations
172:         // are inside it
173:         FigCompartment operVec = 
174:             new FigOperationsCompartment(10, 31 + ROWHEIGHT, 60, ROWHEIGHT + 2);
175: 
176:         // Set properties of the stereotype box. Make it 1 pixel higher than
177:         // before, so it overlaps the name box, and the blanking takes out both
178:         // lines. Initially not set to be displayed, but this will be changed
179:         // when we try to render it, if we find we have a stereotype.
180:         getStereotypeFigText().setExpandOnly(true);
181:         getStereotypeFig().setFilled(true);
182:         getStereotypeFig().setLineWidth(1);
183:         getStereotypeFigText().setEditable(false);
184:         getStereotypeFig().setHeight(STEREOHEIGHT + 1);
185:         // +1 to have 1 pixel overlap with getNameFig()
186:         getStereotypeFig().setVisible(false);
187: 
188:         // A thin rectangle to overlap the boundary line between stereotype
189:         // and name. This is just 2 pixels high, and we rely on the line
190:         // thickness, so the rectangle does not need to be filled. Whether to
191:         // display is linked to whether to display the stereotype.
192:         FigRect stereoLineBlinder =
193: 	    new FigRect(11, 10 + STEREOHEIGHT, 58, 2,
194: 			Color.white, Color.white);
195:         stereoLineBlinder.setLineWidth(1);
196:         stereoLineBlinder.setVisible(false);
197: 
198:         FigEmptyRect bigPort = new FigEmptyRect(10, 10, 0, 0);
199:         bigPort.setLineWidth(1);
200:         bigPort.setLineColor(Color.black);
201:         setBigPort(bigPort);
202:         
203:         // Mark this as newly created. This is to get round the problem with
204:         // creating figs for loaded classes that had stereotypes. They are
205:         // saved with their dimensions INCLUDING the stereotype, but since we
206:         // pretend the stereotype is not visible, we add height the first time
207:         // we render such a class. This is a complete fudge, and really we
208:         // ought to address how class objects with stereotypes are saved. But
209:         // that will be hard work.
210:         newlyCreated = true;
211: 
212:         // Put all the bits together, suppressing bounds calculations until
213:         // we're all done for efficiency.
214:         enableSizeChecking(false);
215:         setSuppressCalcBounds(true);
216:         addFig(getStereotypeFig());
217:         addFig(getNameFig());
218:         addFig(bigPort);
219:         addFig(stereoLineBlinder);
220:         addFig(operVec);
221:         addFig(attributeFigCompartment);
222: 
223:         setSuppressCalcBounds(false);
224:         // Set the bounds of the figure to the total of the above (hardcoded)
225:         setBounds(10, 10, 60, 22 + 2 * ROWHEIGHT);
226:     }
227: 
228:     /**
229:      * <p>Constructor for use if this figure is created for an existing class
230:      *   node in the metamodel.</p>
