435:     /**
436:      * <p>Gets the minimum size permitted for a class on the diagram.</p>
437:      *
438:      * <p>Parts of this are hardcoded, notably the fact that the name
439:      *   compartment has a minimum height of 21 pixels.</p>
440:      *
441:      * @return  the size of the minimum bounding box.
442:      */
443:     public Dimension getMinimumSize() {
444: 
445:         // Use "aSize" to build up the minimum size. Start with the size of the
446:         // name compartment and build up.
447: 
448:         Dimension aSize = getNameFig().getMinimumSize();
449:         if (aSize.height < 21) {
450:             aSize.height = 21;
451:         }
452: 
453:         // If we have a stereotype displayed, then allow some space for that
454:         // (width and height)
455: 
456:         if (getStereotypeFig().isVisible()) {
457:             aSize.width =
458: 		Math.max(aSize.width,
459: 			 getStereotypeFig().getMinimumSize().width);
460:             aSize.height += STEREOHEIGHT;
461:         }
462: 
463:         // Allow space for each of the attributes we have
464: 
465:         if (getAttributesFig().isVisible()) {
466: 
467:             // Loop through all the attributes, to find the widest (remember
468:             // the first fig is the box for the whole lot, so ignore it).
469: 
470:             Iterator it = getAttributesFig().getFigs(null).iterator();
471:             it.next(); // Ignore first element
472: 
473:             while (it.hasNext()) {
474:                 int elemWidth =
475: 		    ((FigText) it.next()).getMinimumSize().width + 2;
476:                 aSize.width = Math.max(aSize.width, elemWidth);
477:             }
478: 
479:             // Height allows one row for each attribute (remember to ignore the
480:             // first element.
481: 
482:             aSize.height +=
483: 		ROWHEIGHT * Math.max(1, 
484: 		        getAttributesFig().getFigs(null).size() - 1) + 1;
485:         }
486: 
487:         // Allow space for each of the operations we have
488: 
489:         if (isOperationsVisible()) {
490: 
491:             // Loop through all the operations, to find the widest (remember
492:             // the first fig is the box for the whole lot, so ignore it).
493: 
494:             Iterator it = getOperationsFig().getFigs(null).iterator();
495:             it.next(); // ignore
496: 
497:             while (it.hasNext()) {
498:                 int elemWidth =
499: 		    ((FigText) it.next()).getMinimumSize().width + 2;
500:                 aSize.width = Math.max(aSize.width, elemWidth);
501:             }
502: 
503:             aSize.height +=
504: 		ROWHEIGHT * Math.max(1, 
505: 		        getOperationsFig().getFigs(null).size() - 1) + 1;
506:         }
507: 
508:         // we want to maintain a minimum width for the class
509:         aSize.width = Math.max(60, aSize.width);
510: 
511:         // And now aSize has the answer
512: 
513:         return aSize;
514:     }
