1261:     protected void updateListeners(Object newOwner) {
1262:         Object oldOwner = getOwner();
1263:         if (oldOwner != null && oldOwner != newOwner) {
1264: 	    // remove the listeners if the owner is changed
1265:             Object cl = /*(MClass)*/ oldOwner;
1266:             Iterator it = ModelFacade.getFeatures(cl).iterator();
1267:             while (it.hasNext()) {
1268:                 Object feat = /*(MFeature)*/ it.next();
1269:                 if (ModelFacade.isAOperation(feat)) {
1270:                     Object oper = /*(MOperation)*/ feat;
1271:                     Iterator it2 = ModelFacade.getParameters(oper).iterator();
1272:                     while (it2.hasNext()) {
1273:                         Object param = /*(MParameter)*/ it2.next();
1274:                         UmlModelEventPump.getPump()
1275: 			    .removeModelEventListener(this, param);
1276:                     }
1277:                 }
1278:             }
1279:         }
1280:         if (newOwner != null) { // add the listeners to the newOwner
1281:             Object cl = /*(MClass)*/ newOwner;
1282:             Iterator it = ModelFacade.getFeatures(cl).iterator();
1283:             while (it.hasNext()) {
1284:                 Object feat = /*(MFeature)*/ it.next();
1285:                 if (ModelFacade.isAOperation(feat)) {
1286:                     Object oper = /*(MOperation)*/ feat;
1287:                     Iterator it2 = ModelFacade.getParameters(oper).iterator();
1288:                     while (it2.hasNext()) {
1289:                         Object param = /*(MParameter)*/ it2.next();
1290:                         // UmlModelEventPump.getPump()
1291:                         // .removeModelEventListener(this, param);
1292:                         UmlModelEventPump.getPump()
1293: 			    .addModelEventListener(this, param);
1294:                     }
1295:                 }
1296:             }
1297:         }
1298: 
1299:         super.updateListeners(newOwner);
