269:     /**
270:      * Build a collection of menu items relevant for a right-click
271:      * popup menu on a Class.
272:      *
273:      * @param     me     a mouse event
274:      * @return           a collection of menu items
275:      *
276:      * @see org.tigris.gef.ui.PopupGenerator#getPopUpActions(java.awt.event.MouseEvent)
277:      */
278:     public Vector getPopUpActions(MouseEvent me) {
279:         Vector popUpActions = super.getPopUpActions(me);
280: 
281:         // Add...
282:         ArgoJMenu addMenu = new ArgoJMenu("menu.popup.add");
283:         addMenu.add(new ActionAddAttribute());
284:         addMenu.add(new ActionAddOperation());
285:         addMenu.add(ActionAddNote.getSingleton());
286:         popUpActions.insertElementAt(addMenu,
287:             popUpActions.size() - POPUP_ADD_OFFSET);
288: 
289:         // Show ...
290:         ArgoJMenu showMenu = new ArgoJMenu("menu.popup.show");
291:         if (isAttributesVisible() && isOperationsVisible()) {
292:             showMenu.add(ActionCompartmentDisplay.hideAllCompartments());
293:         } else if (!isAttributesVisible() && !isOperationsVisible()) {
294:             showMenu.add(ActionCompartmentDisplay.showAllCompartments());
295:         }
296:         if (isAttributesVisible()) {
297:             showMenu.add(ActionCompartmentDisplay.hideAttrCompartment());
298:         } else {
299:             showMenu.add(ActionCompartmentDisplay.showAttrCompartment());
300:         }
301:         if (isOperationsVisible()) {
302:             showMenu.add(ActionCompartmentDisplay.hideOperCompartment());
303:         } else {
304:             showMenu.add(ActionCompartmentDisplay.showOperCompartment());
305:         }
306:         showMenu.add(ActionEdgesDisplay.getShowEdges());
307:         showMenu.add(ActionEdgesDisplay.getHideEdges());
308:         popUpActions.insertElementAt(showMenu,
309:             popUpActions.size() - POPUP_ADD_OFFSET);
310: 
311:         // Modifiers ...
312:         popUpActions.insertElementAt(
313:                 buildModifierPopUp(ABSTRACT | LEAF | ROOT | ACTIVE),
314:                 popUpActions.size() - POPUP_ADD_OFFSET);
315: 
316:         // Visibility ...
317:         popUpActions.insertElementAt(buildVisibilityPopUp(),
318:                 popUpActions.size() - POPUP_ADD_OFFSET);
319:            
320:         return popUpActions;
321:     }
