1093:             // TODO: in future version of GEF call getFigs returning array
1094:             Vector figs = new Vector(getAttributesFig().getFigs(null));
1095:             CompartmentFigText attr;
1096:             while (iter.hasNext()) {
1097:                 Object sf = /*(MStructuralFeature)*/ iter.next();
1098:                 // update the listeners
1099: 		// UmlModelEventPump.getPump().removeModelEventListener(this,
1100: 		// sf);
1101:                 UmlModelEventPump.getPump().addModelEventListener(this, sf);
1102:                 if (figs.size() <= acounter) {
1103:                     attr =
1104: 			new FigFeature(xpos + 1,
1105: 				       ypos + 1 + (acounter - 1) * ROWHEIGHT,
1106: 				       0,
1107: 				       ROWHEIGHT - 2,
1108:                     attributesPort);
1109:                     // bounds not relevant here
1110:                     attr.setFilled(false);
1111:                     attr.setLineWidth(0);
1112:                     attr.setFont(getLabelFont());
1113:                     attr.setTextColor(Color.black);
1114:                     attr.setJustification(FigText.JUSTIFY_LEFT);
1115:                     attr.setMultiLine(false);
1116:                     getAttributesFig().addFig(attr);
1117:                 } else {
1118:                     attr = (CompartmentFigText) figs.elementAt(acounter);
1119:                 }
1120:                 attr.setText(Notation.generate(this, sf));
1121:                 attr.setOwner(sf);
1122:                 // underline, if static
1123:                 attr.setUnderline(ModelFacade.CLASSIFIER_SCOPEKIND
1124: 				  .equals(ModelFacade.getOwnerScope(sf)));
1125:                 acounter++;
1126:             }
1127:             if (figs.size() > acounter) {
1128:                 //cleanup of unused attribute FigText's
1129:                 for (int i = figs.size() - 1; i >= acounter; i--) {
1130:                     getAttributesFig().removeFig((Fig) figs.elementAt(i));
1131:                 }
1132:             }
1133:         }
1134:         Rectangle rect = getBounds();
1135:         updateFigGroupSize(getAttributesFig(), xpos, ypos, 0, 0);
1136:         // ouch ugly but that's for a next refactoring
1137:         // TODO: make setBounds, calcBounds and updateBounds consistent
