1083:     protected void updateAttributes() {
1084:         Object cls = /*(MClassifier)*/ getOwner();
1085:         Fig attributesPort = ((FigAttributesCompartment) getFigAt(ATTRIBUTES_POSN))
1086:             .getBigPort();
1087:         int xpos = attributesPort.getX();
