182:         synchronized (parent.getTreeLock()) {
183:             Insets insets = parent.getInsets();
184:             int minimumHeight = insets.top + insets.bottom;
185: 
186:             ArrayList rowHeights = new ArrayList();
187: 
188:             int componentCount = parent.getComponentCount();
189:             for (int i = 0; i < componentCount; ++i) {
190:                 Component childComp = parent.getComponent(i);
191:                 if (childComp instanceof JLabel) {
192:                     JLabel jlabel = (JLabel) childComp;
193:                     childComp = jlabel.getLabelFor();
194:                     int childHeight = (int) childComp.getMinimumSize().getHeight();
195:                     if (childHeight < jlabel.getMinimumSize().getHeight()) {
196:                         childHeight = (int) jlabel.getMinimumSize().getHeight();
197:                     }
198:                     minimumHeight += childHeight + _vgap;
199:                 }
200:             }
201:             return new Dimension(0, minimumHeight);
202:         }
203:     }
