152:         String projectName = null;
153: 
154:         //--------------------------------------------
155:         // Parse command line args:
156:         // The assumption is that all options precede
157:         // the name of a project file to load.
158:         //--------------------------------------------
159: 
160:         String themeMemory = null;
161:         for (int i = 0; i < args.length; i++) {
162:             if (args[i].startsWith("-")) {
163: 		String theme =
164: 		    LookAndFeelMgr.getInstance().getThemeFromArg(args[i]);
165:                 if (theme != null) {
166: 		    themeMemory = theme;
167:                 } else if (
168:                     args[i].equalsIgnoreCase("-help")
169:                         || args[i].equalsIgnoreCase("-h")
