323:         st.mark("close splash");
324:         if (splash != null) {
325:             splash.setVisible(false);
326:             splash.dispose();
327:             splash = null;
328:         }
329: 
330:         performCommands(commands);
331:         commands = null;
332: 
333:         st.mark("start critics");
334:         Runnable startCritics = new StartCritics();
335:         Main.addPostLoadAction(startCritics);
336: 
337:         st.mark("start preloader");
338:         if (preload) {
339:             Runnable preloader = new PreloadClasses();
340:             Main.addPostLoadAction(preloader);
341:         }
342: 
343:         PostLoad pl = new PostLoad(postLoadActions);
344:         Thread postLoadThead = new Thread(pl);
