347:         LOG.info("");
348:         LOG.info("profile of load time ############");
349:         for (Enumeration i = st.result(); i.hasMoreElements();) {
350:             LOG.info(i.nextElement());
351:         }
352:         LOG.info("#################################");
353:         LOG.info("");
354: 
355:         st = null;
356:         pb.setCursor(Cursor.getPredefinedCursor(Cursor.DEFAULT_CURSOR));
357: 
358:         //ToolTipManager.sharedInstance().setInitialDelay(500);
