362:     /**
363:      * Calculates the {@link URL} for the given project name.
364:      * If the file does not exist or cannot be converted the default
365:      * {@link URL} is returned.
366:      *
367:      * @param projectName is the file name of the project
368:      * @param urlToOpen is the default {@link URL}
369:      * @return the new URL.
370:      */
371:     private static URL projectUrl(final String projectName, URL urlToOpen) {
372:         File projectFile = new File(projectName);
373:         if (!projectFile.exists()) {
374:             System.err.println("Project file '" + projectFile
375: 			       + "' does not exist.");
376:             /* this will cause an empty project to be created */
377:         } else {
378:             try {
379:                 urlToOpen = Util.fileToURL(projectFile);
380:             } catch (Exception e) {
381:                 LOG.error("Exception opening project in main()", e);
382:             }
383:         }
384: 
385:         return urlToOpen;
386:     }
