388:     /**
389:      * Prints the usage message.
390:      */
391:     private static void printUsage() {
392:         System.err.println("Usage: [options] [project-file]");
393:         System.err.println("Options include: ");
394:         System.err.println("  -help           display this information");
395:         LookAndFeelMgr.getInstance().printThemeArgs();
396:         System.err.println("  -nosplash       don't display logo at startup");
397:         System.err.println("  -noedem         don't report usage statistics");
398:         System.err.println("  -nopreload      don't preload common classes");
399:         System.err.println("  -norecentfile   don't reload last saved file");
400:         System.err.println("  -command <arg>  command to perform on startup");
401:         System.err.println("  -batch          don't start GUI");
402:         System.err.println("  -locale <arg>   set the locale (e.g. 'en_GB')");
403:         System.err.println("");
404:         System.err.println("You can also set java settings which influence "
405: 			   + "the behaviour of ArgoUML:");
406:         System.err.println("  -Dforce.nativelaf  [force ArgoUML to use "
407: 			   + "the native look and feel. [UNSUPPORTED]");
408:         System.err.println("\n\n");
409:     }
410: 
411:     /**
412:      * Checks tha JVM Version.<p>
413:      *
414:      * If it is a non supported JVM version we exit immediatly.
415:      */
416:     private static void checkJVMVersion() {
417:         // check if we are using a supported java version
418:         String javaVersion = System.getProperty("java.version", "");
419:         // exit if unsupported java version.
420:         if (javaVersion.startsWith("1.3")
421:             || javaVersion.startsWith("1.2")
422:             || javaVersion.startsWith("1.1")) {
423: 
424: 	    System.err.println("You are using Java " + javaVersion + ", "
425: 			       + "Please use Java 1.4 or later with ArgoUml");
426: 	    System.exit(0);
427:         }
428:     }
429: 
430:     /**
431:      * Check that we can get the InetAddress for localhost.
432:      * This can fail on Unix if /etc/hosts is not correctly set up.
433:      */
434:     private static void checkHostsFile() {
435:         try {
436:             InetAddress.getLocalHost();
437:         } catch (UnknownHostException e) {
438:             System.err.println("ERROR: unable to get localhost information.");
439:             e.printStackTrace(System.err);
440:             System.err.println("On Unix systems this usually indicates that"
441:                 + "your /etc/hosts file is incorrectly setup.");
442:             System.err.println("Stopping execution of ArgoUML.");
443:             System.exit(0);
