594:     /**
595:      * Do a part of the initialization that is very much GUI-stuff.
596:      *
597:      * @param doSplash true if we are updating the splash
598:      * @param theTheme is the theme to set.
599:      */
600:     private static SplashScreen initializeGUI(
601:                     boolean doSplash, String theTheme) {
602: 	// initialize the correct look and feel
603: 	LookAndFeelMgr.getInstance().initializeLookAndFeel();
604: 	if (theTheme != null) {
605: 	    LookAndFeelMgr.getInstance().setCurrentTheme(theTheme);
606: 	}
607: 
608:         SplashScreen splash = null;
609:         if (doSplash) splash = new SplashScreen();
610: 
611:         // make the projectbrowser
612: 	ProjectBrowser pb = ProjectBrowser.makeInstance(splash);
613: 
614: 	JOptionPane.setRootFrame(pb);
615: 
616: 	// Set the screen layout to what the user left it before, or
617: 	// to reasonable defaults.
618: 	Dimension scrSize = Toolkit.getDefaultToolkit().getScreenSize();
619: 	pb.setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));
620: 
621: 	int configFrameWidth =
622: 	    Configuration.getInteger(Argo.KEY_SCREEN_WIDTH,
623: 				     (int) (0.95 * scrSize.width));
624: 	int configFrameHeight =
625: 	    Configuration.getInteger(Argo.KEY_SCREEN_HEIGHT,
626: 				     (int) (0.95 * scrSize.height));
627:         int w = Math.min(configFrameWidth, scrSize.width);
628:         int h = Math.min(configFrameHeight, scrSize.height);
629: 	int x = Configuration.getInteger(Argo.KEY_SCREEN_LEFT_X, 0);
630: 	int y = Configuration.getInteger(Argo.KEY_SCREEN_TOP_Y, 0);
631: 	pb.setLocation(x, y);
632: 	pb.setSize(w, h);
633:         return splash;
634:     }
