282:             || (lafClass != null && lafClass.equals(currentLookAndFeel))) {
283:             return;
284:         }
285: 
286:         //setLookAndFeel(lafClass); Disabled until UI supports dynamic switching
287: 
288:         String lafValue = lafClass;
289:         if (lafValue == null) {
290:             lafValue = DEFAULT_KEY;
291:         }
292:         Configuration.setString(Argo.KEY_LOOK_AND_FEEL_CLASS, lafValue);
293:     }
294: 
295:     /**
296:      * Returns the string identifier for the current theme.
297:      * This is the class name of the MetalTheme class for the theme.
298:      * This method should never return null.
299:      *
300:      * @return	current theme class name
301:      **/
302:     public String getCurrentTheme() {
303: 	String value = Configuration.getString(Argo.KEY_THEME_CLASS, null);
304: 	if (DEFAULT_KEY.equals(value)) {
305: 	    value = null;
306: 	}
307: 	return value;
308:     }
309: 
310:     /**
311:      * Returns the display name of the current theme.
312:      *
313:      * @return	theme display name
314:      **/
315:     public String getCurrentThemeName() {
316:         String currentTheme = getCurrentTheme();
317: 
318:         if (currentTheme == null) {
319:             return DEFAULT_THEME.getName();
320:         } 
321:         String name = null;
322:         
323:         for (int i = 0; i < THEMES.length; ++i) {
324:             if (THEMES[i].getClass().getName().equals(currentTheme)) {
325:                 name = THEMES[i].getName();
326:             }
327:         }
328:         return name;
329:     }
