230:     /**
231:      * Returns the string identifier for the current look and feel.
232:      * This is the class name of the LookAndFeel class for the look and feel.
233:      * Returns null if no look and feel has been specified, in which case
234:      * Swing's default look and feel should be used.
235:      *
236:      * @return	current look and feel class name
237:      **/
238:     public String getCurrentLookAndFeelClassName() {
239:         String value =
240: 	    Configuration.getString(Argo.KEY_LOOK_AND_FEEL_CLASS, null);
241:         if (DEFAULT_KEY.equals(value)) {
242:             value = null;
243:         }
244:         return value;
245:     }
246: 
247:     /**
248:      * Returns the display name of the current look and feel.
249:      *
250:      * @return	look and feel display name
251:      **/
252:     public String getCurrentLookAndFeelName() {
253:         String currentLookAndFeel = getCurrentLookAndFeel();
254: 
255:         if (currentLookAndFeel == null) {
256:             return DEFAULT_KEY;
257:         } 
258:         String name = null;
259:         
260:         UIManager.LookAndFeelInfo[] lafs =
261:             UIManager.getInstalledLookAndFeels();
262:         for (int i = 0; i < lafs.length; ++i) {
263:             if (lafs[i].getClassName().equals(currentLookAndFeel)) {
264:                 name = lafs[i].getName();
265:             }
266:         }
267:         
268:         return name;
269:     }
270: 
271:     /**
272:      * Sets the current look and feel, storing the new value in
273:      * Configuration.  If argument is null, indicates that Swing's default
274:      * look and feel should be used.
275:      *
276:      * @param	lafClass	class name of desired look and feel
277:      **/
278:     public void setCurrentLookAndFeelClassName(String lafClass) {
279:         String currentLookAndFeel = getCurrentLookAndFeel();
280: 
281:         if ((lafClass == null && currentLookAndFeel == null)
282:             || (lafClass != null && lafClass.equals(currentLookAndFeel))) {
283:             return;
284:         }
285: 
286:         //setLookAndFeel(lafClass); Disabled until UI supports dynamic switching
287: 
288:         String lafValue = lafClass;
289:         if (lafValue == null) {
290:             lafValue = DEFAULT_KEY;
291:         }
292:         Configuration.setString(Argo.KEY_LOOK_AND_FEEL_CLASS, lafValue);
293:     }
294: 
295:     /**
296:      * Returns the string identifier for the current theme.
297:      * This is the class name of the MetalTheme class for the theme.
298:      * This method should never return null.
299:      *
300:      * @return	current theme class name
301:      **/
302:     public String getCurrentTheme() {
303: 	String value = Configuration.getString(Argo.KEY_THEME_CLASS, null);
304: 	if (DEFAULT_KEY.equals(value)) {
305: 	    value = null;
306: 	}
307: 	return value;
308:     }
309: 
310:     /**
311:      * Returns the display name of the current theme.
312:      *
313:      * @return	theme display name
314:      **/
315:     public String getCurrentThemeName() {
316:         String currentTheme = getCurrentTheme();
317: 
318:         if (currentTheme == null) {
319:             return DEFAULT_THEME.getName();
320:         } 
321:         String name = null;
322:         
323:         for (int i = 0; i < THEMES.length; ++i) {
324:             if (THEMES[i].getClass().getName().equals(currentTheme)) {
325:                 name = THEMES[i].getName();
326:             }
327:         }
328:         return name;
329:     }
330: 
331:     /**
332:      * Sets the current theme, storing the new value in
333:      * Configuration. Argument should not be null, and argument class
334:      * should be an instance of MetalTheme.
335:      *
336:      * @param	themeClass	class name of desired theme
337:      **/
338:     public void setCurrentTheme(String themeClass) {
339:         MetalTheme theme = getMetalTheme(themeClass);
340: 
341:         if (theme.getClass().getName().equals(getCurrentTheme())) {
342:             return;
343:         }
344: 
345:         //setTheme(theme); Disabled until UI supports dynamic switching
346: 
347:         String themeValue = themeClass;
348:         if (themeValue == null) {
349:             themeValue = DEFAULT_KEY;
350:         }
351:         Configuration.setString(Argo.KEY_THEME_CLASS, themeValue);
352:     }
353: 
354:     /**
355:      * @return the standard textfield font
356:      */
357:     public Font getStandardFont() {
358:         Font font = UIManager.getDefaults().getFont("TextField.font");
359:         if (font == null) {
360:             font = (new javax.swing.JTextField()).getFont();
361:         }
362:         return font;
363:     }
364: 
365:     /**
366:      * @return the small font
367:      */
368:     public Font getSmallFont() {
369:         Font font = getStandardFont();
370:         if (font.getSize2D() >= 12f) {
371:             return font.deriveFont(font.getSize2D() - 2f);
372:         }
373:         return font;
374:     }
375: 
376:     /**
377:      * Sets the look and feel in the GUI by calling UIManager.setLookAndFeel().
378:      *
379:      * @param	lafClass	class name of look and feel
380:      **/
381:     private void setLookAndFeel(String lafClass) {
382:         try {
383:             if (lafClass == null && defaultLafClass != null) {
384:                 // Set to the default LAF
385:                 UIManager.setLookAndFeel(defaultLafClass);
386:             } else {
387:                 // Set a custom LAF
388:                 UIManager.setLookAndFeel(lafClass);
389:             }
390:         } catch (UnsupportedLookAndFeelException e) {
391:             LOG.error(e);
392:         } catch (ClassNotFoundException e) {
393:             LOG.error(e);
394:         } catch (InstantiationException e) {
395:             LOG.error(e);
396:         } catch (IllegalAccessException e) {
397:             LOG.error(e);
398:         }
399:     }
400: 
401:     /**
402:      * Sets the metal theme in the GUI by calling
403:      * MetalLookAndFeel.setCurrentTheme().
404:      *
405:      * @param	theme	new MetalTheme to set
406:      **/
407:     private void setTheme(MetalTheme theme) {
408:         String currentLookAndFeel = getCurrentLookAndFeel();
409: 
410:         // If LAF is Metal (either set explicitly, or as the default)
411:         if ((currentLookAndFeel != null && currentLookAndFeel.equals(METAL_LAF_CLASS_NAME))
412: 	    || (currentLookAndFeel == null
413: 	        && defaultLafClass.equals(METAL_LAF_CLASS_NAME))) {
414:             try {
415:                 MetalLookAndFeel.setCurrentTheme(theme);
416:                 UIManager.setLookAndFeel(METAL_LAF_CLASS_NAME);
417:             } catch (UnsupportedLookAndFeelException e) {
418:                 LOG.error(e);
419:             } catch (ClassNotFoundException e) {
420:                 LOG.error(e);
421:             } catch (InstantiationException e) {
422:                 LOG.error(e);
423:             } catch (IllegalAccessException e) {
424:                 LOG.error(e);
425:             }
426:         }
427:     }
428: 
429:     /**
430:      * Returns the MetalTheme for the specified class name.
431:      * Returns the default theme if a corresponding MetalTheme class
432:      * can not be found.
433:      *
434:      * @param	themeClass	MetalTheme class name
435:      * @return				MetalTheme object for class name
436:      **/
437:     private MetalTheme getMetalTheme(String themeClass) {
438:         MetalTheme theme = null;
439: 
440:         for (int i = 0; i < THEMES.length; ++i) {
441:             if (THEMES[i].getClass().getName().equals(themeClass)) {
442:                 theme = THEMES[i];
443:             }
444:         }
445: 
446:         if (theme == null) {
447:             theme = DEFAULT_THEME;
448:         }
449: 
450:         return theme;
451:     }
452: }
