258:                     addedTargets.removeAll(currentSelection);
259:                     Iterator it = addedTargets.iterator();
260:                     while (it.hasNext()) {
261:                         TargetManager.getInstance().addTarget(it.next());
262:                     }
263:                 } else {
264:                     if (currentSelection.size() > sels.size()) {
265:                         // there are targets removed
266:                         List removedTargets = new ArrayList(currentSelection);
267:                         removedTargets.removeAll(sels);
268:                         Iterator it = removedTargets.iterator();
269:                         while (it.hasNext()) {
270:                             TargetManager.getInstance().removeTarget(it.next());
271:                         }
272:                     } else {                        
273:                         TargetManager.getInstance().setTargets(sels);
274:                     }
275:                 }
276:             }
