239:     public void selectionChanged(GraphSelectionEvent gse) {
240:         if (!updatingSelection) {
241:             updatingSelection = true;
242:             Vector sels = gse.getSelections();
243:             ActionCut.getInstance().setEnabled(sels != null && !sels.isEmpty());
244:             ActionCopy.getInstance()
245:                     .setEnabled(sels != null && !sels.isEmpty());
246:             /*
247:              * ActionPaste.getInstance().setEnabled( Globals.clipBoard
248:              * != null && !Globals.clipBoard.isEmpty());
249:              */
250:             Collection currentSelection = TargetManager.getInstance()
251:                     .getTargets();
252:             if (currentSelection.size() == 0)
253:                 TargetManager.getInstance().setTargets(sels);
254:             else {
255:                 if (currentSelection.size() < sels.size()) {
256:                     // there are targets added
257:                     List addedTargets = new ArrayList(sels);
258:                     addedTargets.removeAll(currentSelection);
259:                     Iterator it = addedTargets.iterator();
260:                     while (it.hasNext()) {
261:                         TargetManager.getInstance().addTarget(it.next());
262:                     }
263:                 } else {
264:                     if (currentSelection.size() > sels.size()) {
265:                         // there are targets removed
266:                         List removedTargets = new ArrayList(currentSelection);
267:                         removedTargets.removeAll(sels);
268:                         Iterator it = removedTargets.iterator();
269:                         while (it.hasNext()) {
270:                             TargetManager.getInstance().removeTarget(it.next());
271:                         }
272:                     } else {                        
273:                         TargetManager.getInstance().setTargets(sels);
274:                     }
275:                 }
276:             }
277:             updatingSelection = false;
278:         }
