459:     public void mouseEntered(MouseEvent me) {
460: 	if (getActiveTextEditor() != null) {
461:             getActiveTextEditor().requestFocus();         
462:         }
463: 	translateMouseEvent(me);
464: 	Globals.curEditor(this);
465: 	pushMode((FigModifyingMode) Globals.mode());
466: 	setUnderMouse(me);
467: 	_modeManager.mouseEntered(me);
468:     }
469:         
470:     /** Invoked when the mouse button has been moved (with no buttons
471:      * no down). */
472:     public void mouseMoved(MouseEvent me) {
473: 	//- RedrawManager.lock();
474: 	translateMouseEvent(me);
475: 	Globals.curEditor(this);
476: 	setUnderMouse(me);
477:         Fig currentFig = getCurrentFig();
478: 	if (currentFig != null && Globals.getShowFigTips()) {
479: 	    String tip = currentFig.getTipString(me);
480: 	    if (tip != null && (getJComponent() != null)) {
481: 	        JComponent c = getJComponent();
482: 	        if (c.getToolTipText() == null 
483: 		    || !(c.getToolTipText().equals(tip))) {
484: 	            c.setToolTipText(tip);
485: 	        }
486:             }
487: 	} else if (getJComponent() != null
488: 		   && getJComponent().getToolTipText() != null) {
489:             getJComponent().setToolTipText(null); //was ""
490: 	}
491: 
492: 	_selectionManager.mouseMoved(me);
