45: /**
46:  *  Provides settings for altering the appearance of the Argo application.
47:  *
48:  *  @author Linus Tolke
49:  *  @author Jeremy Jones
50:  *  @since  0.9.7
51:  */
52: public class SettingsTabAppearance
53:     extends SettingsTabHelper
54:     implements SettingsTabPanel
55: {
56: 
57:     private JComboBox	lookAndFeel;
58:     private JComboBox	metalTheme;
59:     private JLabel      metalLabel;
60:     private JCheckBox   smoothEdges;
61:     
62:     /**
63:      * The constructor.
64:      * 
65:      */
66:     public SettingsTabAppearance() {
67:         super();
68: 
69:         setLayout(new BorderLayout());
70: 
71:         int labelGap = 10;
72:         int componentGap = 10;
73:         JPanel top = new JPanel(new LabelledLayout(labelGap, componentGap));
74: 
75:         JLabel label = createLabel("label.look-and-feel");
76:         lookAndFeel =
77: 	    new JComboBox(LookAndFeelMgr.getInstance()
78: 			  .getAvailableLookAndFeelNames());
79:         lookAndFeel.addActionListener(new ActionListener() {
80:             public void actionPerformed(ActionEvent e)
81:             {
82:                 setMetalThemeState();
83:             }
84:         });
85:         label.setLabelFor(lookAndFeel);
86:         top.add(label);
87:         top.add(lookAndFeel);
88: 
89:         metalLabel = createLabel("label.metal-theme");
90: 
91:         metalTheme = new JComboBox(LookAndFeelMgr.getInstance()
92:                 .getAvailableThemeNames());
93:         metalLabel.setLabelFor(metalTheme);
94:         top.add(metalLabel);
95:         top.add(metalTheme);
96:         
97:         smoothEdges = createCheckBox("label.smooth-edges");
98:         JLabel emptyLabel = new JLabel();
99:         emptyLabel.setLabelFor(smoothEdges);
100:         
101:         top.add(emptyLabel);
102:         top.add(smoothEdges);
103:         
104:         top.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
105:         add(top, BorderLayout.CENTER);
106: 
107:         JLabel restart = createLabel("label.restart-application");
108:         restart.setHorizontalAlignment(SwingConstants.CENTER);
109:         restart.setVerticalAlignment(SwingConstants.CENTER);
110:         restart.setBorder(BorderFactory.createEmptyBorder(10, 2, 10, 2));
111:         add(restart, BorderLayout.SOUTH);
112: 
113:         setMetalThemeState();
114:     }
115:     
116:     /**
117:      * Enables or disables the metal theme controls depending on whether
118:      * or not themes are supported by the selected look and feel.
119:     **/
120:     private void setMetalThemeState()
121:     {
122:         String lafName = (String) lookAndFeel.getSelectedItem();
123:         boolean enabled =
124: 	    LookAndFeelMgr.getInstance().isThemeCompatibleLookAndFeel(
125: 		LookAndFeelMgr.getInstance().getLookAndFeelFromName(lafName));
126: 
127:         metalLabel.setEnabled(enabled);
128:         metalTheme.setEnabled(enabled);
129:     }
130: 
131:     /**
132:      * @see org.argouml.application.api.SettingsTabPanel#handleSettingsTabRefresh()
133:      */
134:     public void handleSettingsTabRefresh() {
135:         String laf = LookAndFeelMgr.getInstance().getCurrentLookAndFeelName();
136:     	String theme = LookAndFeelMgr.getInstance().getCurrentThemeName();
137: 
138:         lookAndFeel.setSelectedItem(laf);
139:         metalTheme.setSelectedItem(theme);		
140:         
141:         smoothEdges.setSelected(Configuration.getBoolean(
142:             Argo.KEY_SMOOTH_EDGES, false));
143:     }
144: 
145:     /**
146:      * @see org.argouml.application.api.SettingsTabPanel#handleSettingsTabSave()
147:      */
148:     public void handleSettingsTabSave() {
149:         LookAndFeelMgr.getInstance().setCurrentLookAndFeel(
150:             LookAndFeelMgr.getInstance().getLookAndFeelFromName(
151:                 (String) lookAndFeel.getSelectedItem()));
152:     
153:         LookAndFeelMgr.getInstance().setCurrentTheme(
154:             LookAndFeelMgr.getInstance().getThemeFromName(
155:                 (String) metalTheme.getSelectedItem()));
156:     
157:         Configuration.setBoolean(Argo.KEY_SMOOTH_EDGES, 
158:             smoothEdges.isSelected());
159:     }
160: 
161:     /**
162:      * @see org.argouml.application.api.SettingsTabPanel#handleSettingsTabCancel()
163:      */
164:     public void handleSettingsTabCancel() { }
165:     
