426:     /**
427:      * Adds the UMLDiagram and all the figs on it as listener to
428:      * UmlModelEventPump.  Together with removeAsModelListener this is
429:      * a performance improvement.
430:      *
431:      */
432:     public void setAsTarget() {
433:         Enumeration elems = elements();
434:         while (elems.hasMoreElements()) {
435:             Fig fig = (Fig) elems.nextElement();
436:             if (org.argouml.model.ModelFacade.isAElementListener(fig)) {
437:                 Object owner = fig.getOwner();
438:                 // pump.addModelEventListener((MElementListener)fig, owner);
439:                 // this will make sure all the correct event listeners are set. 
440:                 fig.setOwner(null);
441:                 fig.setOwner(owner);
442:             }
443:         }
444:     }
