463:       if (p != null && p.getPathname() != null && p.getPathname().length()>0) {
464: 	chooser  = new JFileChooser(p.getPathname());
465:       }
466:       else chooser = new JFileChooser();
467: 
468:       chooser.setDialogTitle("Save " + p.getName());
469:       FileFilter filter = FileFilters.XMIFilter;
470:       chooser.addChoosableFileFilter(filter);
471:       chooser.setFileFilter(filter);
472:       Hashtable stats = p.getStats();
473: 
474:       int retval = chooser.showSaveDialog(pb);
475:       if(retval == 0) {
476: 	File theFile = chooser.getSelectedFile();
477: 	if (theFile != null) {
478: 	  String pathname = chooser.getSelectedFile().getAbsolutePath();
479: 	  pb.showStatus("Writing " + pathname + "...");
480: 	  p.setPathname(chooser.getSelectedFile().getParent());
481: 	  String name = chooser.getSelectedFile().getName();
482: 	  if (!name.endsWith(".xmi")) name += ".xmi";
483: 	  if (!pathname.endsWith(".xmi")) pathname += ".xmi";
484: 	  p.setName(name);
485: 	  FileWriter fw = new FileWriter(pathname);
486: 	  p.preSave();
487: 	  expander.expand(fw, p, "", "");
488: 	  p.postSave();
489: 	  fw.close();
490: 	  pb.showStatus("Wrote " + pathname);
491: 	  pb.updateTitle();
492: 	  return true;
493: 	}
494:       }
495:     }
