1229: class ActionMessage extends UMLChangeAction {
1230:   public ActionMessage() { super("Message"); }
1231: 
1232:   public void actionPerformed(ActionEvent ae) {
1233:     ProjectBrowser pb = ProjectBrowser.TheInstance;
1234:     Object target = pb.getDetailsTarget();
1235:     Object d = pb.getTarget();
1236:     if (!(d instanceof UMLCollaborationDiagram)) return;
1237:     if (!(target instanceof AssociationRole)) return;
1238:     AssociationRole ar = (AssociationRole) target;
1239:     try {
1240:       Editor _curEditor = Globals.curEditor();
1241:       GraphModel gm = _curEditor.getGraphModel();
1242:       GraphNodeRenderer renderer = _curEditor.getGraphNodeRenderer();
1243:       Layer lay = _curEditor.getLayerManager().getActiveLayer();
1244:       SelectionManager _sm = _curEditor.getSelectionManager();
1245:       Vector figs = _sm.selections();
1246:       Selection _cf = (Selection) figs.firstElement();
1247:       FigEdge _curFig = (FigEdge) _cf.getContent();
1248:       Point _center = _curFig.center();
1249: 
1250:       Message msg = new Message();
1251:       Vector ascEnds = ar.getAssociationEndRole();
1252: 
1253:       AssociationEndRole aer1 = (AssociationEndRole) ascEnds.firstElement();
1254:       AssociationEndRole aer2 = (AssociationEndRole) ascEnds.lastElement();
1255:       ClassifierRole crSrc = (ClassifierRole) aer1.getType();
1256:       ClassifierRole crDst = (ClassifierRole) aer2.getType();
1257:       msg.setSender(crSrc);
1258:       msg.setReceiver(crDst);
1259:       UninterpretedAction ua = new UninterpretedAction();
1260:       msg.setAction(ua);
1261:       ar.addMessage(msg);
1262: 
1263:       FigNode _pers = renderer.getFigNodeFor(gm, lay, msg);
1264:       Vector messages = ar.getMessages();
1265:       int size = messages.size();
1266:       int offsetY = _pers.getHeight()/2;
1267:       _pers.setLocation(_center.x, _center.y - (offsetY * size));
1268:       _curFig.addPathItem(_pers, new PathConvPercent(_curFig, 50, 10));
1269:       lay.add(_pers);
1270:       super.actionPerformed(ae);
1271:       //System.out.println("sender = " + msg.getSender().getName());
1272:       //System.out.println("receiver = " + msg.getReceiver().getName());
1273:     }
1274:     catch (PropertyVetoException pve) {
1275:       System.out.println("PropertyVetoException in ActionMessage");
1276:     }
1277:   }
