1358:   public void actionPerformed(ActionEvent ae) {
1359:     ProjectBrowser pb = ProjectBrowser.TheInstance;
1360:     Object target = pb.getTarget();
1361:     if (!(target instanceof UMLClassDiagram)) return;
1362:     UMLClassDiagram d = (UMLClassDiagram) target;
1363:     Vector classes = new Vector();
1364:     Vector nodes = d.getGraphModel().getNodes();
1365:     java.util.Enumeration enum = nodes.elements();
1366:     while (enum.hasMoreElements()) {
1367:       Object owner = enum.nextElement();
1368:       if (!(owner instanceof MMClass) && !(owner instanceof Interface))
1369: 	continue;
1370:       Classifier cls = (Classifier) owner;
1371:       String name = cls.getName().getBody();
1372:       if (name == null || name.length() == 0) continue;
1373:       classes.addElement(cls);
1374:     }
1375:     ClassGenerationDialog cgd = new ClassGenerationDialog(classes);
1376:     cgd.show();
1377:   }
1378: 
1379:   public boolean shouldBeEnabled() {
1380:     ProjectBrowser pb = ProjectBrowser.TheInstance;
1381:     Object target = pb.getTarget();
1382:     return super.shouldBeEnabled() && target instanceof UMLClassDiagram;
1383:   }
