1337:     Editor ce = uci.gef.Globals.curEditor();
1338:     Vector sels = ce.getSelectionManager().getFigs();
1339:     java.util.Enumeration enum = sels.elements();
1340:     boolean foundOne = false;
1341:     while (enum.hasMoreElements()) {
1342:       Fig f = (Fig) enum.nextElement();
1343:       Object owner = f.getOwner();
1344:       if (!(owner instanceof MMClass) && !(owner instanceof Interface))
1345: 	continue;
1346:       Classifier cls = (Classifier) owner;
