580:   public void jumpToDiagramShowing(Set dms) {
581:     if (dms.size() == 0) return;
582:     Object first = dms.elementAt(0);
583:     if (first instanceof Diagram && dms.size() > 1) {
584:       setTarget(first);
585:       select(dms.elementAt(1));
586:       return;
587:     }
588:     if (first instanceof Diagram && dms.size() == 1) {
589:       setTarget(first);
590:       select(null);
591:       return;
592:     }
593:     Vector diagrams = getProject().getDiagrams();
594:     Object target = _multiPane.getTarget();
595:     if ((target instanceof Diagram) &&
596: 	((Diagram)target).countContained(dms) == dms.size()) {
597:       select(first);
598:       return;
599:     }
600: 
601:     Diagram bestDiagram = null;
602:     int bestNumContained = 0;
603:     for (int i = 0; i < diagrams.size(); i++) {
604:       Diagram d = (Diagram) diagrams.elementAt(i);
605:       int nc = d.countContained(dms);
606:       if (nc > bestNumContained) {
607: 	bestNumContained = nc;
608: 	bestDiagram = d;
609:       }
610:       if (nc == dms.size()) break;
611:     }
612:     if (bestDiagram != null) {
613:       setTarget(bestDiagram);
614:       select(first);
615:     }
616:   }
