307:     private URL upgrade(URL file) throws OpenException {
308:         try {
309:             int versionFromFile = Integer.parseInt(getVersion(file));
310: 
311:             LOG.info("Loading uml file of version " + versionFromFile);
312:             while (versionFromFile < PERSISTENCE_VERSION) {
313:                 ++versionFromFile;
314:                 LOG.info("Upgrading to version " + versionFromFile);
315:                 file = transform(file, versionFromFile);
316:             }
317:             return file;
318:         } catch (IOException e) {
319:             throw new OpenException(e);
320:         }
321:     }
