783:   public void actionPerformed(ActionEvent e) {
784:     ProjectBrowser pb = ProjectBrowser.TheInstance;
785:     Editor ce = uci.gef.Globals.curEditor();
786:     Vector sels = ce.getSelectionManager().getFigs();
787:     java.util.Enumeration enum = sels.elements();
788:     while (enum.hasMoreElements()) {
789:       Fig f = (Fig) enum.nextElement();
790:       Object owner = f.getOwner();
791:       if (!(owner instanceof MMClass) && !(owner instanceof Interface)) continue;
792:       Classifier cls = (Classifier) owner;
793:       String name = cls.getName().getBody();
794:       if (name == null || name.length() == 0) return;
795:       String path = ".";
796:       pb.showStatus("Generating source file for " + name + "...");
797:       GeneratorJava.GenerateFile(cls, path);
798:       pb.showStatus("Generating source file for " + name + "... done.");
799:       //pb.showStatus(" ");
800:     }
801:   }
