193:      * @author psager@tigris.org Jan. 24, 2oo2
194:      */
195:     public void setup(Object namespace,
196: 		      Object /*MStateMachine*/ machine) {
197:         setNamespace(namespace);
198: 
199:         // add the diagram as a listener to the statemachine so
200:         // that when the statemachine is removed() the diagram is deleted also.
201:         // Remark MVW: It also works without the next line.... So why?
202:         // UmlModelEventPump.getPump().addModelEventListener(this, sm);
203: 
204:         theStateMachine = machine;
205: 
206:         StateDiagramGraphModel gm = new StateDiagramGraphModel();
207:         gm.setHomeModel(namespace);
208:         if (machine != null) {
209:             gm.setMachine(machine);
210:         }
211:         StateDiagramRenderer rend = new StateDiagramRenderer(); // singleton
212: 
213:         LayerPerspective lay = new LayerPerspectiveMutable(
214:                 Model.getFacade().getName(namespace), gm);
215:         lay.setGraphNodeRenderer(rend);
216:         lay.setGraphEdgeRenderer(rend);
217:         setLayer(lay);
218: 
219:     }
