27:  */
28: package org.argouml.swingext;
29: 
30: import java.awt.*;
31: 
32: /**
33:  * Same as the standard java class GridLayout but allows more
34:  * flexability for sizing of columns and rows.
35:  *
36:  * @author Bob Tarling
37:  */
38: public class GridLayout2 implements LayoutManager, java.io.Serializable {
39: 
40:      /**
41:        * Do not resize the child components.
42:        */
43:     public static final int NONE = 0;
44: 
45:      /**
46:        * Resize all child components to fit their cell both
47:        * horizontally and vertically.
48:        */
49:     public static final int BOTH = 1;
50: 
51:      /**
52:        * Resize all child components to fit their cell horizontally
53:        * but not vertically.
54:        */
55:     public static final int HORIZONTAL = 2;
56: 
57:      /**
58:        * Resize all child components to fit their cell vertically but
59:        * not horizontally.
60:        */
61:     public static final int VERTICAL = 3;
62: 
63:      /**
64:       * Put the component in the center of its display area.
65:       */
66:     public static final int CENTER = 10;
67: 
68:      /**
69:        * Put the component at the top of its display area,
70:        * centered horizontally.
71:        */
72:     public static final int NORTH = 11;
73: 
74:       /**
75:        * Put the component at the top-right corner of its display area.
76:        */
77:     public static final int NORTHEAST = 12;
78: 
79:       /**
80:        * Put the component on the right side of its display area,
81:        * centered vertically.
82:        */
83:     public static final int EAST = 13;
84: 
85:       /**
86:        * Put the component at the bottom-right corner of its display area.
87:        */
88:     public static final int SOUTHEAST = 14;
89: 
90:       /**
91:        * Put the component at the bottom of its display area, centered
92:        * horizontally.
93:        */
94:     public static final int SOUTH = 15;
95: 
96:      /**
97:        * Put the component at the bottom-left corner of its display area.
98:        */
99:     public static final int SOUTHWEST = 16;
100: 
101:       /**
102:        * Put the component on the left side of its display area,
103:        * centered vertically.
104:        */
105:     public static final int WEST = 17;
106: 
107:      /**
108:        * Put each component in the top-left corner of its display area.
109:        */
110:     public static final int NORTHWEST = 18;
111: 
112:     /**
113:      * This is the horizontal gap (in pixels) which specifies the space
114:      * between columns.  They can be changed at any time.
115:      * This should be a non negative integer.
116:      *
117:      * @serial
118:      * @see #getHgap()
119:      * @see #setHgap(int)
120:      */
121:     private int h;
122:     /**
123:      * This is the vertical gap (in pixels) which specifies the space
124:      * between rows.  They can be changed at any time.
125:      * This should be a non negative integer.
126:      *
127:      * @serial
128:      * @see #getVgap()
129:      * @see #setVgap(int)
130:      */
131:     private int vgap;
132:     /**
133:      * This is the number of rows specified for the grid.  The number
134:      * of rows can be changed at any time.
135:      * This should be a non negative integer, where '0' means
136:      * 'any number' meaning that the number of Rows in that
137:      * dimension depends on the other dimension.
138:      *
139:      * @serial
140:      * @see #getRows()
141:      * @see #setRows(int)
142:      */
143:     private int rows;
144:     /**
145:      * This is the number of columns specified for the grid.  The number
146:      * of columns can be changed at any time.
147:      * This should be a non negative integer, where '0' means
148:      * 'any number' meaning that the number of Columns in that
149:      * dimension depends on the other dimension.
150:      *
151:      * @serial
152:      * @see #getColumns()
153:      * @see #setCols(int)
154:      */
155:     private int cols;
156: 
157:     /**
158:      * Size all cells as the largest prefered width and height
159:      * component. <p>
160:      *
161:      * A possible value for the cellSizing parameter of the
162:      * constructor in order to size cells so that each have the same
163:      * width and height. The width is the largest prefered width and
164:      * the height is the largest prefered height of all these child
165:      * components.
166:      */
167:     public static final int MAXPREFERRED = 20;
168: 
169:     /**
170:      * Size all cells so that all in the same row are the same height
171:      * and all in the same column are the same width.<p>
172:      *
173:      * A possible value for the cellSizing parameter of the
174:      * constructor. The width is the largest prefered width of all
175:      * components in the same column and the height is the largest
176:      * prefered height of all components in the same row.
177:      */
178:     public static final int ROWCOLPREFERRED = 21;
179: 
180:     /**
181:      * Size all cells as the same width and height to fit the parent
182:      * component. <p>
183:      *
184:      * A possible value for the cellSizing parameter of the
185:      * constructor in order to size cells so that each has the same
186:      * height and width and are sized to fit their parent.  This
187:      * emulates the sizing done by a standard GridLayout.
188:      */
189:     public static final int FITPARENT = 22;
190: 
191:     int cellSizing = FITPARENT;
192: 
193:     private int fill = BOTH;
194:     private int anchor = WEST;
195: 
196:     /**
197:      * The height of the child component with the largest height
198:      */
199:     protected int largestHeight;
200:     /**
201:      * The width of the child component with the largest width
202:      */
203:     protected int largestWidth;
204:     /**
205:      * The required cell width of each column
206:      */
207:     protected int[] colWidth;
208:     /**
209:      * The required cell height of each row
210:      */
211:     protected int[] rowHeight;
212: 
213:     /**
214:      * Construct a new GridLayout2 with a default of one column per
215:      * component, in a single row.
216:      */
217:     public GridLayout2() {
218: 	this(1, 0, 0, 0);
219:     }
220: 
221:     /**
222:      * Construct a new GridLayout2 with the specified number of rows
223:      * and columns.
224:      *
225:      * @param rows the number of rows in the layout
226:      * @param cols the number of columns in the layout
227:      */
228:     public GridLayout2(int rows, int cols) {
229: 	this(rows, cols, 0, 0);
230:     }
231: 
232:     /**
233:      * Construct a new GridLayout2 with the specified number of rows
234:      * and columns and cell spacing.
235:      *
236:      * @param rows the number of rows in the layout
237:      * @param cols the number of columns in the layout
238:      * @param hgap the horizontal gap between cells
239:      * @param vgap the vertical gap between cells
240:      */
241:     public GridLayout2(int rows, int cols, int hgap, int vgap) {
242: 	if ((rows == 0) && (cols == 0)) {
243: 	    throw new IllegalArgumentException("rows and cols cannot "
244: 					       + "both be zero");
245: 	}
246: 	this.rows = rows;
247: 	this.cols = cols;
248: 	this.h = hgap;
249: 	this.vgap = vgap;
250:     }
251: 
252:     /**
253:      * Construct a new GridLayout2 with the specified number of rows
254:      * and columns and cell sizing scheme.
255:      *
256:      * @param rows the number of rows in the layout
257:      * @param cols the number of columns in the layout
258:      * @param cellSizing the required cell sizing scheme
259:      */
260:     public GridLayout2(int rows, int cols, int cellSizing) {
261: 	this(rows, cols, 0, 0, cellSizing);
262:     }
263: 
264:     /**
265:      * Construct a new GridLayout2 with the specified number of rows
266:      * and columns, cell spacing and cell sizing scheme.
267:      *
268:      * @param rows the number of rows in the layout
269:      * @param cols the number of columns in the layout
270:      * @param hgap the horizontal gap between cells
271:      * @param vgap the vertical gap between cells
272:      * @param cellSizing the required cell sizing scheme
273:      */
274:     public GridLayout2(int rows, int cols, int hgap, int vgap, int cellSizing) {
275:         this(rows, cols, hgap, vgap);
276:         this.cellSizing = cellSizing;
277:     }
278: 
279:     /**
280:      * Construct a new GridLayout2 with the specified number of rows
281:      * and columns, cell spacing, cell sizing scheme and filling
282:      * scheme.
283:      *
284:      * @param rows the number of rows in the layout
285:      * @param cols the number of columns in the layout
286:      * @param hgap the horizontal gap between cells
287:      * @param vgap the vertical gap between cells
288:      * @param cellSizing the required cell sizing scheme
289:      * @param fill the required cell filling scheme
290:      */
291:     public GridLayout2(int rows, int cols, int hgap, int vgap,
292: 		       int cellSizing, int fill)
293:     {
294:         this(rows, cols, hgap, vgap, cellSizing);
295:         this.fill = fill;
296:     }
297: 
298:     /**
299:      * Construct a new GridLayout2 with the specified number of rows
300:      * and columns, cell spacing, cell sizing scheme and component
301:      * sizing and anchoring scheme.
302:      *
303:      * @param rows the number of rows in the layout
304:      * @param cols the number of columns in the layout
305:      * @param hgap the horizontal gap between cells
306:      * @param vgap the vertical gap between cells
307:      * @param cellSizing the required cell sizing scheme
308:      * @param fill the required cell filling scheme
309:      * @param anchor the required anchoring of a child component within its cell
310:      */
311:     public GridLayout2(int rows, int cols, int hgap, int vgap,
312: 		       int cellSizing, int fill, int anchor) {
313:         this(rows, cols, hgap, vgap, cellSizing, fill);
314:         this.anchor = anchor;
315:     }
316: 
317: 
318:     /** 
319:      * Adds the specified component with the specified name to the
320:      * layout. This is included to satisfy the LayoutManager interface
321:      * but is not actually used in this layout implementation.
322:      *
323:      * @param name the name of the component
324:      * @param comp the component to be added
325:      */    
326:     public void addLayoutComponent(String name, Component comp) {
327:     }
328: 
329:     /** 
330:      * Removes the specified component with the specified name from
331:      * the layout. This is included to satisfy the LayoutManager
332:      * interface but is not actually used in this layout
333:      * implementation.<p>
334:      *
335:      * @param comp the name of the component
336:      */    
337:     public void removeLayoutComponent(Component comp) {
338:     }
339: 
340:     /**
341:      * Determines the preferred size of the container argument using
342:      * this grid layout.  The preferred size of a grid layout is
343:      * dependant on the cellSizing scheme.<p>
344:      *
345:      * MAXPREFERRED and FITPARENT use the same formula to calculate
346:      * prefered size.<p>
347:      *
348:      * The prefered width using MAXPREFERRED or FITPARENT is the
349:      * largest preferred width of any of the widths in the container
350:      * times the number of columns, plus the horizontal padding times
351:      * the number of columns plus one, plus the left and right insets
352:      * of the target container.<p>
353:      *
354:      * The preferred height using MAXPREFERRED or FITPARENT is the
355:      * largest preferred height of any of the heights in the container
356:      * times the number of rows, plus the vertical padding times the
357:      * number of rows plus one, plus the top and bottom insets of the
358:      * target container.<p>
359:      *
360:      * The prefered width using ROWCOLPREFERRED is the largest
361:      * preferred is the sum of the widths of of all columns, plus the
362:      * horizontal padding times the number of columns plus one, plus
363:      * the left and right insets of the target container.<p>
364:      *
365:      * The prefered height using ROWCOLPREFERRED is the largest
366:      * preferred is the sum of the heights of of all columns, plus the
367:      * horizontal padding times the number of columns plus one, plus
368:      * the left and right insets of the target container.
369:      *
370:      * @param parent the container to be laid out 
371:      * @return the preferred dimensions to lay out the subcomponents
372:      * of the specified container
373:      */
374:     public Dimension preferredLayoutSize(Container parent) {
375:         synchronized (parent.getTreeLock()) {
376:             int componentCount = parent.getComponentCount();
377:             int actualRows = rows;
378:             int actualCols = cols;
379: 
380:             if (actualRows > 0) {
381:                 actualCols = (componentCount + actualRows - 1) / actualRows;
382:             } else {
383:                 actualRows = (componentCount + actualCols - 1) / actualCols;
384:             }
385: 
386:             colWidth = new int[actualCols];
387:             rowHeight = new int[actualRows];
388:             int largestPreferredWidth = 0;
389:             int largestPreferredHeight = 0;
390: 
391:             for (int c = 0; c < actualCols; ++c) {
392:                 for (int r = 0; r < actualRows; ++r) {
393:                     int i = r * actualCols + c;
394:                     if (i < componentCount) {
395:                         if (parent.getComponent(i).getPreferredSize().getWidth()
396: 			    > colWidth[c]) {
397:                             colWidth[c] =
398: 				(int) parent.getComponent(i)
399: 				    .getPreferredSize().getWidth();
400:                             if (colWidth[c] > largestPreferredWidth)
401: 				largestPreferredWidth = colWidth[c];
402:                         }
403:                         if (parent.getComponent(i)
404: 			    .getPreferredSize().getHeight()
405: 			    > rowHeight[r])
406: 			{
407:                             rowHeight[r] =
408: 				(int) parent.getComponent(i)
409: 				    .getPreferredSize().getHeight();
410:                             if (rowHeight[r] > largestPreferredHeight)
411: 				largestPreferredHeight = rowHeight[r];
412:                         }
413:                     }
414:                 }
415:             }
416: 
417:             return calculateSizes(parent, colWidth, rowHeight,
418: 				  actualRows, actualCols,
419: 				  largestPreferredWidth,
420: 				  largestPreferredHeight);
421:         }
422:     }
