642:     public int getRows() {
643:         return rows;
644:     }
645: 
646:     public void setRows(int rows) {
647: 	if ((rows == 0) && (this.cols == 0)) {
648: 	    throw new IllegalArgumentException("rows and cols cannot "
649: 					       + "both be zero");
650: 	}
651: 	this.rows = rows;
652:     }
653: 
654:     public int getColumns() {
655:         return cols;
656:     }
657: 
658:     public void setCols(int cols) {
659: 	if ((cols == 0) && (this.rows == 0)) {
660: 	    throw new IllegalArgumentException("rows and cols cannot "
661: 					       + "both be zero");
662: 	}
663: 	this.cols = cols;
664:     }
665: 
666:     public int getHgap() {
667:         return h;
668:     }
669: 
670:     public void setHgap(int h) {
671:         this.h = h;
672:     }
673: 
674:     public int getVgap() {
675:         return vgap;
676:     }
677: 
678:     public void setVgap(int vgap) {
679:         this.vgap = vgap;
680:     }
681: }
